window.HT = window.HT || {};
window.HT.CD = {"G00":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Sảnh Hành trình","tieu_de":"Bảy mươi chín năm, một con đường: bản đồ cuộc đời Chủ tịch Hồ Chí Minh","sapo":"Cuộc đời ấy bắt đầu dưới một mái nhà tranh ở Nam Đàn và khép lại bên một ngôi nhà sàn gỗ nhỏ giữa Hà Nội. Ở giữa là bảy mươi chín năm với những bến cảng, thủ đô, nhà tù và hang núi trên nhiều châu lục. Sảnh Hành trình mở tấm bản đồ ấy ra trước mắt người xem: mười bảy vòm cửa là mười bảy nơi chốn có thật, đi hết là đi trọn một đời người.","bia":{"src":"textures/bai/G00_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2297},{"i":1,"tieu_de_bang":"Một đời người, nhiều tên gọi","tieu_de":"Từ Nguyễn Sinh Cung đến Hồ Chí Minh: những cái tên theo suốt hành trình","sapo":"Người mà cả thế giới biết đến với tên Hồ Chí Minh từng được gọi là anh Ba, ông Thầu Chín, ông Vương, ông Ké… Các nhà nghiên cứu đã sưu tầm được hơn một trăm tên gọi, bí danh và bút danh của Người. Mỗi cái tên là một vỏ bọc, một chặng đường, và cũng là một câu chuyện còn nhiều điều để kể.","bia":{"src":"textures/bai/G00_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2034},{"i":2,"tieu_de_bang":"Lời hứa năm 1911 và ngày trở về 1941","tieu_de":"“Tôi sẽ trở về giúp đồng bào”: ba mươi năm giữ một lời hứa","sapo":"Theo Trần Dân Tiên, năm 1911, trước khi xuống tàu, người thanh niên Nguyễn Tất Thành nói với một người bạn rằng anh muốn ra nước ngoài xem người ta làm thế nào, rồi sẽ trở về giúp đồng bào. Ba mươi năm sau, vào ngày mồng 2 Tết Tân Tỵ, lời hứa ấy thành hiện thực bên một cột mốc biên giới Cao Bằng. Giữa hai mốc ấy là cả một hành trình qua nhiều châu lục, với đôi bàn tay trắng và một ý chí không đổi.","bia":{"src":"textures/bai/G00_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2053},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Ba mươi hai mốc son trên hành trình 79 năm","sapo":"Từ làng Hoàng Trù năm 1890 đến Nhà 67 trong khu Phủ Chủ tịch năm 1969, ba mươi hai mốc thời gian dưới đây là xương sống của cả bảo tàng. Có quãng ba mươi năm chỉ lác đác vài mốc, có tháng tám năm 1945 dồn dập những sự kiện đổi thay vận nước. Nhiều mốc trong số ấy nay đã thành ngày lễ của cả dân tộc.","bia":{"src":"textures/bai/G00_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1530},{"i":4,"tieu_de_bang":"Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người","tieu_de":"Năm 1946 qua một gương mặt và một nét bút","sapo":"Người chụp bức ảnh này không để lại tên, nhưng năm 1946 thì để lại rất nhiều dấu vết của vị Chủ tịch 56 tuổi. Có một pho tượng được nặn trong hơn hai mươi buổi sáng ở Bắc Bộ phủ, rồi nằm dưới gầm bàn thờ suốt những năm kháng chiến. Có những bản sắc lệnh còn nguyên nét mực, một trang sổ vàng ở Paris, một tấm ảnh ký tặng người họa sĩ xa quê. Lần theo chữ ký “Hồ Chí Minh”, ta đi lại một năm đầy giông bão.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1957},{"i":5,"tieu_de_bang":"Chân dung Bác trong sách Trang sử mới, 1945","tieu_de":"“Trang sử mới”: gương mặt vị Chủ tịch trên những trang sách mùa thu 1945","sapo":"Mùa thu năm 1945, một cuốn sách mang tên “Trang sử mới” ra đời, in lại bản Tuyên ngôn Độc lập cùng những lời phát biểu tại lễ Độc lập ở Ba Đình. Người làm sách là những nhà văn, nhà thơ, họa sĩ của Hội Văn hóa cứu quốc, vừa bước ra khỏi thời hoạt động bí mật. Trong sách có chân dung vị Chủ tịch nước mà phần đông đồng bào chưa từng gặp mặt. Câu chuyện của trang sách ấy cũng là câu chuyện gương mặt Người đến với nhân dân.","bia":{"src":"textures/ht/ht_anh_portrait_of_ho_chi_minh_from_the_book_trang_su_m.jpg","credit":"Ảnh: Hội Văn hóa cứu quốc Việt Nam · Public domain · Wikimedia Commons"},"so_chu":1949},{"i":6,"tieu_de_bang":"Lời Bác: “Ham muốn tột bậc”","tieu_de":"“Ham muốn tột bậc”: lời tự bạch của một vị Chủ tịch nước","sapo":"Tháng Giêng năm 1946, các nhà báo nước ngoài hỏi vị Chủ tịch nước Việt Nam Dân chủ Cộng hòa về chính con người ông. Người không nói về quyền lực hay dự tính riêng, mà nói về một ham muốn duy nhất, rồi về một ngôi nhà nhỏ bên non xanh nước biếc. Ít ai biết lời tự bạch ấy còn nhắc tới đảng phái, tới kẻ phản quốc và kẻ tham ô. Đọc trọn văn bản, ta hiểu vì sao câu nói ấy sống mãi.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1869}],"do_vat":[]},"G01":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Làng Sen – Kim Liên","tieu_de":"Hai ngôi làng, một cánh đồng: nơi hành trình của Người bắt đầu","sapo":"Năm 1957, về thăm quê sau hơn nửa thế kỷ, vị Chủ tịch nước nhận ra ngay tấm phản trong ngôi nhà cũ đã bị ngắn đi một đoạn. Trí nhớ ấy được nuôi từ mười năm tuổi thơ ở hai ngôi làng nhỏ của Nam Đàn: Hoàng Trù, nơi cậu bé Nguyễn Sinh Cung chào đời, và làng Sen, nơi Nguyễn Tất Thành lớn lên. Gian trưng bày đầu tiên mời bạn đi lại con đường giữa hai làng ấy, từ năm 1890 đến năm 1906.","bia":{"src":"textures/bai/G01_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2297},{"i":1,"tieu_de_bang":"Ngày vinh quy và cái tên Tất Thành","tieu_de":"Năm Tân Sửu 1901: một đám tang, một ngày vinh quy và cái tên Tất Thành","sapo":"Năm 1901, quan Tổng đốc An Tĩnh cho dân hai làng Sen và Hoàng Trù sửa lễ ra tận Vinh đón một vị tân khoa. Người được đón là một nhà nho nghèo vừa mất vợ, và ông khiến bà con bất ngờ khi nói rằng việc mình đỗ đạt chẳng đáng để dân làng nhọc công rước xách. Cũng năm ấy, cậu con trai mười một tuổi của ông bước qua lễ vào làng với một cái tên mới: Nguyễn Tất Thành.","bia":{"src":"textures/bai/G01_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2277},{"i":2,"tieu_de_bang":"Bên chén trà nhà Phó bảng","tieu_de":"Bên chén trà nhà Phó bảng: chuyện nước mất, những con đường cứu nước và một cậu học trò lặng lẽ lắng nghe","sapo":"Có một vị khách của nhà Phó bảng làng Sen, mỗi khi rượu say lại ngâm hai câu thơ cổ nói rằng lập thân bằng văn chương là bậc thấp nhất. Người ấy là Phan Bội Châu. Bên chén trà, chén rượu trong ngôi nhà tranh, các bậc sĩ phu bàn chuyện nước mất, chuyện những con đường cứu nước mới. Và ở một góc nhà, cậu học trò Nguyễn Tất Thành ngồi nghe, ghi nhớ.","bia":{"src":"textures/bai/G01_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2250},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Hoàng Trù đến làng Sen: những mốc đời trước ngày xa quê (1862–1906)","sapo":"Một cậu bé mồ côi được thầy đồ làng bên đón về nuôi, một cô gái giỏi nghề dệt, ba lần vào trường thi Hội, một cái Tết vắng mẹ, một cái tên mới. Câu chuyện tuổi thơ của Người bắt đầu từ trước khi Người ra đời. Những mốc dưới đây giúp bạn lần theo từng bước chân ấy, từ năm 1862 đến ngày cậu học trò Tất Thành rời làng Sen, và cả những ngày Người trở về hơn nửa thế kỷ sau.","bia":{"src":"textures/bai/G01_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1583},{"i":4,"tieu_de_bang":"Cổng làng Hoàng Trù – quê ngoại, nơi Người sinh ra","tieu_de":"Sau cổng làng Hoàng Trù: người thầy đồ làng và nơi cậu bé Nguyễn Sinh Cung chào đời","sapo":"Tấm ảnh chụp ngày 15/8/2016 chỉ ghi lại một chiếc cổng chào làng quê bình dị ở Nam Đàn. Nhưng bước qua chiếc cổng ấy là bước vào câu chuyện của một thầy đồ làng đã đón một cậu học trò mồ côi về nuôi dạy, rồi gả con gái cho. Nhờ tấm lòng của người thầy ấy, làng Hoàng Trù trở thành quê ngoại, nơi Chủ tịch Hồ Chí Minh cất tiếng khóc chào đời.","bia":{"src":"textures/ht/ht_anh_cong_chao_lang_hoang_tru_va_mau_tai_nam_dan_nghe.jpg","credit":"Ảnh: Linhcandng (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1854},{"i":5,"tieu_de_bang":"Khu Di tích Kim Liên, làng Sen","tieu_de":"Khu Di tích Kim Liên: gần bảy mươi năm giữ một làng quê cho ký ức dân tộc","sapo":"Tháng Sáu năm 1957, một ông cụ mặc bộ kaki, đi dép cao su, đứng lặng giữa khoảng sân làng Sen sau hơn nửa thế kỷ xa quê. Ít ai biết rằng từ một năm trước chuyến trở về ấy, những mái nhà tranh của gia đình Người đã bắt đầu được tìm lại, chuộc lại, dựng lại. Tấm ảnh chụp năm 2009 chỉ là một khoảnh khắc trong câu chuyện dài của Khu Di tích Kim Liên – câu chuyện về cách một làng quê được gìn giữ cho cả dân tộc.","bia":{"src":"textures/ht/ht_anh_kim_lien_monuments_park.jpg","credit":"Ảnh: Liftold at Vietnamese Wikipedia · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1974},{"i":6,"tieu_de_bang":"Khu mộ bà Hoàng Thị Loan trên núi Động Tranh","tieu_de":"Ba mươi ba bậc lên núi Động Tranh: hành trình trở về của người mẹ","sapo":"Muốn đến trước ngôi mộ hình bông sen trên núi Động Tranh, người viếng phải bước lên ba mươi ba bậc. Con số ấy không ngẫu nhiên: đó là số tuổi của bà Hoàng Thị Loan khi bà nằm xuống giữa kinh thành Huế. Nhưng để về được sườn núi quê nhà, hài cốt người mẹ đã đi một hành trình kéo dài bốn mươi mốt năm, qua tay những người con từng nếm trải tù đày.","bia":{"src":"textures/ht/ht_anh_khu_mo_ba_hoang_thi_loan.jpg","credit":"Ảnh: David Brewer · CC BY-SA 2.0 · Wikimedia Commons"},"so_chu":1964},{"i":7,"tieu_de_bang":"Hồ sơ về cụ Phó bảng Nguyễn Sinh Sắc","tieu_de":"Một trang hồ sơ thuộc địa: cụ Phó bảng Nguyễn Sinh Sắc trong tầm mắt chính quyền bảo hộ","sapo":"Khoảng năm 1923, chính quyền bảo hộ Pháp ở Trung Kỳ lưu một hồ sơ về một cựu tri huyện đã rời quan trường từ mười ba năm trước. Vì sao một ông đồ già sống bằng nghề bốc thuốc ở phương Nam vẫn nằm trong tầm mắt của nhà cầm quyền? Câu trả lời gắn với người con trai của ông, khi ấy đang mang tên Nguyễn Ái Quốc.","bia":{"src":"textures/ht/ht_anh_records_of_the_government_of_french_indochina_on.jpg","credit":"Ảnh: French protectorate of Annam · Public domain · Wikimedia Commons"},"so_chu":1763},{"i":8,"tieu_de_bang":"Hoa sen – làng Sen, Kim Liên","tieu_de":"Sen vàng, sen hồng, sen trắng: loài hoa đặt tên cho quê hương của Người","sapo":"Có một loài hoa đã đặt tên cho làng quê của Người, rồi lặng lẽ có mặt ở những nơi trang nghiêm nhất trong câu chuyện của gia đình ấy. Nó nằm trong hai chữ Kim Liên, trên ngôi mộ người mẹ ở núi Động Tranh, trên vùng đất Đồng Tháp nơi người cha yên nghỉ. Và giữa Thủ đô Hà Nội, nó nở thành một công trình kiến trúc lưu giữ ký ức về Người.","bia":{"src":"textures/ht/ht_anh_hoa_sen.jpg","credit":"Ảnh: Teyvatism · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1858},{"i":9,"tieu_de_bang":"Nhà tranh năm gian","tieu_de":"Ngôi nhà tranh năm gian: món quà của làng Sen và nửa thế kỷ tìm về nền cũ","sapo":"Ông Phó bảng mới đỗ vốn là người mồ côi, gia cảnh thanh bạch; chính dân làng đã trích đất, mua một ngôi nhà gỗ năm gian đem về dựng tặng. Nửa thế kỷ sau, ngôi nhà ấy đã qua tay nhiều chủ và bị cắt bớt chỉ còn ba gian. Khi được đưa về dựng lại trên nền cũ, nó có một người chỉ dẫn đặc biệt: chính cậu học trò từng sống dưới mái tranh ấy.","bia":{"src":"textures/bai/G01_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1995},{"i":10,"tieu_de_bang":"Bàn thờ và bức hoành phi","tieu_de":"Gian thờ nhà cụ Phó bảng: chiếc bàn thờ tre, bức hoành phi “Ân tứ ninh gia” và tấm biển “Phó bảng”","sapo":"Tháng 6 năm 1957, trở về ngôi nhà tranh ở làng Sen sau hơn nửa thế kỷ xa cách, Chủ tịch Hồ Chí Minh đứng thật lâu trong gian nhà cũ. Người vẫn nhớ chiếc bàn thờ ngày trước không có chân, chỉ gác trên hai thanh gỗ đóng vào cột. Góc nhà nhỏ ấy chứa cả nếp nghĩ của một gia đình nhà nho nghèo: đạo hiếu, lòng biết ơn và niềm tự hào về con đường học vấn. Hãy cùng đọc từng chữ trên hoành phi, câu đối để hiểu những điều được gửi gắm lên bàn thờ.","bia":{"src":"textures/bai/G01_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2187},{"i":11,"tieu_de_bang":"Góc học và bàn trà","tieu_de":"Án thư gian đầu hồi: năm năm học chữ của cậu học trò Tất Thành","sapo":"Một chiếc án thư thấp, bộ ấm chén, giá sách và cánh võng đay. Năm 1957, về thăm nhà sau hơn nửa thế kỷ, Chủ tịch Hồ Chí Minh vẫn chỉ đúng chỗ cha mình ngồi đọc sách, chỗ mắc chiếc võng năm xưa. Từ góc nhà nhỏ ấy, cậu học trò Nguyễn Tất Thành bắt đầu con đường chữ nghĩa, theo cha đi dạy học khắp Nghệ Tĩnh, rồi năm 1905 lần đầu bước vào một lớp học kiểu Pháp.","bia":{"src":"textures/bai/G01_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2175},{"i":12,"tieu_de_bang":"Nhà ngang: bếp, cối, khung cửi","tieu_de":"Nhà ngang ba gian: bếp lửa, cối xay, khung cửi và bốn cây cột trở về","sapo":"Tháng 3 năm 1959, những người làm bảo tàng mang về làng Sen bốn cây cột gỗ cũ. Đó là những gì còn lại của nhà ngang ba gian, nơi gia đình cụ Phó bảng nấu cơm, xay lúa, giã gạo những năm 1901 – 1906. Sau nếp nhà khoa bảng là một nhịp sống cần lao, nơi hạt thóc phải qua tay người mới thành bát cơm.","bia":{"src":"textures/bai/G01_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1860},{"i":13,"tieu_de_bang":"Nhà ba gian ở Hoàng Trù","tieu_de":"Ngôi nhà ba gian ở Hoàng Trù: khung cửi, cánh võng và tiếng khóc chào đời","sapo":"Ngày 9 tháng 12 năm 1961, một cụ già bảy mươi mốt tuổi bước vào ngôi nhà tranh nhỏ ở làng Hoàng Trù, lặng lẽ chạm tay vào chiếc khung cửi, chiếc giường, cánh võng. Đó là lần duy nhất Chủ tịch Hồ Chí Minh trở lại nơi mình cất tiếng khóc chào đời, hơn sáu mươi năm sau ngày rời đi. Ngôi nhà ba gian mái tranh, vách đất ấy là món quà cưới của ông bà ngoại, là nơi người mẹ vừa dệt vải vừa ru con.","bia":{"src":"textures/ht/ht_anh_cong_chao_lang_hoang_tru_va_mau_tai_nam_dan_nghe.jpg","credit":"Ảnh: Linhcandng (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1807},{"i":14,"tieu_de_bang":"Ao sen làng Sen","tieu_de":"Ao sen, cánh đồng và con đường nối quê nội với quê ngoại","sapo":"Tháng 6 năm 1957, giữa đám đông đón Bác ở làng Sen, một cụ già hàng xóm hỏi Người có còn nhớ mình không. Người nhận ra ngay người bạn thuở chăn trâu, thả diều, và hai ông già ôm nhau mà khóc. Những thửa ruộng, ao sen và con đường đất giữa làng Sen với Hoàng Trù là không gian tuổi thơ theo Người suốt hơn nửa thế kỷ xa quê.","bia":{"src":"textures/bai/G01_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1838}],"do_vat":[{"id":"hoanhPhi@-9.8,-6.2","x":-9.75,"y":2.35,"z":-6.16,"loai":"hoanhPhi","ten":"Hoành phi “Ân tứ ninh gia” (恩賜寧家)","tieu_de":"Bốn chữ Hán trên gian thờ"},{"id":"hoanhPhi@-11.6,-6.2","x":-11.6,"y":2.05,"z":-6.16,"loai":"hoanhPhi","ten":"Biển “Phó bảng” (副榜)","tieu_de":"Học vị của chủ nhà"},{"id":"cauDoi@-11.0,-4.7","x":-11,"y":0.65,"z":-4.66,"loai":"cauDoi","ten":"Câu đối “Thiên địa quân thân sư” (天地君親師)","tieu_de":"Năm điều tôn kính của nhà nho"},{"id":"cauDoi@-8.5,-4.7","x":-8.5,"y":0.65,"z":-4.66,"loai":"cauDoi","ten":"Câu đối “Tổ công tông đức hậu” (祖功宗德厚)","tieu_de":"Công tổ, đức tông"},{"id":"altar@-9.8,-5.9","x":-9.75,"y":0.3,"z":-5.9,"loai":"altar","ten":"Bàn thờ gia tiên nhà cụ Phó bảng","tieu_de":"Gian thờ giữa ngôi nhà năm gian"},{"id":"phan@-7.2,-3.5","x":-7.25,"y":0.3,"z":-3.5,"loai":"phan","ten":"Bộ phản gỗ tiếp khách","tieu_de":"Chỗ ngồi của những vị khách yêu nước"},{"id":"table@-1.6,-5.6","x":-1.6,"y":0.3,"z":-5.6,"loai":"table","ten":"Án thư ở góc học","tieu_de":"Lớp học bên cha"},{"id":"pestle@10.0,-0.7","x":10,"y":0.21,"z":-0.7,"loai":"pestle","ten":"Cối giã gạo trong nhà ngang","tieu_de":"Tiếng chày trong nhà ngang"},{"id":"loom@45.5,-5.7","x":45.55,"y":0.24,"z":-5.7,"loai":"loom","ten":"Khung cửi của bà Hoàng Thị Loan","tieu_de":"Tiếng thoi đưa nuôi chồng con ăn học"},{"id":"phan@50.3,-6.2","x":50.3,"y":0.24,"z":-6.2,"loai":"phan","ten":"Chiếc giường gỗ ở nhà Hoàng Trù","tieu_de":"Nơi bắt đầu một cuộc đời"}]},"G02":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Huế – Kinh thành và trường Quốc Học","tieu_de":"Hơn tám năm ở kinh đô: nơi cậu bé làng Sen nhìn thấu bộ mặt chế độ bảo hộ","sapo":"Cuối năm 1895, một gia đình nhà nho nghèo xứ Nghệ đi bộ nhiều ngày vào kinh, hai đứa trẻ ngồi trong đôi quang gánh. Kinh đô ấy có cung điện, có Kỳ Đài, có nhà vua, nhưng quyền lực thật lại nằm ở một tòa nhà bên kia sông. Qua hai lần sống ở Huế, cậu bé làng Sen mất mẹ, đổi tên, học chữ Tây và lần đầu đứng giữa đoàn người đòi giảm sưu thuế. Gian trưng bày này mở ra từng lát cắt của những năm tháng ấy.","bia":{"src":"textures/bai/G02_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2590},{"i":1,"tieu_de_bang":"Mất mẹ giữa kinh thành (1901)","tieu_de":"Tháng Chạp năm Canh Tý: cậu bé mười một tuổi bồng em đi xin sữa giữa kinh thành","sapo":"Ngày 22 tháng Chạp năm Canh Tý, tức 10/2/1901, khi kinh đô đang sửa soạn đón Tết, một người mẹ ba mươi ba tuổi trút hơi thở cuối cùng trong căn nhà nhỏ ở Thành Nội. Chồng và con trưởng đang ở xa. Bên người mẹ chỉ còn cậu con trai mười một tuổi và đứa em đỏ hỏn đói sữa. Câu chuyện ấy, và hành trình hơn một thế kỷ của nấm mộ người mẹ, bắt đầu từ đây.","bia":{"src":"textures/bai/G02_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1940},{"i":2,"tieu_de_bang":"Người phiên dịch cho đoàn nông dân (1908)","tieu_de":"Buổi sáng trước Tòa Khâm sứ: người học trò lật ngược chiếc nón, đứng ra làm thông ngôn cho dân","sapo":"Sáng 11/4/1908, khoảng một nghìn nông dân Thừa Thiên vây quanh Tòa Khâm sứ Trung Kỳ, đòi giảm thuế. Họ có lý lẽ, nhưng không nói được thứ tiếng của những người đang cai trị mình. Một học trò trường Pháp – Việt sắp tròn mười tám tuổi đã lật ngược chiếc nón, bước lên đứng giữa hai bên. Từ buổi sáng ấy, tên anh bắt đầu có trong hồ sơ theo dõi của mật thám Pháp.","bia":{"src":"textures/bai/G02_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2315},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ làng Sen đến Bến Nhà Rồng: những mốc thời gian gắn với kinh đô Huế","sapo":"Hai lần vào kinh, cách nhau năm năm ở quê nhà, rồi một hành trình xuôi về phương Nam. Xếp các mốc theo thứ tự, ta thấy Huế chiếm trọn tuổi thơ và tuổi thiếu niên của Người. Cũng từ những mốc ấy, ta thấy tư liệu lưu trữ đã giúp đính chính những điều từng được kể lại suốt nhiều năm.","bia":{"src":"textures/bai/G02_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1648},{"i":4,"tieu_de_bang":"Lớp học Trường Quốc Học Huế đầu thế kỷ XX","tieu_de":"Bên trong lớp học Quốc Học: người học trò Nguyễn Sinh Côn và ngôi trường Pháp – Việt","sapo":"Một văn thư hành chính đề ngày 7/8/1908 nhắc đến một cái tên ít người biết: Nguyễn Sinh Côn, quê Nghệ An. Người học trò ấy về sau là Chủ tịch Hồ Chí Minh. Tấm ảnh một lớp học Quốc Học công bố năm 1913 mở cửa vào thế giới mà cậu học trò mười tám tuổi từng sống: những giờ tiếng Pháp, những người thầy yêu nước, và một câu hỏi day dứt về nước Pháp thật sự.","bia":{"src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_2e_annee_complementaire.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1956},{"i":5,"tieu_de_bang":"Giờ thể dục ở Trường Quốc Học Huế","tieu_de":"Giờ thể dục giữa sân Quốc Học: từ một môn học lạ lẫm đến lời kêu gọi “Dân cường thì quốc thịnh”","sapo":"Học trò kinh đô xưa quen ngồi bên án thư, cúi đầu trên trang sách thánh hiền. Vậy mà trong một tấm ảnh công bố năm 1913, học sinh Quốc Học lại đang ra sân trong giờ thể dục. Môn học lạ lẫm ấy mở đầu cho một câu chuyện dài. Gần bốn mươi năm sau khi rời ghế Quốc Học, người học trò năm nào kêu gọi cả nước mỗi sáng tập thể dục.","bia":{"src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_cours_de_gymnastique.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1843},{"i":6,"tieu_de_bang":"Trường Quốc Học Huế bên bờ sông Hương","tieu_de":"Sắc đỏ bên dòng Hương: hơn một thế kỷ của ngôi trường nơi những người làm nên lịch sử từng ngồi học","sapo":"Một buổi chiều tháng Giêng năm 2008, tác giả Lưu Ly bấm máy trước ngôi trường sắc đỏ bên bờ nam sông Hương. Tấm ảnh bình dị ấy ghi lại một địa chỉ hiếm có. Ở đây từng có mặt người học trò Nguyễn Tất Thành, rồi hai vị Tổng Bí thư, một Thủ tướng, một Đại tướng. Đằng sau khung hình là hơn một thế kỷ sông nước, lớp học và những cuộc ra đi.","bia":{"src":"textures/ht/ht_anh_quoc_hoc_hue.jpg","credit":"Ảnh: Lưu Ly · Public domain · Wikimedia Commons"},"so_chu":1808},{"i":7,"tieu_de_bang":"Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học","tieu_de":"Người học trò trở về sân trường xưa: bức tượng Nguyễn Tất Thành giữa sân Quốc Học","sapo":"Người học trò ấy chỉ ngồi ở Quốc Học chưa trọn một năm, rời trường không mang theo tấm bằng nào. Hơn tám mươi năm sau, Người trở lại giữa sân trường trong dáng hình một pho tượng, đúng vào năm kỷ niệm một trăm năm ngày sinh của Người. Câu chuyện của bức tượng cũng là câu chuyện về một câu hỏi lớn: học để làm gì?","bia":{"src":"textures/ht/ht_anh_tuong_nguyen_tat_thanh_tai_quoc_hoc_hue.jpg","credit":"Ảnh: Lưu Ly at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},"so_chu":1866},{"i":8,"tieu_de_bang":"Cổng Trường Quốc Học","tieu_de":"Cổng Quốc Học: năm dáng hình của một cánh cổng, và người học trò bước qua năm 1908","sapo":"Ai đến Huế cũng nhận ra Quốc Học từ xa nhờ cánh cổng hai tầng mái ngói đỏ bên đường Lê Lợi. Nhưng cánh cổng người học trò Nguyễn Sinh Côn bước qua năm 1908 không phải cánh cổng hôm nay. Hơn một thế kỷ, cổng trường đã mang ít nhất năm dáng hình, từng đề chữ Hán, chữ Pháp, rồi có lúc bị đục mất chữ. Lần theo cánh cổng ấy là lần theo lịch sử một ngôi trường và một người học trò.","bia":{"src":"textures/bai/G02_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2178},{"i":9,"tieu_de_bang":"Phong trào chống sưu thuế 1908","tieu_de":"Mùa xuân 1908: những người “đồng bào cắt tóc” kéo về kinh đô","sapo":"Họ đi tay không, tóc cắt ngắn, gọi nhau là “đồng bào”. Mùa xuân năm 1908, nông dân Trung Kỳ từ Quảng Nam đến Thừa Thiên lần lượt kéo đến các tòa sứ đòi giảm sưu, giảm thuế. Một bản báo cáo mật của viên Công sứ Pháp ở Huế, mới được dịch và công bố, cho phép dựng lại từng ngày biến động ở kinh đô. Trong đám đông ấy có một học trò mười tám tuổi tên Nguyễn Tất Thành.","bia":{"src":"textures/bai/G02_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2067},{"i":10,"tieu_de_bang":"Cầu Trường Tiền và sông Hương","tieu_de":"Cầu Trường Tiền: sáu nhịp thép, bốn lần đổi tên, một dòng sông chứng nhân","sapo":"Tháng 3/1897, muốn vào gặp vua Thành Thái, Toàn quyền Đông Dương Paul Doumer vẫn phải vượt sông Hương bằng tàu. Ba năm sau, một cây cầu thép sáu nhịp vắt ngang dòng sông, mang niên hiệu nhà vua. Cây cầu ấy từng bị bão quật gãy, hai lần bị đánh sập, bốn lần đổi tên. Và mùa xuân năm 1908, chính trên mặt cầu, những đoàn nông dân chống thuế đã tụ lại giữa kinh đô.","bia":{"src":"textures/bai/G02_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1939}],"do_vat":[{"id":"blackboard@0.0,42.9","x":0,"y":1.65,"z":42.85,"loai":"blackboard","ten":"Bảng đen lớp học Quốc Học","tieu_de":"Tấm bảng của một ngôi trường Pháp – Việt"},{"id":"schoolDesk@1.5,40.0","x":1.5,"y":0.75,"z":40,"loai":"schoolDesk","ten":"Bàn học trò Quốc Học","tieu_de":"Chưa đầy một năm trên ghế nhà trường"},{"id":"schoolDesk@-1.6,40.0","x":-1.6,"y":0.75,"z":40,"loai":"schoolDesk","ten":"Bàn học trò Quốc Học","tieu_de":"Từ chữ Hán sang chữ Pháp"},{"id":"schoolDesk@4.6,40.0","x":4.6,"y":0.75,"z":40,"loai":"schoolDesk","ten":"Bàn học trò Quốc Học","tieu_de":"Lời tương truyền của cụ Phó bảng về chốn quan trường"}]},"G03":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Phan Thiết – Trường Dục Thanh","tieu_de":"Phan Thiết, mùa thu 1910: khi người thanh niên Nguyễn Tất Thành làm thầy giáo bên dòng Cà Ty","sapo":"Trên bản đồ hành trình của Chủ tịch Hồ Chí Minh, Phan Thiết chỉ là một chấm nhỏ, và thời gian Người ở đây chưa đầy nửa năm. Nhưng đó là chặng dừng chân dài cuối cùng trên đất Việt trước khi người thanh niên hai mươi tuổi xuống tàu ra đi. Vì sao anh dừng lại ở thị xã nước mắm bên dòng Cà Ty, và ở ngôi trường nhỏ ấy anh đã thấy những gì?","bia":{"src":"textures/bai/G03_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2219},{"i":1,"tieu_de_bang":"Một mình đi về phương Nam","tieu_de":"Từ Bình Khê đến Phan Thiết: chặng đường phương Nam của người thanh niên hai mươi tuổi","sapo":"Năm 1910, người cha vừa mất chức quan, còn người con trai không quay về Huế. Nguyễn Tất Thành một mình đi tiếp về phía Nam, qua những vùng đất lần đầu đặt chân tới, với vài mối quen biết của cha làm chỗ dựa. Ở làng biển Duồng, một ngôi chùa nhỏ và một nhà nho yêu nước đã mở cho anh cánh cửa vào Phan Thiết.","bia":{"src":"textures/bai/G03_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2001},{"i":2,"tieu_de_bang":"Hội buôn nước mắm nuôi một ngôi trường","tieu_de":"Liên Thành: khi nghề nước mắm nuôi một ngôi trường yêu nước","sapo":"Năm 1906, ở Phan Thiết, sáu nhà nho làm một việc khiến người đương thời lấy làm lạ: họ lập hội đi buôn nước mắm. Đồng tiền từ những thùng nước mắm ấy nuôi một thư xã, một ngôi trường, và bốn năm sau mở cho người thanh niên Nguyễn Tất Thành một lớp học để đứng. Hội buôn ấy còn sống lâu hơn cả ngôi trường, qua gần bảy mươi năm thăng trầm của đất nước.","bia":{"src":"textures/bai/G03_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2053},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Ngọa Du Sào đến bến Nhà Rồng: dòng thời gian của Trường Dục Thanh","sapo":"Câu chuyện Dục Thanh bắt đầu từ trước khi thầy Thành ra đời, và đến nay vẫn chưa khép lại. Ba mươi mốt mốc dưới đây nối lịch sử một mảnh vườn, một hội buôn và một ngôi trường với hành trình của người thanh niên Nguyễn Tất Thành. Đọc chúng theo thứ tự, ta sẽ thấy vì sao một thị xã nhỏ ven biển lại trở thành chặng dừng chân cuối cùng của Người trên đất Việt trước chuyến đi xa.","bia":{"src":"textures/bai/G03_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1574},{"i":4,"tieu_de_bang":"Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ","tieu_de":"Nếp nhà gỗ bên sông Cà Ty: hành trình hơn một thế kỷ của Trường Dục Thanh","sapo":"Nhìn qua tấm ảnh, đó chỉ là mấy nếp nhà gỗ mái ngói giữa lòng Phan Thiết. Nhưng ngôi trường ấy chỉ hoạt động khoảng năm năm, rồi có lúc chỉ còn lại một ngôi nhà nhỏ, một nhà thờ họ, một cây khế và một chiếc giếng. Nó được dựng lại nhờ trí nhớ của bốn học trò cũ của thầy Thành. Câu chuyện của những nếp nhà gỗ ấy dài hơn một thế kỷ.","bia":{"src":"textures/ht/ht_anh_truong_duc_thanh.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1967},{"i":5,"tieu_de_bang":"Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp","tieu_de":"Một ngày ở lớp nhì Dục Thanh: thầy Thành dạy gì và dạy thế nào?","sapo":"Sáu giờ sáng, giờ học ở Trường Dục Thanh đã bắt đầu, sau buổi tập thể dục ngoài sân. Trong ngôi nhà gỗ chung của cả bốn lớp, một thầy giáo hai mươi tuổi giảng chậm những bài khó và kiên nhẫn hỏi lại từng trò. Mấy chục năm sau, học trò cũ vẫn nhớ từng nét trong cách dạy ấy. Một ngày học ở Dục Thanh năm 1910 diễn ra như thế nào?","bia":{"src":"textures/ht/ht_anh_lop_hoc_trong_duc_thanh.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1738},{"i":6,"tieu_de_bang":"Gian nhà nơi Bác Hồ dạy học ở Dục Thanh","tieu_de":"Từ bục giảng Dục Thanh đến sự nghiệp “trồng người”","sapo":"Tấm ảnh chụp một ngày cuối tháng 8/2016 cho thấy gian nhà gỗ nơi thầy Thành từng đứng lớp. Người thầy trẻ ấy chỉ dạy ở đây chưa đầy nửa năm. Nhưng việc dạy người thì Người theo đuổi suốt đời: từ lớp huấn luyện ở Quảng Châu, lớp học ở Pác Bó, đến chiến dịch diệt giặc dốt của cả một dân tộc vừa giành độc lập.","bia":{"src":"textures/ht/ht_anh_truong_duc_thanh_noi_bac_ho_day_o_truong_duc_tha.jpg","credit":"Ảnh: Phương Huy · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1639},{"i":7,"tieu_de_bang":"Giếng nước trong sân Trường Dục Thanh","tieu_de":"Chiếc giếng, cây khế và thói quen trồng cây suốt đời của Bác","sapo":"Chiếc giếng gạch sâu chừng bốn mét trong sân Trường Dục Thanh đã hơn một trăm tuổi. Năm 1910, thầy giáo Thành thường ra đây múc nước, tưới cho cây khế của bà Nguyễn Thông. Gần nửa thế kỷ sau, người thầy ấy, khi đã là Chủ tịch nước, phát động cả miền Bắc đón Tết bằng cách trồng cây.","bia":{"src":"textures/ht/ht_anh_gieng_truong_duc_thanh.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1730},{"i":8,"tieu_de_bang":"Sông Cà Ty, Phan Thiết","tieu_de":"Bên dòng Cà Ty: nghề biển, xóm chài và những buổi học ngoài lớp của thầy Thành","sapo":"Con sông chảy qua lòng Phan Thiết đã nuôi nghề biển, nghề nước mắm, và nuôi cả một ngôi trường yêu nước dựng bên bờ nó. Năm 1910, người thầy giáo hai mươi tuổi của ngôi trường ấy thường dắt học trò ra khỏi lớp, tới tận những xóm chài nghèo. Thầy kể chuyện Hai Bà Trưng, Bà Triệu giữa cảnh sống vất vả của ngư dân. Vài tháng sau, cũng từ miền cửa sông này, người thầy lên đường vào Sài Gòn rồi ra biển lớn.","bia":{"src":"textures/ht/ht_anh_song_ca_ty.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1863},{"i":9,"tieu_de_bang":"Lớp học Trường Dục Thanh","tieu_de":"Lớp học gỗ 137 mét vuông: đi một vòng quanh lớp của thầy Thành","sapo":"Hai tấm bảng đen, hai mươi mốt bộ bàn ghế chia ba dãy, một bộ trường kỷ cho bảy thầy giáo: lớp học Dục Thanh không có gì cầu kỳ. Nhưng đặt vào năm 1910, khi phần đông trẻ em được đi học ở Trung Kỳ vẫn ngồi chiếu học chữ Nho, mỗi món đồ ấy là một lựa chọn mới. Hãy đi một vòng quanh lớp học, từ mái ngói xuống nền gạch, để thấy một ngôi trường Duy Tân được bài trí thế nào và vì sao.","bia":{"src":"textures/bai/G03_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1856},{"i":10,"tieu_de_bang":"Nhà Ngọa Du Sào","tieu_de":"Ngọa Du Sào – “cái tổ để nằm mà ngao du” và thư viện nhỏ của thầy Thành","sapo":"Trong khuôn viên Trường Dục Thanh có một ngôi nhà ba gian nhiều tuổi hơn cả ngôi trường. Người dựng nó là một nhà thơ đã rời quê Nam Kỳ khi giặc tới, và đặt cho nó cái tên gợi một điển cố xưa. Ba mươi năm sau, dưới mái nhà ấy, một thầy giáo hai mươi tuổi lui tới đọc sách, làm thơ, bàn chuyện thời cuộc.","bia":{"src":"textures/bai/G03_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1802},{"i":11,"tieu_de_bang":"Giếng nước","tieu_de":"Giếng gạch giữa sân và nếp sống nội trú của thầy trò Dục Thanh","sapo":"Ở Dục Thanh, chiếc giếng gạch giữa sân là hiện vật gần với đời thường của thầy Thành hơn cả. Quanh nó là cả một nếp sống nội trú: thầy trò cùng ở, cùng dậy sớm, cùng lo liệu việc chung. Ở một thị xã nắng gió bên cửa biển, nơi khoảng hai mươi năm sau mới có tháp nước, giếng nước ngọt là thứ quý. Câu chuyện của chiếc giếng vì thế cũng là câu chuyện về một lối sống giản dị theo Người suốt đời.","bia":{"src":"textures/bai/G03_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1791}],"do_vat":[{"id":"schoolDesk@-3.2,-2.2","x":-3.2,"y":0.71,"z":-2.25,"loai":"schoolDesk","ten":"Bàn ghế học trò","tieu_de":"Hai mươi mốt bộ bàn ghế của lớp học xưa"},{"id":"schoolDesk@-3.2,-4.0","x":-3.2,"y":0.71,"z":-4,"loai":"schoolDesk","ten":"Chỗ ngồi của học trò lớp nhì","tieu_de":"Thầy hỏi lại: “Các trò đã hiểu chưa?”"},{"id":"schoolDesk@5.5,-0.5","x":5.5,"y":0.71,"z":-0.5,"loai":"schoolDesk","ten":"Bàn học cuối lớp","tieu_de":"Những buổi học ngoài lớp"},{"id":"table@-5.1,-2.3","x":-5.1,"y":0.96,"z":-2.3,"loai":"table","ten":"Bàn thầy giáo","tieu_de":"Người thầy hai mươi tuổi"},{"id":"vintage_oil_lamp@-5.1,-1.9","x":-5.1,"y":1.74,"z":-1.95,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"Ánh đèn của những buổi soạn bài"},{"id":"blackboard@-6.3,-3.4","x":-6.27,"y":1.66,"z":-3.4,"loai":"blackboard","ten":"Bảng đen","tieu_de":"Chữ Quốc ngữ – môn học chính"},{"id":"blackboard@-6.3,-0.6","x":-6.27,"y":1.66,"z":-0.6,"loai":"blackboard","ten":"Bảng đen thứ hai","tieu_de":"Một chương trình học rất mới"},{"id":"phan@23.3,-11.9","x":23.34,"y":0.66,"z":-11.88,"loai":"phan","ten":"Phản gỗ","tieu_de":"Góc nhà nho trong Ngọa Du Sào"},{"id":"table@25.6,-11.5","x":25.55,"y":0.66,"z":-11.5,"loai":"table","ten":"Bàn đọc sách","tieu_de":"Thư viện nhỏ của một ngôi trường Duy Tân"},{"id":"well@-9.0,10.0","x":-9,"y":0.29,"z":10,"loai":"well","ten":"Giếng nước","tieu_de":"Chiếc giếng gạch và cây khế"}]},"G04":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Sài Gòn – Bến Nhà Rồng","tieu_de":"Sài Gòn 1911: bốn tháng mở cánh cửa ra biển lớn của người thanh niên Nguyễn Tất Thành","sapo":"Trưa ngày 5/6/1911, một con tàu buôn Pháp rời Sài Gòn, mang theo một phụ bếp vừa nhận việc hai hôm trước. Không ai trên tàu biết người thanh niên hai mươi mốt tuổi ấy vừa khép lại bốn tháng chuẩn bị lặng lẽ ở thành phố cảng. Vì sao lại là Sài Gòn, vì sao lại là phương Tây, và anh đã mang theo những gì? Gian trưng bày này mở ra từ những câu hỏi ấy.","bia":{"src":"textures/bai/G04_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2415},{"i":1,"tieu_de_bang":"Lời rủ ra đi và người bạn tên Lê","tieu_de":"“Anh có yêu nước không?” – cuộc trò chuyện bí mật ở Sài Gòn năm 1911","sapo":"Trước khi bước lên tàu, người thanh niên ấy từng rủ một người bạn cùng đi. Anh không nói ngay dự định, mà hỏi trước hai câu để thử lòng. Khi bạn hỏi lấy đâu ra tiền, anh chỉ giơ hai bàn tay. Câu chuyện được ghi lại trong sách của Trần Dân Tiên cho thấy chuyến đi năm 1911 đã được chuẩn bị bằng cả sự thận trọng lẫn một quyết tâm hiếm có.","bia":{"src":"textures/bai/G04_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2072},{"i":2,"tieu_de_bang":"Người phụ bếp Văn Ba","tieu_de":"Người phụ bếp tên Ba: từ bốn giờ sáng dưới bếp tàu đến quán cà phê ở Marseille","sapo":"Người cùng tàu nhớ anh chỉ lĩnh mười quan; các nhà nghiên cứu ghi bốn mươi lăm franc mỗi tháng. Dù con số nào đúng, đó vẫn là một đồng lương ít ỏi. Người phụ bếp trẻ làm từ bốn giờ sáng đến chín giờ tối, rồi thức tới khuya để đọc và viết. Ba mươi mốt ngày sau, ở Marseille, lần đầu tiên anh được một người Pháp gọi bằng “ông”.","bia":{"src":"textures/bai/G04_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2070},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Nhà Rồng đến Marseille: những mốc thời gian của chuyến đi năm 1911","sapo":"Hai ngày giữa lúc nhận việc và lúc nhổ neo. Ba mươi mốt ngày từ Sài Gòn đến Marseille. Bốn mươi chín năm giữa hai ngày mồng 5 tháng 6. Đặt các mốc thời gian cạnh nhau, ta thấy những con số cũng biết kể chuyện.","bia":{"src":"textures/bai/G04_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1511},{"i":4,"tieu_de_bang":"Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX","tieu_de":"Tòa nhà của hãng tàu “Hoàng đế”: câu chuyện đằng sau tấm ảnh trụ sở Messageries Maritimes","sapo":"Dưới tấm ảnh cũ chỉ có một dòng chữ Pháp khô khan: “Saïgon – Direction de la Cie des Messageries Maritimes”. Người Sài Gòn chưa bao giờ gọi tòa nhà bằng cái tên dài ấy; họ gọi nó là Nhà Rồng. Đằng sau cái tên dân gian là câu chuyện về một hãng tàu mang danh “Hoàng đế”, đặt chân lên Sài Gòn cùng lúc với tiếng súng xâm lược. Hơn một thế kỷ sau, chính tòa nhà ấy lại trở thành nơi tưởng niệm người đã dành cả đời đấu tranh xóa bỏ ách thuộc địa.","bia":{"src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1926},{"i":5,"tieu_de_bang":"Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông","tieu_de":"Mũi Tán Dóc và con tàu Paul-Lecat: tấm bưu ảnh kể chuyện thương cảng Sài Gòn","sapo":"Trên tấm bưu ảnh cũ, một con tàu viễn dương buông neo giữa dòng sông Sài Gòn, trước mũi đất mà dân Sài Gòn xưa gọi đùa là “Mũi Tán Dóc”. Con tàu ấy được hạ thủy ở Pháp vào mùa xuân năm 1911, đúng lúc Nguyễn Tất Thành đang học nghề ở Sài Gòn. Nó không phải con tàu đưa anh đi. Nhưng đọc kỹ, tấm ảnh kể được rất nhiều về thương cảng mà người thanh niên ấy từng ngày ngày lui tới.","bia":{"src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},"so_chu":1928},{"i":6,"tieu_de_bang":"Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh","tieu_de":"Nhiều lần đổi chủ, một sứ mệnh mới: tòa Nhà Rồng trở thành Bảo tàng Hồ Chí Minh","sapo":"Tấm ảnh chụp ngày 29/9/2013 ghi lại tòa Nhà Rồng khi đã làm bảo tàng được gần hai mươi năm. Ít ai ngờ trước đó, tòa nhà từng qua tay một hãng tàu Pháp, chính quyền Sài Gòn cũ, quân đội Mỹ và ngành đường biển Việt Nam. Từ năm 1979, nơi đây kể câu chuyện về người thanh niên đã ra đi từ bến cảng này. Năm 2026, bảo tàng lại tạm đóng cửa để chuẩn bị cho một diện mạo mới.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_museum_saigon.jpg","credit":"Ảnh: Gary Todd · CC0 · Wikimedia Commons"},"so_chu":1830},{"i":7,"tieu_de_bang":"Tượng Nguyễn Tất Thành tại Bến Nhà Rồng","tieu_de":"Pho tượng người thanh niên hai mươi mốt tuổi bên bến sông Sài Gòn","sapo":"Hình ảnh quen thuộc nhất về Bác Hồ là một ông cụ râu tóc bạc, hiền từ. Ở Bến Nhà Rồng thì khác: giữa sân bảo tàng là một người thanh niên, hướng mặt về phía dòng sông. Pho tượng đồng cao 3,3 mét ấy gợi lại khoảnh khắc trước lúc lên đường của Nguyễn Tất Thành, khi chưa ai biết đến tên anh.","bia":{"src":"textures/ht/ht_anh_tuong_nguyen_ai_quoc_nguyen_tat_thanh_nha_tuong_.jpg","credit":"Ảnh: vi:User:TDA · Public domain · Wikimedia Commons"},"so_chu":1668},{"i":8,"tieu_de_bang":"Nhà Rồng","tieu_de":"Nhà Rồng: đôi rồng Việt trên nóc một tòa nhà Pháp và hơn một thế kỷ rưỡi đổi chủ","sapo":"Giữa năm 1862, khi Sài Gòn vừa bị cắt về tay người Pháp, một hãng tàu mang danh “Vận tải Hoàng đế” dựng trụ sở bên rạch Bến Nghé, rồi đắp lên nóc hai con rồng theo lối trang trí đình chùa Việt. Người dân không gọi tên hãng, họ gọi theo đôi rồng. Hơn một trăm sáu mươi năm, tòa nhà đổi chủ nhiều lần, đôi rồng cũng đổi dáng, chỉ cái tên Nhà Rồng là ở lại.","bia":{"src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":2007},{"i":9,"tieu_de_bang":"Tàu Amiral Latouche-Tréville","tieu_de":"Amiral Latouche-Tréville: chân dung con tàu buôn của hãng Năm Sao","sapo":"Nó dài gần một trăm hai mươi mét, chạy bằng hơi nước và mang tên một vị đô đốc từng đẩy lui Nelson. Suốt hai mươi lăm năm, nó chỉ là một trong nhiều con tàu buôn nối nước Pháp với Đông Dương. Thế nhưng chuyến rời Sài Gòn trưa 5/6/1911, với một người phụ bếp mới nhận việc tên Văn Ba, đã đưa tên con tàu vào lịch sử Việt Nam.","bia":{"src":"textures/bai/G04_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1824},{"i":10,"tieu_de_bang":"Hai bàn tay","tieu_de":"Hai bàn tay: những nghề Người đã làm suốt mười hai năm đi tìm đường cứu nước","sapo":"Ở Sài Gòn năm 1911, khi bạn hỏi lấy đâu ra tiền để đi, người thanh niên chỉ giơ hai bàn tay. Lời hứa ấy được giữ trọn trong hơn một thập kỷ sau đó: dưới bếp tàu, giữa tuyết lạnh và lò than ở London, trong gian bếp khách sạn, bên bàn sửa ảnh ở Paris. Bảng hiện vật này đi theo đôi bàn tay ấy qua từng nghề, từng thành phố.","bia":{"src":"textures/bai/G04_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2071},{"i":11,"tieu_de_bang":"Bến cảng Sài Gòn","tieu_de":"Bến cảng Sài Gòn năm 1911 – và câu hỏi: con tàu đã rời bến ở đâu?","sapo":"Mỗi dịp tháng Sáu, Bến Nhà Rồng được nhắc đến như nơi người thanh niên Nguyễn Tất Thành xuống tàu ra đi. Nhưng một tài liệu của thương cảng Sài Gòn in năm 1912 lại gợi ý một cầu tàu khác, ở bên kia cửa rạch Bến Nghé. Đi tìm lời giải cho câu hỏi nhỏ ấy, ta gặp lại cả một bến cảng thuộc địa: cầu tàu, kho hàng, cột neo, và những con người lao động quanh đó.","bia":{"src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},"so_chu":2038}],"do_vat":[{"id":"caged_hanging_light@-2.8,7.2","x":-2.8,"y":5.1,"z":7.22,"loai":"caged_hanging_light","ten":"Đèn treo kho cảng","tieu_de":"Ánh đèn bên những dãy kho"},{"id":"caged_hanging_light@-2.8,-7.2","x":-2.8,"y":5.1,"z":-7.22,"loai":"caged_hanging_light","ten":"Đèn xưởng","tieu_de":"Nhớ xưởng học nghề trường Bá Nghệ"},{"id":"caged_hanging_light@-2.8,-14.1","x":-2.8,"y":5.1,"z":-14.13,"loai":"caged_hanging_light","ten":"Đèn khoang tàu","tieu_de":"Những ngày làm phụ bếp dưới khoang tàu"}]},"G05":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Nước Pháp – Paris","tieu_de":"Mười hai năm trên đất Pháp: nơi người phụ bếp Văn Ba trở thành Nguyễn Ái Quốc","sapo":"Mùa hè năm 1911, một người phụ bếp hai mươi mốt tuổi bước xuống bến Marseille với hai bàn tay trắng. Mùa hè năm 1923, một người thợ ảnh bị mật thám bám theo từng giờ lặng lẽ rời Paris, để lại cho bạn bè một lá thư: câu trả lời đã rõ ràng, phải trở về nước. Giữa hai chuyến đi ấy là mười hai năm đổi thay cả một đời người. Gian trưng bày này mời bạn đi lại con đường đó.","bia":{"src":"textures/bai/G05_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2594},{"i":1,"tieu_de_bang":"Lá đơn xin học năm 1911","tieu_de":"Lá đơn gửi Tổng thống Pháp: khi người phụ bếp gõ cửa Trường Thuộc địa","sapo":"Ngày 15/9/1911, tại Marseille, một người phụ bếp trên tàu buôn viết bằng tiếng Pháp gửi Tổng thống Cộng hòa Pháp, xin được vào học Trường Thuộc địa. Lá đơn không mở được cánh cửa nào. Nhưng sổ lương của con tàu, công văn của Khâm sứ Trung Kỳ và những lá thư ký tên Paul Tất Thành còn lưu lại cho thấy khát vọng học tập của người thanh niên ấy bền bỉ đến mức nào.","bia":{"src":"textures/ht/ht_anh_23_10_11_marseille_vue_du_port_btv1b6917711h.jpg","credit":"Ảnh: Agence Rol. Agence photographique (comma · Public domain · Wikimedia Commons"},"so_chu":2192},{"i":2,"tieu_de_bang":"Thư gửi ngài Bộ trưởng Thuộc địa","tieu_de":"Thư ngỏ gửi Albert Sarraut: người bị theo dõi tự công bố thời khóa biểu","sapo":"Bảy giờ rưỡi sáng rời nhà, mười hai giờ rưỡi ra về, hai giờ rưỡi chiều có mặt ở câu lạc bộ: mật thám Pháp ghi lại từng bước chân của Nguyễn Ái Quốc, chính xác đến từng phút. Tháng 7/1922, người bị theo dõi đáp lại bằng một bức thư ngỏ trên báo L'Humanité, lễ phép xin ngài Bộ trưởng Thuộc địa khỏi phải tốn công: ông sẽ tự công bố thời khóa biểu của mình. Đằng sau tiếng cười ấy là một cuộc đấu trí kéo dài bốn năm giữa lòng Paris.","bia":{"src":"textures/ht/ht_anh_portrait_dated_1922_of_ho_chi_minh.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":2310},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Mười hai năm trên đất Pháp qua từng mốc thời gian: từ bến Marseille đến chuyến đi bí mật năm 1923","sapo":"Có những mốc được ghi trong sổ nhập cảng của một con tàu, có những mốc được ghi trong báo cáo của chính những người theo dõi. Ghép lại, chúng kể câu chuyện mười hai năm người phụ bếp Văn Ba trở thành chiến sĩ cộng sản Nguyễn Ái Quốc. Dưới đây là những mốc chính, cùng những điểm các nhà sử học còn tiếp tục tìm hiểu.","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_at_the_age_of_30_in_franc.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1453},{"i":4,"tieu_de_bang":"Nguyễn Ái Quốc ở Pháp, tuổi ba mươi (1920)","tieu_de":"Chân dung tuổi ba mươi: Nguyễn Ái Quốc và năm 1920 ở Paris","sapo":"Không ai còn biết chắc người bấm máy, cũng không rõ tấm ảnh được chụp ở hiệu ảnh nào. Nhưng gương mặt trong khung hình thuộc về một người thanh niên ba mươi tuổi đang ở giữa năm quan trọng bậc nhất đời mình. Năm 1920 ấy, cảnh sát Paris còn tưởng Người mới hai mươi sáu, mật thám ghi lại cả những cuốn sách Người tìm mua, và một bản thảo mang tên Những người bị áp bức đang dần thành hình.","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_at_the_age_of_30_in_franc.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1891},{"i":5,"tieu_de_bang":"Nguyễn Ái Quốc phát biểu tại Đại hội Tours, 12/1920","tieu_de":"“Các đồng chí, hãy cứu chúng tôi!”: vài phút của người đại biểu Đông Dương ở Tours","sapo":"Chiều 26/12/1920, giữa hội trường chật kín đại biểu Pháp, chủ tọa xướng lên một cái tên lạ: Đông Dương. Người thanh niên ba mươi tuổi bước lên diễn đàn và nói chưa đầy ba trang biên bản. Nhưng có những câu nói ở đó, như “nhà tù nhiều hơn trường học”, còn vang lại hai mươi lăm năm sau trong bản Tuyên ngôn Độc lập.","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_at_the_national_congress_.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1937},{"i":6,"tieu_de_bang":"Toàn cảnh Đại hội Tours, tháng 12/1920","tieu_de":"Sáu ngày ở Tours: lá phiếu khai sinh người cộng sản Việt Nam đầu tiên","sapo":"Tấm ảnh toàn cảnh ghi lại một hội trường chật kín đại biểu, với đoàn chủ tịch ở phía trước. Ở bàn thứ hai bên trái đoàn chủ tịch là Nguyễn Ái Quốc, đại biểu Đông Dương. Trong sáu ngày cuối năm 1920, những người ngồi trong hội trường ấy đã chia đôi một chính đảng lớn của nước Pháp. Và người thanh niên Đông Dương đã chọn con đường cho cả cuộc đời mình.","bia":{"src":"textures/ht/ht_anh_overview_of_the_congress_tous_comrade_nguyen_ai_.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1682},{"i":7,"tieu_de_bang":"Thẻ căn cước mang tên Nguyễn Ái Quấc, 4/9/1919","tieu_de":"阮愛國: tấm thẻ đề ngày 4/9/1919 và cái tên khiến mật thám phải truy tìm","sapo":"Tấm thẻ căn cước đề ngày 4/9/1919 mang một cái tên mới xuất hiện chưa đầy ba tháng: Nguyễn Ái Quấc. Cũng trong tuần lễ ấy, cái tên này ký dưới một bài báo, bước vào cuộc gặp với người từng hai lần làm Toàn quyền Đông Dương và nằm trên bàn làm việc của cảnh sát Paris. Một mảnh giấy nhỏ mở ra câu chuyện về cách một cái tên trở thành lời tuyên bố.","bia":{"src":"textures/ht/ht_anh_the_can_cuoc_nguyen_ai_quac_ngay_bon_thang_chin_.jpg","credit":"Ảnh: The government of the Republic of France · Public domain · Wikimedia Commons"},"so_chu":1777},{"i":8,"tieu_de_bang":"Đại biểu Đông Dương tại Đại hội Marseille, 1921","tieu_de":"Trở lại Marseille: người đại biểu Đông Dương ở Đại hội đầu tiên của Đảng Cộng sản Pháp","sapo":"Tháng 7/1911, Người đến Marseille dưới bếp một con tàu buôn. Mười năm sau, cuối tháng 12/1921, ống kính của hãng ảnh báo chí Meurisse ghi lại hình ảnh Người ở chính thành phố cảng ấy, với tư cách đại biểu Đông Dương. Tại Đại hội lần thứ nhất của Đảng Cộng sản Pháp, Người ngồi ở bàn chủ tọa và đứng lên đọc một bản dự thảo nghị quyết về các thuộc địa.","bia":{"src":"textures/ht/ht_anh_bibliotheque_nationale_de_france_departement_est.jpg","credit":"Ảnh: Agence de presse Meurisse · Public domain · Wikimedia Commons"},"so_chu":1965},{"i":9,"tieu_de_bang":"Chân dung năm 1922","tieu_de":"Chân dung năm 1922: tiếng cười tiễn chuyến “ngự giá” sang Pháp của vua Khải Định","sapo":"Tấm chân dung năm 1922 ghi lại gương mặt Nguyễn Ái Quốc ở tuổi ba mươi hai. Đó là một năm cầm bút dồi dào hiếm có trong những năm Người ở Paris. Cũng năm ấy, vua Khải Định được đưa sang Pháp dự Hội chợ thuộc địa. Người thanh niên An Nam đã đáp lại bằng một thứ vũ khí đặc biệt: tiếng cười.","bia":{"src":"textures/ht/ht_anh_portrait_dated_1922_of_ho_chi_minh.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1857},{"i":10,"tieu_de_bang":"Cảng Marseille tháng 10/1911","tieu_de":"Bến Marseille năm 1911: cánh cửa đầu tiên của nước Pháp","sapo":"Một tấm ảnh báo chí ghi ngày 23/10/1911, chụp bến cảng Marseille. Trong khung hình không có bóng dáng người phụ bếp Văn Ba, nhưng đó chính là bến cảng Người bước lên hơn ba tháng trước. Đằng sau tấm ảnh là câu chuyện về một hãng ảnh ở Paris, một con tàu mang biểu tượng năm ngôi sao và một thành phố cảng mở ra với cả thế giới thuộc địa.","bia":{"src":"textures/ht/ht_anh_23_10_11_marseille_vue_du_port_btv1b6917711h.jpg","credit":"Ảnh: Agence Rol. Agence photographique (comma · Public domain · Wikimedia Commons"},"so_chu":1867},{"i":11,"tieu_de_bang":"Ngõ Compoint, quận 17 Paris","tieu_de":"Ngõ Compoint: con ngõ cụt quận 17 và những bước chân dưới mắt mật thám","sapo":"Một con ngõ ngắn, yên tĩnh ở phía tây bắc Paris, được đăng lên Wikipedia tiếng Việt năm 2007. Gần chín mươi năm trước đó, cảnh sát Pháp đã ghi từng giờ Nguyễn Ái Quốc bước ra, bước vào nơi này. Con ngõ nhỏ giữ trong mình nhiều lớp lịch sử của Paris – và một tấm biển đồng khắc tên Người.","bia":{"src":"textures/ht/ht_anh_impasse_compoint.jpg","credit":"Ảnh: Rungbachduong at Vietnamese Wikipedia · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1829},{"i":12,"tieu_de_bang":"Lời Bác: “Tôi vui mừng đến phát khóc lên”","tieu_de":"“Tôi vui mừng đến phát khóc lên”: một trang báo tháng 7/1920 và con đường cứu nước","sapo":"Tháng 7/1920 ở Paris, một người thợ sửa ảnh ba mươi tuổi ngồi một mình trong căn buồng thuê, đọc đi đọc lại một trang báo, rồi nói to lên như đang đứng trước đông đảo đồng bào. Bốn mươi năm sau, Chủ tịch Hồ Chí Minh mới kể lại khoảnh khắc ấy. Vì sao một văn kiện chính trị đầy chữ khó lại khiến Người “vui mừng đến phát khóc lên”?","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_at_the_age_of_30_in_franc.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1856},{"i":13,"tieu_de_bang":"Số 9 ngõ Compoint","tieu_de":"Căn phòng số 9 ngõ Compoint: chín mét vuông, một ngọn đèn dầu và những trang viết đầu đời","sapo":"Một căn phòng chừng chín mét vuông trên tầng hai của ngôi nhà cũ, tiền thuê bốn mươi phrăng mỗi tháng, trả trước. Không có chỗ tắm giặt, chỉ một chiếc giường sắt, một chiếc bàn và ngọn đèn dầu. Gần hai năm, nơi đây vừa là nhà ở, vừa là xưởng sửa ảnh, vừa là “tòa soạn” của một người làm báo cách mạng. Ngôi nhà không còn, nhưng cánh cửa và chiếc chậu rửa của căn phòng vẫn được giữ đến hôm nay.","bia":{"src":"textures/bai/G05_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2028},{"i":14,"tieu_de_bang":"Nghề sửa ảnh","tieu_de":"Người thợ sửa ảnh ở Paris: đôi tay kiếm sống, thời gian dành cho dân tộc","sapo":"Một lời rao nhỏ trên tờ báo của giới thợ thuyền Paris mời khách mang ảnh người thân đến làm ảnh, lồng khung, giá 45 phrăng. Người đứng tên lời rao ấy là Nguyễn Ái Quốc. Không lương, không học bổng, không người bảo trợ, người thanh niên An Nam chọn một nghề cần đôi mắt tinh và bàn tay kiên nhẫn. Đổi lại, nghề ấy cho Người thứ quý nhất: thời gian để học và làm việc cho dân tộc.","bia":{"src":"textures/bai/G05_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1853},{"i":15,"tieu_de_bang":"Báo Le Paria (Người cùng khổ)","tieu_de":"Le Paria: tờ báo của những người cùng khổ ở các thuộc địa","sapo":"Cái tên của tờ báo đã là một lời thách thức: “paria”, kẻ bị ruồng bỏ. Trong bốn năm, những số báo mang tên ấy ra đời ở Paris, rồi theo hành lý thủy thủ, có khi nằm trong ruột những chiếc đồng hồ, vượt biển về các thuộc địa. Người đứng sau những số báo đầu tiên vừa là chủ nhiệm, chủ bút, người viết, người vẽ, vừa lo tiền in và việc phát hành: Nguyễn Ái Quốc.","bia":{"src":"textures/bai/G05_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1890},{"i":16,"tieu_de_bang":"Yêu sách của nhân dân An Nam","tieu_de":"Tám điều yêu sách: tiếng nói đầu tiên của người Việt Nam gửi tới Versailles","sapo":"Mười ngày trước khi hòa ước Versailles được ký trong Điện Gương, các phái đoàn dự Hội nghị hòa bình nhận được một văn bản ngắn bằng tiếng Pháp, ký tên Nguyễn Ái Quấc. Văn bản không đòi độc lập, chỉ xin tám điều tối thiểu. Các cường quốc làm ngơ. Nhưng tám điều ấy đã đưa tiếng nói của người Việt Nam lên diễn đàn quốc tế, và mở đầu một con đường dài hơn nhiều.","bia":{"src":"textures/ht/ht_anh_the_can_cuoc_nguyen_ai_quac_ngay_bon_thang_chin_.jpg","credit":"Ảnh: The government of the Republic of France · Public domain · Wikimedia Commons"},"so_chu":2026},{"i":17,"tieu_de_bang":"Phố Paris thập niên 1920","tieu_de":"Phố Paris đầu thập niên 1920: thành phố đã làm trường học cho người thợ ảnh An Nam","sapo":"Một cột quảng cáo tròn dán kín áp phích, một vòi nước bằng gang sơn xanh với bốn tượng nữ thần đỡ mái vòm, một ki-ốt báo bên hè, dãy bàn tròn trước quán cà phê. Góc phố dựng lại trong gian trưng bày không có gì phi thường: đó là Paris của người lao động những năm 1920. Nhưng chính trên những con phố như thế, người thợ ảnh Nguyễn Ái Quốc đã đi về mỗi ngày, đọc báo, nghe diễn thuyết và học cách nói với cả thế giới.","bia":{"src":"textures/bai/G05_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2093}],"do_vat":[{"id":"old_bed_frame@-5.8,-10.9","x":-5.8,"y":0.12,"z":-10.95,"loai":"old_bed_frame","ten":"Giường sắt","tieu_de":"Viên gạch nóng trong những đêm đông Paris"},{"id":"table@-3.0,-10.9","x":-2.95,"y":0.12,"z":-10.95,"loai":"table","ten":"Bàn sửa ảnh cạnh cửa sổ","tieu_de":"Chiếc bàn của người thợ sửa ảnh và người viết báo"},{"id":"vintage_oil_lamp@-2.9,-11.4","x":-2.9,"y":0.88,"z":-11.4,"loai":"vintage_oil_lamp","ten":"Ngọn đèn dầu bên bàn","tieu_de":"Ngọn đèn của những đêm đọc Luận cương Lê-nin"},{"id":"fancy_picture_frame_01@-3.0,-10.7","x":-2.95,"y":0.88,"z":-10.65,"loai":"fancy_picture_frame_01","ten":"Khung ảnh trên bàn làm việc","tieu_de":"Lời rao phóng ảnh trên báo của những người thợ thuyền"},{"id":"table@-6.0,-7.7","x":-6,"y":0.12,"z":-7.7,"loai":"table","ten":"Bàn làm báo Le Paria","tieu_de":"Nơi những số báo Người cùng khổ được chuẩn bị"},{"id":"vintage_suitcase@-5.3,-10.1","x":-5.3,"y":0.12,"z":-10.05,"loai":"vintage_suitcase","ten":"Chiếc va li cũ","tieu_de":"Hành trang của những cuộc ra đi"},{"id":"bookshelf@-4.0,-6.3","x":-4,"y":0.12,"z":-6.32,"loai":"bookshelf","ten":"Giá sách","tieu_de":"Người tự học giữa Paris"}]},"G06":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Nước Anh – London","tieu_de":"Bốn năm giữa lòng Đế quốc Anh: Nguyễn Tất Thành ở London sương mù","sapo":"Năm 1913, một thanh niên châu Á mảnh khảnh đặt chân đến London, kinh đô của đế quốc rộng lớn nhất thế giới lúc bấy giờ. Người ta thuê anh cào tuyết, đốt lò, rửa bát, và chẳng ai hỏi anh từ đâu đến, đang nghĩ gì. Bốn năm ấy để lại rất ít giấy tờ, nhưng để lại cho Người một ngoại ngữ, một cái nhìn mới về giai cấp lao động và về số phận chung của các dân tộc bị trị. Gian trưng bày này mời bạn đi lại những con phố ấy, tách bạch điều đã được tư liệu xác nhận với những gì chỉ còn trong lời kể.","bia":{"src":"textures/bai/G06_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2284},{"i":1,"tieu_de_bang":"Cào tuyết, đốt lò: những việc làm đầu tiên","tieu_de":"Từ xẻng tuyết đến hầm lò: những việc làm đầu tiên của Nguyễn Tất Thành ở London","sapo":"Việc làm đầu tiên người thanh niên Việt Nam tìm được ở London không nằm trong khách sạn sang trọng nào, mà ở sân một trường học phủ tuyết. Rồi đến hầm lò than, nơi ngày làm việc bắt đầu từ năm giờ sáng. Những công việc vô danh ấy không để lại tờ giấy nào, chỉ còn trong lời kể. Nhưng chính từ đó, một người làm thuê đã tự học để hiểu thế giới.","bia":{"src":"textures/bai/G06_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2102},{"i":2,"tieu_de_bang":"Giai thoại vua bếp Escoffier","tieu_de":"Những chiếc bánh không bị vứt đi: giai thoại vua bếp Escoffier và người phụ bếp trẻ","sapo":"Trong các câu chuyện về London, không chuyện nào được kể lại nhiều bằng cuộc gặp giữa “vua đầu bếp” Auguste Escoffier và người phụ bếp châu Á ở khách sạn Carlton. Câu chuyện có những chiếc bánh thừa, một câu hỏi, một lời đề nghị hậu hĩnh và một lời từ chối nhã nhặn. Nhân vật có thật, bối cảnh có thật, nhưng cuộc gặp thì chưa có tài liệu gốc nào xác nhận. Chuyên đề này tách từng lớp của giai thoại để xem đâu là lời kể, đâu là sự thật lịch sử.","bia":{"src":"textures/bai/G06_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1997},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ bến Nhà Rồng đến phố Haymarket: những mốc thời gian của chặng London","sapo":"Những năm ở Anh để lại ít giấy tờ, nên mỗi mốc thời gian cần được đọc cùng nguồn của nó. Có mốc dựa trên văn bản gốc, có mốc dựa trên lời kể, có mốc ghi trên một tấm biển gắn gần tám mươi năm sau. Dòng thời gian dưới đây nối hành trình của Người với số phận của khách sạn Carlton, của vị bếp trưởng lừng danh và của tấm biển tưởng niệm hôm nay.","bia":{"src":"textures/bai/G06_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1505},{"i":4,"tieu_de_bang":"Biển tưởng niệm tại số 80 Haymarket, London","tieu_de":"Một dòng chữ trên phố Haymarket: tấm biển mang tên Hồ Chí Minh giữa lòng London","sapo":"Sáng 13/3/2020, một người chụp ảnh dừng lại trước tòa nhà số 80 phố Haymarket và bấm máy hai lần. Thứ được ghi lại chỉ là một tấm biển tròn nhỏ trên tường. Nhưng đó là dấu tích hữu hình hiếm hoi ở London về những năm người thanh niên Nguyễn Tất Thành sống và làm việc tại đây. Để tấm biển ấy có mặt trên tường, những người bạn Anh đã mất gần ba năm vận động.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_plaque_new_zealand_house_80_haymarke.jpg","credit":"Ảnh: Spudgun67 · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1966},{"i":5,"tieu_de_bang":"New Zealand House, trên nền khách sạn Carlton cũ","tieu_de":"Từ tàn tích thời chiến đến tòa tháp kính: New Zealand House trên nền khách sạn Carlton","sapo":"Khách sạn nơi người thanh niên Nguyễn Tất Thành từng làm việc nay không còn nữa. Trên nền đất ấy, từ năm 1963, là tòa tháp mà Historic England gọi là tòa tháp văn phòng lớn đầu tiên ở trung tâm London. Câu chuyện của nó bắt đầu từ những quả bom năm 1940 và một hợp đồng bán đất năm 1949. Hôm nay, trên tường tòa tháp ấy có một tấm biển mang tên Hồ Chí Minh.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_1890_1969_founder_of_modern_vietnam_.jpg","credit":"Ảnh: Spudgun67 · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1867},{"i":6,"tieu_de_bang":"Đường phố London đầu thế kỷ XX","tieu_de":"London năm 1915: thành phố thời chiến nơi người thanh niên Việt Nam sống và làm việc","sapo":"Một bức ảnh cũ, không rõ tác giả, nằm trong kho ảnh báo chí của Hà Lan với dòng chú thích vỏn vẹn: London, nước Anh, năm 1915. Đó đúng là năm người thanh niên Nguyễn Tất Thành đang sống ở thành phố này. Đằng sau khung hình lặng lẽ ấy là một kinh đô đông dân bậc nhất thế giới, đang đổi thay từng ngày giữa cuộc chiến tranh khốc liệt nhất mà châu Âu từng biết đến lúc bấy giờ.","bia":{"src":"textures/ht/ht_anh_londen_engeland_sfa006011738.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1880},{"i":7,"tieu_de_bang":"Khách sạn Carlton","tieu_de":"Khách sạn Carlton: cung điện của Ritz và Escoffier, nơi người thanh niên từ xứ thuộc địa làm việc","sapo":"Ở góc phố Haymarket và Pall Mall từng có một khách sạn mà giới quý tộc London coi là chốn lui tới sang trọng bậc nhất. Nó mọc lên cùng một nhà hát, do ông vua ngành khách sạn César Ritz điều hành, với gian bếp của vua đầu bếp Auguste Escoffier. Theo tấm biển tưởng niệm ngày nay, người thanh niên Nguyễn Tất Thành đã làm việc tại đây năm 1913. Khách sạn chỉ hoạt động hơn bốn mươi năm, nhưng tên nó vẫn sống trong ký ức của hai dân tộc.","bia":{"src":"textures/bai/G06_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1858},{"i":8,"tieu_de_bang":"Gian bếp khách sạn","tieu_de":"Sau cánh cửa bếp: lò than, nồi đồng và “lữ đoàn” áo trắng ở London đầu thế kỷ XX","sapo":"Phía sau phòng ăn lộng lẫy của một khách sạn lớn ở London đầu thế kỷ XX là một thế giới khác: lò than đỏ lửa từ tinh mơ, hàng dãy nồi đồng sáng loáng, tiếng hô gọi món bằng tiếng Pháp. Trong thế giới ấy, người đứng ở bậc thấp nhất là những người rửa nồi, rửa bát. Theo nhiều hồi ký, người thanh niên Nguyễn Tất Thành đã bắt đầu từ chính vị trí ấy.","bia":{"src":"textures/bai/G06_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2102},{"i":9,"tieu_de_bang":"Nhà hát Hoàng gia Haymarket","tieu_de":"Nhà hát Hoàng gia Haymarket: sáu cột Corinth bên kia con phố","sapo":"Chếch bên kia phố Haymarket, nhìn sang khu đất của khách sạn Carlton, có một hàng sáu cột trắng đã đứng đó từ năm 1821. Nhà hát phía sau hàng cột từng dựng những vở hài kịch khiến chính quyền Anh phải ban luật kiểm duyệt, từng đón buổi công diễn đầu tiên của hai vở kịch Oscar Wilde. Không có tư liệu nào nói người thanh niên Nguyễn Tất Thành bước vào đây, nhưng hàng cột ấy là một phần khung cảnh quen thuộc của con phố nơi Người làm việc.","bia":{"src":"textures/bai/G06_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1836},{"i":10,"tieu_de_bang":"Thư gửi Phan Châu Trinh","tieu_de":"Những lá thư từ London gửi cụ Phan Châu Trinh: tiếng nói hiếm hoi của người thanh niên xa xứ","sapo":"Gần như mọi điều ta biết về những năm London của Nguyễn Tất Thành đều đến từ lời kể của người khác. Chỉ vài lá thư là tiếng nói trực tiếp của chính Người. Người nhận là cụ Phan Châu Trinh, nhà chí sĩ đang sống ở Paris, bạn đồng khoa của cụ thân sinh ra Người. Đọc lại, ta gặp một người thanh niên vừa lo miếng ăn, vừa lo học tiếng, vừa dõi theo vận mệnh đất nước.","bia":{"src":"textures/bai/G06_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1940}],"do_vat":[{"id":"brass_pot_01@-20.5,-2.8","x":-20.5,"y":1.07,"z":-2.8,"loai":"brass_pot_01","ten":"Nồi đồng trong bếp khách sạn","tieu_de":"Những chiếc nồi đồng và việc làm đầu tiên trong bếp"},{"id":"brass_pan_01@-18.9,0.0","x":-18.9,"y":2.3,"z":0,"loai":"brass_pan_01","ten":"Giá treo chảo đồng","tieu_de":"Mỗi tổ bếp một phần việc"},{"id":"table@-16.4,-2.6","x":-16.4,"y":0.1,"z":-2.6,"loai":"table","ten":"Bàn nhồi bột","tieu_de":"Giai thoại về người phụ bếp và tổ làm bánh"},{"id":"wicker_basket_01@-14.2,-5.9","x":-14.2,"y":0.1,"z":-5.9,"loai":"wicker_basket_01","ten":"Giỏ rau củ","tieu_de":"Có phải Người từng nấu rau cho Churchill?"},{"id":"bookshelf@-17.0,6.2","x":-16.98,"y":0.1,"z":6.25,"loai":"bookshelf","ten":"Giá sách","tieu_de":"Những buổi tối tự học ở London"},{"id":"caged_hanging_light@-16.4,-3.0","x":-16.4,"y":3.6,"z":-3,"loai":"caged_hanging_light","ten":"Đèn treo lồng sắt trong bếp","tieu_de":"Ánh đèn London thời chiến"}]},"G07":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Nước Mỹ – Boston và New York","tieu_de":"Nước Mỹ 1912 – 1913: đoạn đứt nét trên tấm bản đồ hành trình","sapo":"Trên tấm bản đồ hành trình tìm đường cứu nước, chặng Mỹ là một đoạn đứt nét: không rõ con tàu, không rõ ngày đến, ngày đi. Vậy mà người thanh niên hai mươi hai tuổi đã đi qua một nền cộng hòa hơn trăm tuổi và nhìn thấy cả ánh sáng lẫn bóng tối của nó. Gian nhỏ này mời bạn bước vào mùa đông năm ấy, và phân biệt thật rõ đâu là điều giấy tờ đã xác nhận, đâu là lời kể.","bia":{"src":"textures/bai/G07_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2245},{"i":1,"tieu_de_bang":"Lá thư đóng dấu bưu điện New York","tieu_de":"Ngày 15/12/1912: lá thư đóng dấu New York và nghịch lý của kho hồ sơ theo dõi","sapo":"Không có tấm ảnh hay trang nhật ký nào ghi lại những ngày Người ở Mỹ. Thứ còn lại trên giấy là một lá thư ngắn đề ngày 15/12/1912, mang dấu bưu điện New York. Nghịch lý thay, nó được giữ lại nhờ chính bộ máy thuộc địa vốn muốn theo dõi người viết. Đọc kỹ từng dòng khai báo, ta thấy hiện lên chân dung một người thủy thủ trẻ không nhà cửa mà không lạc hướng.","bia":{"src":"textures/bai/G07_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2169},{"i":2,"tieu_de_bang":"Từ Harlem đến bài báo “Hành hình kiểu Linsơ”","tieu_de":"“Hành hình kiểu Linsơ”: bản cáo trạng viết sau mười một năm","sapo":"Năm 1924, giữa những trang tin về các đại hội và phong trào cách mạng, độc giả tập san của Quốc tế Cộng sản bắt gặp một lời mời lạnh người: “Các bạn hãy tưởng tượng…”. Tác giả là Nguyễn Ái Quốc, người thanh niên từng làm thuê trên đất Mỹ hơn mười năm trước. Bài báo “Hành hình kiểu Linsơ” đã biến những điều người thợ phụ năm nào chứng kiến thành một bản cáo trạng bằng hình ảnh và con số.","bia":{"src":"textures/bai/G07_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2001},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ bến Nhà Rồng đến Quảng trường Ba Đình: hai mươi chín mốc quanh chặng Mỹ","sapo":"Chặng Mỹ chỉ kéo dài chưa đầy một năm và để lại rất ít giấy tờ. Muốn hiểu nó, phải đặt nó vào một dòng thời gian dài hơn: từ bản Tuyên ngôn năm 1776 của nước Mỹ, qua những năm người phụ bếp Văn Ba lênh đênh trên biển, đến ngày Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập ở Ba Đình. Mỗi mốc dưới đây được đánh dấu rõ: đâu là văn bản, đâu là lời kể, đâu là bối cảnh.","bia":{"src":"textures/bai/G07_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1289},{"i":4,"tieu_de_bang":"Khách sạn Parker House trên phố School, Boston","tieu_de":"Phố School, Boston: một góc phố, ba thế kỷ và địa chỉ cụ thể nhất của Bác trên đất Mỹ","sapo":"Đầu giờ chiều ngày 1/10/2013, một người chụp ảnh đến từ Canada hướng ống kính về khách sạn Parker House ở trung tâm Boston. Tấm ảnh du lịch ấy nay nằm trong một bảo tàng kể về cuộc đời Chủ tịch Hồ Chí Minh. Bởi trên chính khu đất này, theo lời kể, người thanh niên Nguyễn Tất Thành từng làm phụ bếp bánh trong mùa đông 1912–1913 — và con phố nhỏ quanh khách sạn còn giữ dấu vết của gần bốn thế kỷ lịch sử nước Mỹ.","bia":{"src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},"so_chu":1832},{"i":5,"tieu_de_bang":"Mặt tiền khách sạn Parker House ngày nay","tieu_de":"Parker House xưa và nay: một địa chỉ, hai tòa nhà, một trăm bảy mươi năm","sapo":"Tấm ảnh chụp tháng 11/2025 cho thấy mặt tiền một khách sạn vừa tròn một trăm bảy mươi năm tuổi. Nhưng tòa nhà trong ảnh chưa hề tồn tại khi người thợ phụ Nguyễn Tất Thành, theo lời kể, làm việc ở đây. Câu chuyện về hai tòa nhà trên cùng một nền đất giúp ta học cách nhìn một di tích đã đổi hình hài — và cảm nhận độ dài thật của thời gian lịch sử.","bia":{"src":"textures/ht/ht_anh_omni_parker_house_54957839082.jpg","credit":"Ảnh: ajay_suresh · CC BY 4.0 · Wikimedia Commons"},"so_chu":1745},{"i":6,"tieu_de_bang":"Tất cả mọi người đều sinh ra có quyền bình đẳng","tieu_de":"Từ Philadelphia 1776 đến Ba Đình 1945: hành trình của một câu Tuyên ngôn","sapo":"Chiều 2/9/1945, trước hàng chục vạn đồng bào ở Quảng trường Ba Đình, câu đầu tiên Chủ tịch Hồ Chí Minh đọc sau lời gọi quốc dân lại là một câu văn của nước Mỹ. Câu ấy được viết ở Philadelphia từ năm 1776. Chỉ hai chữ “suy rộng ra” tiếp theo đã biến quyền của mỗi con người thành quyền của mọi dân tộc. Bảy mươi mốt năm sau, chính một Tổng thống Mỹ đã đọc lại câu văn ấy giữa Hà Nội.","bia":{"src":"textures/bai/G07_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1867},{"i":7,"tieu_de_bang":"Khách sạn Parker House","tieu_de":"Parker House: nơi nhà văn họp mặt, món bánh ra đời và một người thợ phụ Việt Nam","sapo":"Trước khi gắn với câu chuyện về người thanh niên Nguyễn Tất Thành, Parker House đã là một huyền thoại của Boston. Ở đây, các nhà văn lớn của nước Mỹ họp mặt mỗi tháng, Charles Dickens tập đọc truyện trước tấm gương, và những món bánh mang tên khách sạn lan ra khắp nước Mỹ. Trong danh sách dài những con người gắn với khách sạn, có tên một người phụ bếp châu Á vô danh — người về sau trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hòa.","bia":{"src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},"so_chu":2006},{"i":8,"tieu_de_bang":"Gian bếp bánh","tieu_de":"Gian bếp bánh ở Boston: bột, lửa và đôi tay người thợ phụ mùa đông 1912 – 1913","sapo":"Trước khi khách của khách sạn Parker House thức dậy, bánh mì trên bàn ăn sáng của họ đã phải được nhào, ủ và nướng xong. Theo lời kể về sau, trong mùa đông 1912 – 1913, giữa những người thợ làm việc từ lúc trời còn tối ấy có một thanh niên châu Á hai mươi hai tuổi. Gian bếp bánh phục dựng trong không gian 3D mời người xem bước vào công việc của anh: một nghề không tên tuổi, nhưng đã nuôi anh trên con đường tìm đường cứu nước.","bia":{"src":"textures/bai/G07_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2041},{"i":9,"tieu_de_bang":"Nhà thờ King’s Chapel","tieu_de":"King’s Chapel: nhà thờ đá xám ở góc phố người thợ phụ đi qua, giữa thành phố của những lời tuyên ngôn","sapo":"Mùa đông 1912 – 1913, bước ra khỏi khách sạn Parker House, người ta sẽ thấy ngay ở góc phố Tremont một khối đá xám nặng nề với ngọn tháp vuông không có chóp nhọn. Nhà thờ King’s Chapel khi ấy đã đứng đó gần một trăm sáu mươi năm, chứng kiến Boston từ một thuộc địa trung thành với nhà vua nước Anh trở thành cái nôi của cuộc cách mạng Mỹ. Câu chuyện của nó giúp ta hiểu thành phố mà người thanh niên Việt Nam đã sống, và bài học về độc lập mà Người sẽ còn trở lại nhiều lần.","bia":{"src":"textures/bai/G07_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2028},{"i":10,"tieu_de_bang":"New York và Harlem","tieu_de":"New York 1912: thành phố chọc trời, cửa ngõ người nhập cư và khu Harlem đang thành hình","sapo":"Dấu vết giấy tờ hiếm hoi nhất về chặng Mỹ của Nguyễn Tất Thành là một con dấu bưu điện New York. Thành phố ấy vừa khoe những tòa nhà cao nhất thế giới, vừa đón hàng triệu người nhập cư nghèo, lại vừa chứng kiến người Mỹ gốc Phi dồn về một khu phố phía bắc Manhattan tên là Harlem. Đi qua New York năm 1912 là đi qua cả ánh sáng lẫn bóng tối của nước Mỹ, những điều người thanh niên châu Á ấy sẽ còn nhắc lại trong nhiều trang viết về sau.","bia":{"src":"textures/bai/G07_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2129}],"do_vat":[{"id":"table@1.4,-9.4","x":1.4,"y":0.1,"z":-9.4,"loai":"table","ten":"Bàn nhồi bột","tieu_de":"Chiếc bàn của người thợ phụ"},{"id":"wooden_bowl_01@0.1,-9.2","x":0.15,"y":1,"z":-9.25,"loai":"wooden_bowl_01","ten":"Âu gỗ trộn bột","tieu_de":"Chiếc bánh mang tên Parker House"}]},"G08":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Liên Xô – Petrograd và Mátxcơva","tieu_de":"Hai lần cập bến xứ tuyết: Liên Xô trên hành trình tìm đường của Nguyễn Ái Quốc","sapo":"Mùa hè năm 1923, một con tàu từ Hamburg cập bến Petrograd, mang theo người thợ ảnh có tên Chen Vang. Mùa hè năm 1934, một tàu buôn từ Thượng Hải cập cảng Vlađivôxtốc, chở một vị khách đặc biệt mà thuyền trưởng được dặn phải đón. Cả hai lần, người khách ấy là Nguyễn Ái Quốc. Giữa hai lần cập bến là mười một năm, và cả một chặng đường cách mạng.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2341},{"i":1,"tieu_de_bang":"Chuyến đi bí mật từ Paris tới Petrograd","tieu_de":"Mười bảy ngày thoát khỏi vòng vây mật thám: từ Paris tới Petrograd, mùa hè 1923","sapo":"Tối 13/6/1923, một người thanh niên châu Á mua vé xem suất chiếu phim cuối cùng ở Paris, nhưng không bao giờ xem hết bộ phim ấy. Mười bảy ngày sau, người ấy bước xuống một bến tàu ở Petrograd, trong túi là giấy thông hành mang một cái tên xa lạ. Những kẻ theo dõi Người suốt mấy năm trời phải mất một thời gian mới hiểu chuyện gì đã xảy ra.","bia":{"src":"textures/ht/ht_anh_visa_for_entry_into_russia_no_1829_on_june_16_19.jpg","credit":"Ảnh: The representative of the Union of Sovie · Public domain · Wikimedia Commons"},"so_chu":2175},{"i":2,"tieu_de_bang":"Đồng chí Lin ở Mátxcơva, 1934 – 1938","tieu_de":"Học viên số 375, nghiên cứu sinh số 19: bốn năm của đồng chí Lin ở Mátxcơva (1934 – 1938)","sapo":"Trong hồ sơ của Trường Quốc tế Lê-nin, người ấy là học viên số hiệu 375, tên Lin. Trong quyết định cho về nước năm 1938, người ấy là sinh viên số hiệu 19. Đằng sau những con số khô khan là bốn năm lặng lẽ học tập, giảng dạy, nghiên cứu và chờ đợi của Nguyễn Ái Quốc, giữa một Mátxcơva đầy biến động.","bia":{"src":"textures/bai/G08_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2212},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Luận cương của Lênin đến cột mốc 108: dòng thời gian hai chặng ở Liên Xô (1920 – 1941)","sapo":"Có những năm dồn dập đến mức tháng nào cũng có một sự kiện, lại có những năm lặng lẽ tưởng như chẳng có gì xảy ra. Dòng thời gian dưới đây xếp cạnh nhau hơn ba mươi mốc, từ bài báo Người đọc ở Paris năm 1920 đến ngày Người vượt cột mốc 108 về nước năm 1941. Đọc kỹ khoảng cách giữa các mốc, ta hiểu vì sao Liên Xô có mặt ở hai khúc quanh lớn trong cuộc đời Nguyễn Ái Quốc.","bia":{"src":"textures/bai/G08_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1435},{"i":4,"tieu_de_bang":"Nguyễn Ái Quốc ở Liên Xô, 1923","tieu_de":"Người thanh niên mặc áo len đan: Nguyễn Ái Quốc năm 1923 qua tấm ảnh và trang báo của Manđenxtam","sapo":"Một ngày cuối năm 1923 ở Mátxcơva, nhà thơ Nga Ôxíp Manđenxtam ngồi trước người mà ông gọi là người An Nam duy nhất của thành phố, và mở đầu bằng một câu hỏi về Gandhi. Cuộc trò chuyện ấy thành một bài báo mà gần một thế kỷ sau người Việt Nam vẫn còn trích dẫn. Tấm ảnh chụp cùng năm cho ta thấy gương mặt Nguyễn Ái Quốc; trang báo của nhà thơ cho ta nghe giọng nói của Người.","bia":{"src":"textures/ht/ht_anh_nguyen_ai_quoc_in_the_soviet_union_in_1923.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1952},{"i":5,"tieu_de_bang":"Thị thực số 1829 mang tên Chen Vang","tieu_de":"Tờ thị thực số 1829: cánh cửa sang nước Nga mở ra cho một cái tên giả","sapo":"Một tờ giấy đề ngày 16/6/1923 tại Berlin cho phép một người tên Chen Vang nhập cảnh nước Nga. Chẳng ai để ý tới cái tên xa lạ ấy. Người cầm tờ giấy chính là Nguyễn Ái Quốc, ba ngày trước còn ở Paris dưới con mắt theo dõi của mật thám Pháp. Vì sao lại là Berlin, và vì sao lại là một cái tên nghe như tên người Hoa?","bia":{"src":"textures/ht/ht_anh_visa_for_entry_into_russia_no_1829_on_june_16_19.jpg","credit":"Ảnh: The representative of the Union of Sovie · Public domain · Wikimedia Commons"},"so_chu":1746},{"i":6,"tieu_de_bang":"Thẻ đại biểu tư vấn Đại hội V, 1924","tieu_de":"Tấm thẻ không có quyền biểu quyết: tiếng nói của các dân tộc thuộc địa ở Đại hội V","sapo":"Bốn ngày trước khi Đại hội V Quốc tế Cộng sản khai mạc, Nguyễn Ái Quốc viết thư xin một tấm thẻ dự đại hội. Tấm thẻ Người nhận được mang tư cách đại biểu tư vấn: được nói, nhưng không được bỏ phiếu. Người đã dùng trọn quyền được nói ấy, từ phiên khai mạc đến những phiên họp cuối, để kéo sự chú ý của cả đại hội về phía các thuộc địa.","bia":{"src":"textures/ht/ht_anh_advisory_delegate_card_issued_to_nguyen_ai_quoc_.jpg","credit":"Ảnh: 5th Congress of the Communist Internatio · Public domain · Wikimedia Commons"},"so_chu":1940},{"i":7,"tieu_de_bang":"Các đại biểu Đại hội V Quốc tế Cộng sản, 1924","tieu_de":"Mùa hè 1924 ở Điện Kremli: đại hội đầu tiên vắng bóng Lênin","sapo":"Bức ảnh tập thể ghi lại các đại biểu dự Đại hội V Quốc tế Cộng sản tại Điện Kremli, mùa hè năm 1924. Đó là đại hội đầu tiên của Quốc tế Cộng sản vắng bóng Lênin, người đã ra đi chưa đầy năm tháng trước. Giữa hơn năm trăm đại biểu về Mátxcơva năm ấy có một thanh niên Việt Nam ba mươi tư tuổi, mang tấm thẻ đại biểu tư vấn và một câu hỏi lớn về các dân tộc thuộc địa.","bia":{"src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1820},{"i":8,"tieu_de_bang":"Bài báo \"Lênin và các dân tộc thuộc địa\", 1924","tieu_de":"Trên trang báo Pravda ngày tang lễ: lời tiễn biệt Lênin của một người dân thuộc địa","sapo":"Ngày 27/1/1924, ngày Mátxcơva đưa linh cữu Lênin ra Quảng trường Đỏ, báo Pravda in bài viết của một người Việt Nam mới đến nước Nga chưa đầy bảy tháng. Người ấy chưa một lần được gặp Lênin. Vậy mà bài báo ngắn của Người lại nói thay cho hàng triệu người ở các thuộc địa, những người cũng chưa từng biết mặt vị lãnh tụ.","bia":{"src":"textures/ht/ht_anh_article_lenin_and_the_colonial_peoples_by_nguyen.jpg","credit":"Ảnh: Nguyen Ai Quoc (Ho Chi Minh) · Public domain · Wikimedia Commons"},"so_chu":1902},{"i":9,"tieu_de_bang":"Lăng gỗ tạm của Lênin (1/1924)","tieu_de":"Lăng gỗ dựng trên đất băng: Quảng trường Đỏ tháng Giêng năm 1924","sapo":"Tháng Giêng năm 1924, mặt đất Mátxcơva đóng băng cứng như đá, vậy mà chỉ trong vài ngày, một công trình bằng gỗ đã kịp dựng lên sát tường thành Kremli. Đó là nơi an nghỉ đầu tiên của Lênin, tiền thân của tòa lăng đá mà ngày nay ai đến Quảng trường Đỏ cũng nhìn thấy. Trong dòng người đội rét đến viếng những ngày ấy có một thanh niên châu Á mặc không đủ ấm: Nguyễn Ái Quốc.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1741},{"i":10,"tieu_de_bang":"Tháp Spasskaya","tieu_de":"Tháp Spasskaya: chiếc đồng hồ của Quảng trường Đỏ và con đại bàng chưa kịp thay","sapo":"Hơn năm thế kỷ nay, tháp Spasskaya là cổng chính của Điện Kremli và là chiếc đồng hồ của cả nước Nga. Mùa đông năm 1924, khi Nguyễn Ái Quốc đứng giữa Quảng trường Đỏ, đỉnh tháp vẫn còn con đại bàng hai đầu của các Sa hoàng, còn tầng chuông thì ngân giai điệu Quốc tế ca. Câu chuyện của ngọn tháp là câu chuyện của những lớp thời gian chồng lên nhau.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1926},{"i":11,"tieu_de_bang":"Nhà thờ Thánh Basil","tieu_de":"Nhà thờ Thánh Basil: chín nhà nguyện trên một nền chung và số phận một kiệt tác","sapo":"Ở đầu phía nam Quảng trường Đỏ, những mái vòm củ hành xoắn vặn, mỗi mái một màu, trông như bước ra từ truyện cổ tích. Công trình ấy ra đời để tạ ơn một chiến thắng thế kỷ XVI, mang tên một người tu hành đi chân đất, và đã vượt qua bao cơn biến động của lịch sử. Năm 1923, đúng năm Nguyễn Ái Quốc đặt chân tới nước Nga Xô-viết, nhà thờ bắt đầu một cuộc đời mới: trở thành bảo tàng.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1727},{"i":12,"tieu_de_bang":"Quốc tế Cộng sản","tieu_de":"Quốc tế Cộng sản và Nguyễn Ái Quốc: hai mươi ba năm gắn bó (1920 – 1943)","sapo":"Hồ Chí Minh – Biên niên tiểu sử ghi lại một quyết định ngày 14/4/1924 của Quốc tế Cộng sản: nhận Nguyễn Ái Quốc làm cán bộ Ban Phương Đông, lương mỗi tháng 6 trécnôvéc. Tờ giấy hành chính ấy là một mắt xích trong mối gắn bó kéo dài gần một phần tư thế kỷ. Quốc tế Cộng sản là tổ chức thế nào, và vì sao người thanh niên yêu nước Việt Nam lại chọn đi cùng nó?","bia":{"src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":2146}],"do_vat":[]},"G09":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Trung Quốc – Quảng Châu","tieu_de":"Đất Trung Hoa trên hành trình của Người: lớp học bên sông Châu Giang, đường về Tổ quốc và mười ba tháng lao tù","sapo":"Người đến đất Trung Hoa nhiều lần, và mỗi lần mang một cái tên khác: Lý Thụy, Hồ Quang, rồi Hồ Chí Minh. Có lần Người đến trong vai một phiên dịch viên, có lần trong bộ quân phục Bát lộ quân, có lần bị trói tay giải qua mười tám nhà lao. Vậy mà lần nào, mọi toan tính của Người cũng hướng về cùng một phía: con đường trở về Tổ quốc.","bia":{"src":"textures/bai/G09_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2280},{"i":1,"tieu_de_bang":"Từ tiếng bom Sa Diện đến Hội Thanh niên","tieu_de":"Tiếng bom Sa Diện và một con đường khác: từ Tâm tâm xã đến Hội Việt Nam Cách mạng Thanh niên","sapo":"Tối 19/6/1924, một tiếng nổ vang lên giữa bữa tiệc giới chức Pháp chiêu đãi Toàn quyền Đông Dương trên đảo Sa Diện, Quảng Châu. Người ném bom là một thanh niên xứ Nghệ, và chỉ ít lâu sau anh đã nằm lại dưới dòng Châu Giang. Năm tháng sau, một người phiên dịch tên Lý Thụy tới thành phố này, tìm gặp những đồng chí của anh và chỉ cho họ một con đường khác. Con đường ấy dẫn tới sự ra đời của Hội Việt Nam Cách mạng Thanh niên.","bia":{"src":"textures/bai/G09_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2166},{"i":2,"tieu_de_bang":"Mười ba tháng trong các nhà lao Quảng Tây","tieu_de":"Mười ba tháng xiềng xích: người tù Hồ Chí Minh qua mười tám nhà lao Quảng Tây (1942 – 1943)","sapo":"Tháng 8/1942, một người Việt Nam ngoài năm mươi tuổi, giấy tờ mang một cái tên chưa ai biết là Hồ Chí Minh, vượt biên giới sang Trung Quốc để tìm đồng minh. Chỉ mười mấy ngày sau, ông bị bắt vì bị nghi là gián điệp. Không phiên tòa, không bản án, người tù bị giải qua mười ba huyện, mười tám nhà lao, có lúc tin dữ về ông còn truyền về tận Pác Bó. Đây là câu chuyện của mười ba tháng ấy.","bia":{"src":"textures/bai/G09_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2087},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Hai mươi năm trên đất Trung Hoa: dòng thời gian từ Quảng Châu đến ngục Quảng Tây (1924 – 1944)","sapo":"Ba mươi mốc thời gian, trải trên hai mươi năm và hàng nghìn cây số đường đất Trung Hoa. Nếu đặt chúng lên bản đồ, ta sẽ thấy một đường đi kỳ lạ: từ Mátxcơva xuống Quảng Châu, rồi rời xa, rồi quay lại, mỗi lần một gần hơn biên giới Việt Nam. Dòng thời gian này giúp khách tham quan đọc ra quy luật ấy.","bia":{"src":"textures/bai/G09_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1382},{"i":4,"tieu_de_bang":"Nguyễn Ái Quốc năm 1924","tieu_de":"Gương mặt năm 1924: Nguyễn Ái Quốc giữa Mátxcơva và Quảng Châu","sapo":"Một tấm ảnh đen trắng, không rõ người chụp, chỉ ghi năm 1924. Người trong ảnh vừa bước sang tuổi ba mươi tư, đã nổi tiếng trên báo chí Paris, nhưng gương mặt thì mật thám Pháp vẫn phải săn tìm. Chỉ trong năm ấy, Người đi từ giá rét Mátxcơva đến cái nắng Quảng Châu, từ diễn đàn Quốc tế Cộng sản đến một cái tên mới: Lý Thụy.","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_1924.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1749},{"i":5,"tieu_de_bang":"Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam","tieu_de":"Số 89 – 91 phố Nam Hoa Sơn: ngôi nhà ở ga cuối đường sắt, nơi mở đầu đường về","sapo":"Trên một con phố ở khu trung tâm cũ của Côn Minh, hai số nhà 89 và 91 nay mang tên nhà lưu niệm Hồ Chí Minh. Hơn tám mươi năm trước, thành phố cao nguyên này là ga cuối của tuyến đường sắt từ Hải Phòng lên Vân Nam, và là nơi một nhà cách mạng Việt Nam ở tuổi năm mươi âm thầm nối lại sợi dây với Tổ quốc. Vì sao lại là Côn Minh, và ngôi nhà ấy đã đi qua những gì trước khi hiện lên trong tấm ảnh chụp đầu năm 2025?","bia":{"src":"textures/ht/ht_anh_2025_02_05_former_residence_of_ho_chi_minh_kunmi.jpg","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},"so_chu":1946},{"i":6,"tieu_de_bang":"Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh","tieu_de":"Mùa hè 1940 ở Côn Minh: khi thời cơ gõ cửa","sapo":"Bước qua ngưỡng cửa ngôi nhà trên phố Nam Hoa Sơn, người xem được đưa về những tháng ngày Người làm việc bí mật ở Côn Minh. Chính tại thành phố này, mùa hè năm 1940, hai trí thức trẻ từ Hà Nội tìm sang gặp Người, đúng lúc tin nước Pháp thất trận dội về từ châu Âu. Một nhận định của Người trong những ngày ấy về sau được nhắc lại như bài học kinh điển về nắm bắt thời cơ.","bia":{"src":"textures/ht/ht_anh_2025_02_05_interior_of_ho_chi_minh_s_former_resi.jpg","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},"so_chu":1649},{"i":7,"tieu_de_bang":"Cổng Trường Quân sự Hoàng Phố, Quảng Châu","tieu_de":"Cánh cổng trên đảo Trường Châu và câu đối “tham sinh úy tử”","sapo":"Tấm ảnh chụp tháng 4/2009 dừng lại trước cổng một ngôi trường nay đã tròn một thế kỷ tuổi. Trên tấm biển là sáu chữ Hán “Lục quân quân quan học hiệu”; gắn với ngôi trường là câu đối răn kẻ tham sống sợ chết chớ bước qua cửa. Trong số những người từng qua cánh cổng ấy có những thanh niên Việt Nam đi theo con đường Nguyễn Ái Quốc vạch ra từ lớp học trên phố Văn Minh.","bia":{"src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1650},{"i":8,"tieu_de_bang":"Tờ cuối bản thảo Nhật ký trong tù (1942 – 1943)","tieu_de":"Trăng, lò than hồng và chất thép: thơ viết trong ngục của Hồ Chí Minh","sapo":"Tấm ảnh ghi lại tờ cuối của cuốn sổ tay nhỏ, nơi người tù Hồ Chí Minh chép những bài thơ chữ Hán suốt hơn một năm bị giải qua các nhà lao Quảng Tây. Lật ngược từ trang cuối ấy, người đọc gặp vầng trăng qua khe cửa, cô gái xóm núi bên lò than, tiếng chày giã gạo và cả tiếng cười châm biếm nhắm vào bọn cai ngục. Điều gì khiến một tập thơ viết trong xiềng xích lại chan chứa ánh sáng đến thế?","bia":{"src":"textures/ht/ht_anh_to_cuoi_tap_tho_nhat_ky_trong_tu.jpg","credit":"Ảnh: 7ieulong · Public domain · Wikimedia Commons"},"so_chu":1797},{"i":9,"tieu_de_bang":"Bản thảo Nhật ký trong tù – Bảo vật quốc gia","tieu_de":"Cuốn sổ 79 trang: bản thảo Nhật ký trong tù trở thành Bảo vật quốc gia","sapo":"Một cuốn sổ chỉ lớn hơn bàn tay một chút, 79 trang giấy ố vàng, gáy rách, mép sờn. Hơn tám mươi năm trước, nó theo người tù Hồ Chí Minh qua các nhà lao Quảng Tây; hôm nay nó thuộc hàng những hiện vật quý giá nhất của đất nước. Điều gì làm nên giá trị của một cuốn sổ cũ như thế, và vì sao nó được xếp vào hàng Bảo vật quốc gia?","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_s_prison_diary_in_2016.jpg","credit":"Ảnh: Cookie Nguyen · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1581},{"i":10,"tieu_de_bang":"Không có gì quý hơn độc lập, tự do","tieu_de":"“Không có gì quý hơn độc lập, tự do”: chín chữ vang lên giữa mùa hè bom đạn 1966","sapo":"Sáng Chủ nhật 17/7/1966, qua làn sóng Đài Tiếng nói Việt Nam, đồng bào cả nước nghe Chủ tịch Hồ Chí Minh đọc một lời kêu gọi. Người không hứa một chiến thắng dễ dàng: Người nói chiến tranh có thể kéo dài hai mươi năm hoặc lâu hơn nữa. Rồi Người nói một câu chỉ có chín chữ. Vì sao câu nói ấy trở thành chân lý của cả một dân tộc?","bia":{"src":"textures/bai/G09_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1796},{"i":11,"tieu_de_bang":"Nhà số 248 – 250 đường Văn Minh","tieu_de":"Số 13 đường Văn Minh: một ngôi nhà phố vừa là trụ sở, trường học và tòa soạn","sapo":"Năm 1925, người Quảng Châu biết ngôi nhà này bằng một con số giản dị: số 13 đường Văn Minh. Không tấm biển nào cho biết bên trong là Tổng bộ của một tổ chức cách mạng Việt Nam. Ở đó, một người mang tên Lý Thụy vừa giảng bài, vừa viết báo, vừa sống cùng học trò. Trong hơn hai năm, căn nhà phố ấy đào tạo lớp cán bộ đầu tiên cho con đường cách mạng Việt Nam.","bia":{"src":"textures/bai/G09_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2060},{"i":12,"tieu_de_bang":"Nhà kỵ lâu (骑楼)","tieu_de":"Kỵ lâu: những tầng lầu “cưỡi” lên vỉa hè quanh lớp học của Nguyễn Ái Quốc","sapo":"Trong gian Quảng Châu, khách bước dọc một dãy hiên có mái che, hàng cột nối nhau, phía trên là những tầng lầu vươn ra sát mép đường. Người Quảng Châu gọi kiểu nhà ấy là kỵ lâu, nghĩa là lầu cưỡi lên vỉa hè. Đó là khung cảnh mà Nguyễn Ái Quốc và các học viên đi qua mỗi ngày. Câu chuyện của những mái hiên ấy bắt đầu từ các thương cảng Đông Nam Á và từ một cuộc đổi mới đô thị đầu thế kỷ XX.","bia":{"src":"textures/bai/G09_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1880},{"i":13,"tieu_de_bang":"Trường Quân sự Hoàng Phố","tieu_de":"Những học trò Việt Nam ở Hoàng Phố: từ đảo Trường Châu về chiến trường Tổ quốc","sapo":"Hai con người cùng được gọi là “vị tướng đầu tiên” của quân đội cách mạng Việt Nam, và cả hai từng học ở một ngôi trường trên hòn đảo giữa sông Châu Giang. Ngôi trường ấy do chính quyền Tôn Trung Sơn lập ra, hiệu trưởng là Tưởng Giới Thạch. Vì sao những thanh niên Việt Nam được Nguyễn Ái Quốc lựa chọn lại có mặt ở đó? Và họ đã mang những gì từ Hoàng Phố về cho Tổ quốc?","bia":{"src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":2162}],"do_vat":[{"id":"table@-9.5,-16.1","x":-9.5,"y":0.2,"z":-16.15,"loai":"table","ten":"Bàn giảng","tieu_de":"Nơi những bài giảng thành sách Đường Kách mệnh"},{"id":"blackboard@-9.5,-17.5","x":-9.5,"y":1,"z":-17.49,"loai":"blackboard","ten":"Tấm bảng đen","tieu_de":"Bài học về các cuộc cách mạng"},{"id":"vintage_oil_lamp@-8.8,-16.1","x":-8.85,"y":1,"z":-16.05,"loai":"vintage_oil_lamp","ten":"Ngọn đèn dầu","tieu_de":"Những số báo Thanh Niên"},{"id":"table@-11.4,-10.6","x":-11.4,"y":0.2,"z":-10.6,"loai":"table","ten":"Bàn học viên","tieu_de":"Những người học trò đầu tiên"},{"id":"table@-7.6,-10.6","x":-7.6,"y":0.2,"z":-10.6,"loai":"table","ten":"Bàn học viên","tieu_de":"Trần Phú – từ lớp học Quảng Châu đến Tổng Bí thư"},{"id":"table@-11.4,-11.9","x":-11.4,"y":0.2,"z":-11.95,"loai":"table","ten":"Bàn học viên","tieu_de":"Phong trào “vô sản hóa”"}]},"G10":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Thái Lan – Thầu Chín","tieu_de":"Ông Thầu Chín bên dòng Mê Kông: hơn một năm Nguyễn Ái Quốc sống giữa kiều bào đất Xiêm","sapo":"Mùa hè năm 1928, các xóm Việt kiều ở Xiêm có thêm một người đàn ông đội nón, đi dép, được bà con gọi thân mật là Thầu Chín. Ông cày ruộng, đào giếng, tối đến lại ngồi dạy chữ bên ngọn đèn dầu. Ít ai trong xóm biết rằng người mà mật thám Pháp đang ráo riết truy tìm khắp châu Á đang sống ngay giữa họ. Gian trưng bày này đưa bạn trở lại hơn một năm lặng lẽ mà quyết định ấy.","bia":{"src":"textures/bai/G10_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2221},{"i":1,"tieu_de_bang":"Lớp học đèn dầu và tờ báo Thân Ái","tieu_de":"Lớp học dưới ngọn đèn dầu: ông Thầu Chín dạy chữ, dịch sách, làm báo cho kiều bào","sapo":"Ban ngày, ông Thầu Chín ra đồng như mọi người trong xóm. Khi trời tối, một ngọn đèn dầu lại được thắp lên, trẻ con và người lớn ngồi quanh tập đánh vần từng chữ quốc ngữ. Cũng dưới ngọn đèn ấy, những trang báo Thân Ái được viết ra để đi tới các xóm xa. Vì sao một nhà cách mạng lại bắt đầu từ những con chữ?","bia":{"src":"textures/bai/G10_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2047},{"i":2,"tieu_de_bang":"Tin từ quê nhà và chuyến đi cuối năm 1929","tieu_de":"Ba tổ chức, một đảng: vì sao ông Thầu Chín rời đất Xiêm cuối năm 1929","sapo":"Năm 1929, những tin tức vượt sông Mê Kông tới xóm Việt kiều ở Nakhon Phanom khiến ông Thầu Chín không thể ngồi yên. Ở quê nhà, những người cộng sản đầu tiên đã chia thành ba tổ chức, mỗi nơi một ngả. Cùng năm ấy, một tòa án của chính quyền thuộc địa kết án tử hình Người. Cuối năm, Người lặng lẽ rời Xiêm để làm một việc mà chỉ Người mới đủ uy tín để làm.","bia":{"src":"textures/bai/G10_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1907},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Quảng Châu đến Cửu Long qua đất Xiêm: dòng thời gian 1927 – 1930","sapo":"Hơn một năm của ông Thầu Chín ở Xiêm nằm giữa hai bước ngoặt lớn: sự tan vỡ của cách mạng Trung Quốc năm 1927 và sự ra đời của Đảng Cộng sản Việt Nam đầu năm 1930. Đặt những mốc nhỏ ở các xóm Việt kiều bên cạnh những biến cố ở Hà Nội, Hương Cảng, Mátxcơva, ta mới thấy hết vì sao quãng thời gian tưởng như lặng lẽ ấy lại quan trọng đến vậy.","bia":{"src":"textures/bai/G10_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1401},{"i":4,"tieu_de_bang":"Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom","tieu_de":"Nhà lưu niệm ở bản Mạy: nơi ký ức về ông Thầu Chín được giữ bằng tình người","sapo":"Ở làng Nachok, mà người Việt quen gọi là bản Mạy, ngoại ô thành phố Nakhon Phanom, có một ngôi nhà gỗ nhỏ mà người Việt đến Thái Lan thường tìm về. Tấm ảnh này ghi lại mặt trước ngôi nhà ấy vào đầu tháng 3/2010. Đằng sau khung hình giản dị là gần một thế kỷ kiều bào và bạn bè Thái Lan chung tay giữ lại ký ức về những năm 1928 – 1929.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_front.jpg","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1725},{"i":5,"tieu_de_bang":"Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng","tieu_de":"Ngôi nhà ba gian ở bản Mạy: dáng nhà miền Trung bên bờ Mê Kông","sapo":"Giữa vùng đất của những nếp nhà sàn Isan, có một ngôi nhà gỗ trông như vừa được mang sang từ một làng quê xứ Nghệ: ba gian, hai hồi, vách thưng ván, trước hiên buông tấm rèm tre đan. Đó là ngôi nhà ở bản Mạy, ngoại ô Nakhon Phanom, nơi ông Thầu Chín từng sống. Ngôi nhà hôm nay đã được dựng lại, và chính việc dựng lại ấy cũng là một câu chuyện đáng kể.","bia":{"src":"textures/ht/ht_anh_house_hochiminh_stayed_nakhonphanom.jpg","credit":"Ảnh: BacLuong at Vietnamese Wikipedia · CC BY 4.0 · Wikimedia Commons"},"so_chu":1705},{"i":6,"tieu_de_bang":"Hàng dừa trong khu lưu niệm Nakhon Phanom","tieu_de":"Hai cây dừa và một cây khế: khu vườn kể chuyện ông Thầu Chín","sapo":"Ở bản Mạy có hai cây dừa đã vươn cao hơn ba mươi mét và một cây khế già quanh năm trĩu quả. Người giữ vườn kể rằng chúng do chính tay ông Thầu Chín trồng. Tấm ảnh hàng dừa chụp năm 2010 mở ra câu chuyện về cách người Việt xa xứ mang cả một khu vườn quê theo mình, và về một người luôn coi việc trồng cây là việc lớn.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_coco.jpg","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1684},{"i":7,"tieu_de_bang":"Ngôi nhà của “Thầu Chín”","tieu_de":"Dưới mái nhà ông Thầu Chín: sống như dân để hiểu dân","sapo":"Ngôi nhà gỗ trong gian trưng bày không có món đồ nào quý giá: một tấm phản, một bàn viết, ngọn đèn dầu, chum nước bên hiên. Vậy mà dưới những mái nhà như thế, năm 1928 – 1929, một người từng làm việc ở Paris, Mátxcơva, Quảng Châu đã sống như một nông dân nghèo. Vì sao Nguyễn Ái Quốc chọn cách sống ấy, và nó đã để lại cho Người bài học gì?","bia":{"src":"textures/bai/G10_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2038},{"i":8,"tieu_de_bang":"Những chặng đường đi bộ","tieu_de":"Hàng trăm cây số bằng đôi chân: ông Thầu Chín đi khắp các xóm Việt kiều","sapo":"Từ Phichit bên sông Nan đến bờ Mê Kông ở Nakhon Phanom, riêng khoảng cách theo đường chim bay đã gần năm trăm cây số. Ông Thầu Chín đã nối các xóm Việt kiều rải rác trên quãng đường ấy phần lớn bằng chính đôi chân mình, có đêm phải ngủ lại giữa rừng. Những chặng đường đi bộ không chỉ là cách di chuyển: đó là cách một cộng đồng rời rạc được dệt thành một mạng lưới.","bia":{"src":"textures/bai/G10_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1841},{"i":9,"tieu_de_bang":"Sông Mê Kông","tieu_de":"Sông Mê Kông ở Nakhon Phanom: một dòng sông, ba đất nước","sapo":"Chiều xuống ở Nakhon Phanom, mặt sông Mê Kông rộng mênh mông, bên kia là những dãy núi đá vôi của đất Lào. Gần một thế kỷ trước, ông Thầu Chín từng sống cách bờ sông này không xa, ban ngày làm vườn, tối đi đánh cá như bà con trong xóm. Với Người, dòng sông vừa là đường biên phải canh chừng, vừa là con đường bí mật dẫn về quê hương.","bia":{"src":"textures/bai/G10_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1692}],"do_vat":[{"id":"well@9.0,6.0","x":9,"y":0.25,"z":6,"loai":"well","ten":"Giếng nước","tieu_de":"Chiếc giếng của xóm Việt kiều"},{"id":"rusted_spade_01@-2.4,-1.9","x":-2.4,"y":0.3,"z":-1.9,"loai":"rusted_spade_01","ten":"Chiếc mai đào đất","tieu_de":"Cầm mai cùng bà con"},{"id":"wooden_bucket_02@3.6,2.6","x":3.6,"y":0.3,"z":2.6,"loai":"wooden_bucket_02","ten":"Thùng gỗ múc nước","tieu_de":"Những gánh nước trong xóm"},{"id":"jar@3.8,1.8","x":3.8,"y":0.3,"z":1.8,"loai":"jar","ten":"Chum đựng nước","tieu_de":"Chum nước bên hiên nhà"},{"id":"phan@-1.6,-0.9","x":-1.6,"y":1.2,"z":-0.9,"loai":"phan","ten":"Chiếc phản gỗ","tieu_de":"Chỗ nằm của ông Thầu Chín"},{"id":"table@1.8,-1.3","x":1.8,"y":1.2,"z":-1.3,"loai":"table","ten":"Bàn viết","tieu_de":"Nơi những trang báo Thân Ái được viết"},{"id":"table@1.8,-0.8","x":1.8,"y":1.2,"z":-0.75,"loai":"table","ten":"Bàn học của lớp chữ quốc ngữ","tieu_de":"Lớp học buổi tối"},{"id":"vintage_oil_lamp@2.1,-1.4","x":2.15,"y":1.92,"z":-1.4,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"Ngọn đèn của những đêm dạy chữ"},{"id":"binder_notebook@1.6,-1.3","x":1.6,"y":1.92,"z":-1.3,"loai":"binder_notebook","ten":"Tập giấy ghi chép","tieu_de":"Học tiếng Xiêm, dịch sách"},{"id":"treasure_chest@2.3,0.6","x":2.3,"y":1.2,"z":0.6,"loai":"treasure_chest","ten":"Hòm gỗ","tieu_de":"Chiếc hòm cất sách báo"}]},"G11":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Hồng Kông – Thành lập Đảng","tieu_de":"Hương Cảng 1930 – 1933: từ căn phòng khai sinh chính đảng đến xà lim nhà tù Victoria","sapo":"Có một thành phố mà chỉ trong chưa đầy ba năm, Nguyễn Ái Quốc vừa khai sinh một chính đảng, vừa đứng trước nguy cơ bị trao cho chính kẻ đã kết án tử hình mình. Đó là Hồng Kông, nơi người Việt xưa gọi là Hương Cảng. Từ căn phòng nhỏ ở Cửu Long đến xà lim nhà tù Victoria, rồi tới phòng xử án ở tận Luân Đôn, đây là câu chuyện của những năm 1930 – 1933.","bia":{"src":"textures/bai/G11_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2375},{"i":1,"tieu_de_bang":"Từ Xiêm đến Cửu Long: lời triệu tập hợp nhất","tieu_de":"Ba tổ chức, một lời triệu tập: hành trình từ đất Xiêm đến căn phòng nhỏ ở Cửu Long","sapo":"Mùa hè năm 1929, phong trào cộng sản Việt Nam vừa lớn mạnh đã tự chia làm ba. Ở tận nước Xiêm, người đàn ông mà kiều bào quen gọi là Thầu Chín nhận được tin và quyết định lên đường, dù trên đầu đang treo một bản án tử hình. Hai tháng sau khi Người đặt chân tới Hương Cảng, ba ngả đường ấy đã nhập làm một.","bia":{"src":"textures/bai/G11_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2183},{"i":2,"tieu_de_bang":"Luật sư Loseby và người tù Tống Văn Sơ","tieu_de":"Một luật sư Anh và người tù châu Á: nghĩa tình từ nhà tù Victoria đến sân bay Gia Lâm","sapo":"Những ngày giáp Tết Canh Tý 1960, Chủ tịch Hồ Chí Minh đích thân ra sân bay Gia Lâm đón một ông già người Anh cùng vợ và con gái. Gần ba mươi năm trước, người ấy đã đứng ra bảo vệ một người tù châu Á mang cái tên xa lạ Tống Văn Sơ, bất chấp sức ép của nhà cầm quyền Pháp. Đây là câu chuyện về luật sư Frank Loseby và một nghĩa tình được giữ trọn suốt ba thập kỷ.","bia":{"src":"textures/bai/G11_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2036},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Hàm Long, Cửu Long đến Luân Đôn: những mốc thời gian 1929 – 1933","sapo":"Chỉ trong hơn ba năm, Hồng Kông chứng kiến cả sự ra đời của một chính đảng lẫn cuộc đấu tranh giành lại tự do cho người sáng lập ra nó. Ba mươi hai mốc dưới đây đi từ ngôi nhà 5D Hàm Long năm 1929 đến sân bay Gia Lâm năm 1960. Đặt cạnh nhau, chúng cho thấy những quyết định lớn đã được đưa ra trong những khoảng thời gian ngắn đến bất ngờ.","bia":{"src":"textures/bai/G11_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1568},{"i":4,"tieu_de_bang":"Tống Văn Sơ (Nguyễn Ái Quốc) tại nhà tù Victoria","tieu_de":"Người tù mang tên Tống Văn Sơ: một tấm ảnh, ba chữ Hán và những cái tên của một đời hoạt động bí mật","sapo":"Hồ sơ nhà tù Victoria ghi người trong ảnh là Tống Văn Sơ. Nhưng nhà cầm quyền Pháp biết rõ họ đang nhắm tới ai: Nguyễn Ái Quốc, người họ đã truy lùng hơn mười năm. Tấm ảnh nhỏ ấy mở ra câu chuyện về những cái tên, tấm áo giáp vô hình của người cách mạng sống giữa vòng vây mật thám nhiều nước.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_sung_man_cho_victoria_prison_1930.jpg","credit":"Ảnh: Victoria Prison · Public domain · Wikimedia Commons"},"so_chu":1947},{"i":5,"tieu_de_bang":"Ảnh hồ sơ Tống Văn Sơ, 1931","tieu_de":"Từ Singapore đến số nhà 186 Tam Kung: tấm ảnh hồ sơ năm 1931 và cuộc truy lùng xuyên biên giới","sapo":"Đầu tháng 6/1931, giấy tờ thu được từ một người Pháp bị bắt ở Singapore đã để lộ một địa chỉ ở Hồng Kông. Chỉ ít ngày sau, cảnh sát ập vào nơi ở của người đàn ông tên Tống Văn Sơ ở Cửu Long. Tấm ảnh hồ sơ lập năm 1931 là dấu vết còn lại của cuộc truy lùng ấy, một cuộc truy lùng mà đích nhắm là Nguyễn Ái Quốc.","bia":{"src":"textures/ht/ht_anh_sung_man_cho_ho_chi_minh_1931.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1962},{"i":6,"tieu_de_bang":"Nguyễn Ái Quốc trong bộ áo dài lụa (1932 – 1933)","tieu_de":"Chiếc áo lụa và con tàu Anhui: cuộc ra đi bí mật khỏi Hồng Kông đầu năm 1933","sapo":"Ngày 22/1/1933, một thương gia người Hoa khá giả bước lên con tàu Anhui ở Hồng Kông, bên cạnh là thư ký của một văn phòng luật sư người Anh. Không mấy ai ngờ đó là Nguyễn Ái Quốc, người vừa trải qua gần hai mươi tháng trong vòng vây của nhà tù và tòa án. Tấm ảnh Người trong bộ áo dài lụa kiểu Trung Hoa, được xếp vào khoảng năm 1932 – 1933, gợi lại chương cuối đầy hồi hộp ấy.","bia":{"src":"textures/ht/ht_anh_nguyen_ai_quoc_in_silk_gown_made_by_rosa_loseby.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1936},{"i":7,"tieu_de_bang":"Cửu Long, Hồng Kông những năm 1930","tieu_de":"Cửu Long, vùng đất “chín con rồng”: đồi Tống Vương, phố thuộc địa và dấu chân những người cách mạng Việt Nam","sapo":"Tấm ảnh chụp khoảng những năm 1930 được lưu trữ với cái tên Tống Vương Đài, “đài của vua Tống”. Nó dẫn ta về một Cửu Long nhiều lớp thời gian: truyền thuyết những vị vua nhỏ tuổi chạy trốn quân Nguyên, một bán đảo bị cắt nhượng cho Anh, và những khu phố lao động đông đúc. Chính ở đó, năm 1930, những người cộng sản Việt Nam đã bí mật họp bàn việc thống nhất lực lượng.","bia":{"src":"textures/ht/ht_anh_sung_wong_toi_in_1930s.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1921},{"i":8,"tieu_de_bang":"Nhà tù Victoria, Hồng Kông, nơi Người bị giam 1931 – 1932","tieu_de":"Nhà tù Victoria: những bức tường giữa Trung Hoàn và hai mươi tháng của người tù Tống Văn Sơ","sapo":"Giữa khu Trung Hoàn sầm uất của đảo Hồng Kông có một quần thể nhà tù đã đứng đó từ những ngày đầu của thuộc địa Anh. Khối nhà trong tấm ảnh chụp năm 2012 được dựng từ năm 1860, hơn bảy mươi năm trước khi một người tù mang tên Tống Văn Sơ bị đưa tới. Người tù ấy là Nguyễn Ái Quốc, và phía sau những bức tường này, Người đã sống gần hai năm hiểm nghèo nhất của đời hoạt động bí mật.","bia":{"src":"textures/ht/ht_anh_victoria_prison_block_d.jpg","credit":"Ảnh: Zhu yihan · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1956},{"i":9,"tieu_de_bang":"Hội nghị hợp nhất (6/1 – 7/2/1930)","tieu_de":"Hội nghị hợp nhất ở Cửu Long: năm điểm nghị sự và bản Cương lĩnh chính trị đầu tiên","sapo":"Trên chiếc bàn của một căn nhà nhỏ ở Cửu Long đầu năm 1930 có những văn kiện mà tên gọi đều kèm hai chữ “vắn tắt” hay “tóm tắt”. Những trang giấy ngắn gọn ấy trả lời các câu hỏi lớn nhất của cách mạng Việt Nam: đi tới đâu, đi cùng ai, tổ chức ra sao. Bảng hiện vật này mở từng văn kiện ra đọc lại, và lần theo tiếng vọng của chúng qua gần một thế kỷ.","bia":{"src":"textures/bai/G11_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2063},{"i":10,"tieu_de_bang":"Vụ án Tống Văn Sơ","tieu_de":"Vụ án Tống Văn Sơ: cuộc đấu pháp lý từ Hồng Kông đến Hội đồng Cơ mật ở London","sapo":"Nhà cầm quyền Pháp muốn đưa người tù về Đông Dương, nơi một bản án tử hình vắng mặt đang chờ. Một luật sư Anh cùng các đồng nghiệp của ông tin rằng luật pháp không cho phép điều đó. Cuộc đấu pháp lý giữa hai phía kéo dài gần hai năm, đi qua hai lệnh trục xuất, một phiên tòa ở Hồng Kông và một cuộc điều đình ở tận Luân Đôn.","bia":{"src":"textures/bai/G11_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1615},{"i":11,"tieu_de_bang":"Tháp đồng hồ Tiêm Sa Chủy","tieu_de":"Tháp đồng hồ Tiêm Sa Chủy: chứng nhân gạch đỏ của Cửu Long xưa","sapo":"Bên bờ cảng Victoria, một tháp đồng hồ gạch đỏ đã đứng đó hơn một thế kỷ, dù ga xe lửa mà nó từng thuộc về đã biến mất từ lâu. Nó là dấu tích còn lại của tuyến đường sắt nối Cửu Long với Quảng Châu — thành phố gắn bó sâu sắc với những năm tháng hoạt động của Nguyễn Ái Quốc.","bia":{"src":"textures/bai/G11_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1717}],"do_vat":[{"id":"table@10.6,6.6","x":10.6,"y":0.4,"z":6.6,"loai":"table","ten":"Bàn họp Hội nghị hợp nhất","tieu_de":"Quanh một chiếc bàn gỗ giản dị"},{"id":"vintage_oil_lamp@10.6,6.9","x":10.6,"y":1.18,"z":6.9,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"Ánh đèn của một cuộc họp bí mật"},{"id":"book_encyclopedia_set_01@9.2,3.1","x":9.2,"y":2.16,"z":3.06,"loai":"book_encyclopedia_set_01","ten":"Chồng sách","tieu_de":"Từ Đường Kách mệnh đến Chánh cương vắn tắt"},{"id":"alarm_clock_01@10.2,3.1","x":10.2,"y":2.16,"z":3.06,"loai":"alarm_clock_01","ten":"Đồng hồ","tieu_de":"Vì sao là ngày 3 tháng 2?"},{"id":"vintage_suitcase@15.8,3.7","x":15.75,"y":0.4,"z":3.7,"loai":"vintage_suitcase","ten":"Chiếc va li","tieu_de":"Hành trang của người cách mạng không nhà"},{"id":"old_bed_frame@15.4,9.8","x":15.45,"y":0.4,"z":9.8,"loai":"old_bed_frame","ten":"Chiếc giường cũ","tieu_de":"Nơi ở của Tống Văn Sơ"}]},"G12":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Pác Bó – Cao Bằng","tieu_de":"Pác Bó 1941 – 1945: bốn năm ở đầu nguồn và con đường tới ngày độc lập","sapo":"Mùng 2 Tết Tân Tỵ, tức ngày 28/1/1941, một người đàn ông năm mươi tuổi mà bà con sau này quen gọi là Già Thu bước qua cột mốc biên giới 108 vào thung lũng Pác Bó. Hơn bốn năm sau, cũng từ thung lũng đầu nguồn ấy, Người lên đường về Tân Trào để lãnh đạo Tổng khởi nghĩa. Giữa hai mốc đó là một mặt trận, một tờ báo, một bài sử ca, những lớp học giữa rừng và đội quân chủ lực đầu tiên. Gian trưng bày này đưa bạn đi lại chặng đường ấy.","bia":{"src":"textures/bai/G12_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2263},{"i":1,"tieu_de_bang":"“Lịch sử nước ta” và dự báo năm 1945","tieu_de":"“Dân ta phải biết sử ta”: tập sử ca viết ở Cao Bằng và dòng chữ “1945 – Việt Nam độc lập”","sapo":"Đầu năm 1942, khi nước ta còn chìm dưới ách Pháp – Nhật, Việt Minh phát hành một tập sách nhỏ kể lịch sử dân tộc bằng thơ lục bát. Ở trang cuối, trong bảng những năm quan trọng, tác giả ghi một mốc chưa hề xảy ra: “1945 – Việt Nam độc lập”. Ba năm sau, dòng chữ ấy thành sự thật. Tác giả là Nguyễn Ái Quốc, khi ấy đang sống giữa núi rừng Cao Bằng.","bia":{"src":"textures/bai/G12_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2153},{"i":2,"tieu_de_bang":"34 chiến sĩ đầu tiên (22/12/1944)","tieu_de":"Ba mươi tư chiến sĩ trong rừng Trần Hưng Đạo: ngày khai sinh đội quân chủ lực đầu tiên","sapo":"Ba mươi tư người, ba mươi tư khẩu súng, phần lớn là súng trường và súng kíp. Đó là toàn bộ lực lượng làm lễ thành lập trong một khu rừng ở Nguyên Bình, Cao Bằng, ngày 22/12/1944. Bản chỉ thị ngắn của Hồ Chí Minh gọi đội quân nhỏ ấy là “khởi điểm của giải phóng quân”. Ba ngày sau, họ đánh trận đầu tiên, và thắng.","bia":{"src":"textures/bai/G12_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1916},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ cột mốc 108 đến đường về Tân Trào: dòng thời gian Pác Bó 1940 – 1945","sapo":"Từ ngày qua cột mốc 108 đến ngày rời Pác Bó là hơn bốn năm ba tháng, nhưng Người chỉ thật sự ở vùng căn cứ khoảng một nửa quãng thời gian ấy. Phần còn lại là những tháng bị giam cầm và những chuyến đi xa. Dòng thời gian dưới đây xếp lại các mốc để thấy một nhịp điệu rõ ràng: chuẩn bị, chờ đợi, rồi chớp thời cơ.","bia":{"src":"textures/bai/G12_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1422},{"i":4,"tieu_de_bang":"Hang Cốc Bó, nơi Người ở những ngày đầu về nước","tieu_de":"Hang Cốc Bó qua một tấm ảnh: tám mươi mét vuông đá và mùa xuân năm 1941","sapo":"Một khoảng tối nhỏ dưới chân vách núi đá vôi, trước mặt là dòng suối trong. Nhìn thoáng qua, tấm ảnh chụp đầu năm 2016 chỉ như một góc thắng cảnh miền biên viễn. Nhưng sau cửa hang hẹp ấy, bảy mươi lăm năm trước, người vừa trở về sau ba mươi năm xa Tổ quốc đã sống những tuần giá rét đầu tiên trên quê hương. Vì sao Người chọn một hang đá làm nhà, và điều gì đã giữ an toàn cho Người?","bia":{"src":"textures/ht/ht_anh_coc_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1917},{"i":5,"tieu_de_bang":"Suối Lê-nin dưới chân núi Các Mác","tieu_de":"Suối Lê-nin, núi Các Mác: hai cái tên Nguyễn Ái Quốc gửi vào núi sông đầu nguồn","sapo":"Một dòng suối xanh trong chảy dưới chân ngọn núi đá vôi, cảnh vật như bao thung lũng khác ở miền biên viễn Cao Bằng. Điều khác biệt nằm ở tên gọi. Mùa xuân năm 1941, người vừa trở về sau ba mươi năm đã đặt cho dòng suối và ngọn núi tên của hai con người mà Người coi là những bậc soi đường. Câu chuyện của hai cái tên ấy bắt đầu từ một trang báo ở Paris hơn hai mươi năm trước.","bia":{"src":"textures/ht/ht_anh_pac_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1966},{"i":6,"tieu_de_bang":"Lời Bác: “Cuộc đời cách mạng thật là sang”","tieu_de":"Bốn câu thơ bên suối Lê-nin: vì sao cuộc đời cách mạng lại “thật là sang”?","sapo":"Hang đá ẩm lạnh, bữa ăn chỉ có cháo ngô và rau măng, bàn làm việc là một phiến đá chênh vênh bên suối. Vậy mà người chiến sĩ năm mươi tuổi, vừa trở về sau ba mươi năm xa Tổ quốc, lại kết luận: cuộc đời cách mạng “thật là sang”. Bốn câu thơ viết năm 1941 ở Pác Bó giấu trong mình cả một quan niệm sống.","bia":{"src":"textures/ht/ht_anh_pac_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1851},{"i":7,"tieu_de_bang":"Trở về Tổ quốc (28/1/1941)","tieu_de":"Cột mốc 108, trưa mùng 2 Tết Tân Tỵ: ba mươi năm khép lại trong một bước chân","sapo":"Trưa 28/1/1941, khi bà con vùng biên còn đang vui Tết, một nhóm nhỏ lặng lẽ vượt qua cột mốc đá ở đầu thung lũng Pác Bó. Trong nhóm có một người đã rời Tổ quốc từ mùa hè năm 1911. Để đi tới bước chân ấy, Người đã vòng qua Diên An, Quế Lâm, Côn Minh và một lớp học nhỏ sát biên giới.","bia":{"src":"textures/bai/G12_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1979},{"i":8,"tieu_de_bang":"Hang Cốc Bó","tieu_de":"Bên trong hang Cốc Bó: giường gỗ kê trên đá, bếp lửa nhỏ và chiếc hòm tài liệu","sapo":"Cửa hang hẹp đến mức chỉ một người lách qua được. Bên trong, mấy cây gỗ gác lên tảng đá là giường, một bếp lửa nhỏ là lò sưởi, một chiếc hòm gỗ là tủ hồ sơ. Đó là toàn bộ nơi ăn chốn ở của người đứng đầu phong trào cách mạng Việt Nam mùa xuân năm 1941. Căn nhà bằng đá ấy kể gì về con người đã sống trong nó?","bia":{"src":"textures/ht/ht_anh_coc_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1963},{"i":9,"tieu_de_bang":"Bàn đá bên suối Lê-nin","tieu_de":"“Bàn đá chông chênh”: văn phòng giữa trời bên suối Lê-nin","sapo":"Không bàn ghế, không đèn, không mái che. Mỗi ngày, người đàn ông năm mươi tuổi mà bà con gọi là Già Thu ra ngồi bên một phiến đá cạnh suối, đặt giấy lên mặt đá gồ ghề và bắt đầu viết. Từ “văn phòng” giữa trời ấy, những trang sách lý luận được chuyển sang tiếng Việt, những tài liệu huấn luyện đầu tiên của vùng căn cứ ra đời.","bia":{"src":"textures/bai/G12_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1921},{"i":10,"tieu_de_bang":"Lán Khuổi Nặm","tieu_de":"Lán Khuổi Nặm, tháng 5/1941: căn nhà sàn mười hai mét vuông nơi Mặt trận Việt Minh ra đời","sapo":"Căn lán chỉ rộng chừng mười hai mét vuông, chia làm hai gian nhỏ, nép ngay bìa rừng. Từ bên ngoài nhìn vào không thấy, nhưng từ trong nhìn ra thì rõ mọi lối đi. Trong mười ngày tháng 5/1941, dưới mái lán ấy, Hội nghị Trung ương lần thứ tám do Nguyễn Ái Quốc chủ trì đã đưa ra những quyết định làm xoay chuyển vận mệnh dân tộc.","bia":{"src":"textures/bai/G12_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2128}],"do_vat":[{"id":"treasure_chest@-14.6,-49.0","x":-14.6,"y":0.55,"z":-49,"loai":"treasure_chest","ten":"Chiếc hòm gỗ","tieu_de":"Nơi cất giữ tài liệu trong hang đá"},{"id":"wooden_bowl_01@-15.1,-46.8","x":-15.1,"y":0.55,"z":-46.8,"loai":"wooden_bowl_01","ten":"Bát gỗ","tieu_de":"“Cháo bẹ rau măng vẫn sẵn sàng”"},{"id":"binder_notebook@2.2,-11.9","x":2.24,"y":1.17,"z":-11.95,"loai":"binder_notebook","ten":"Cuốn sổ bản dịch","tieu_de":"Những trang dịch “sử Đảng” bên suối"},{"id":"book_encyclopedia_set_01@2.8,-12.2","x":2.79,"y":1.17,"z":-12.15,"loai":"book_encyclopedia_set_01","ten":"Sách và tài liệu huấn luyện","tieu_de":"Những cuốn sách nhỏ cho đồng bào"},{"id":"table@23.1,-18.1","x":23.08,"y":1.64,"z":-18.1,"loai":"table","ten":"Bàn trong lán Khuổi Nặm","tieu_de":"Nơi Hội nghị Trung ương lần thứ tám làm việc"},{"id":"vintage_oil_lamp@23.1,-18.1","x":23.08,"y":2.24,"z":-18.1,"loai":"vintage_oil_lamp","ten":"Ngọn đèn trong lán","tieu_de":"Tờ báo Việt Nam độc lập ra đời giữa rừng"}]},"G13":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Tân Trào – Thủ đô Khu giải phóng","tieu_de":"Tân Trào, chín mươi ba ngày: thung lũng nhỏ trở thành thủ đô của cách mạng","sapo":"Chiều 21/5/1945, sau mười tám ngày đêm vượt rừng từ Pác Bó, một đoàn cán bộ nhỏ dừng chân dưới mái đình Hồng Thái. Người dẫn đầu đoàn vừa bước sang tuổi năm mươi lăm ngay trên đường hành quân. Ba tháng sau, khi rời thung lũng này về Hà Nội, Người đã là Chủ tịch Ủy ban Dân tộc giải phóng Việt Nam. Điều gì đã diễn ra ở Tân Trào trong chín mươi ba ngày ấy?","bia":{"src":"textures/bai/G13_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2281},{"i":1,"tieu_de_bang":"Cơn sốt ở lán Nà Nưa","tieu_de":"Cơn sốt ở lán Nà Nưa: khi thời cơ đến bên giường bệnh","sapo":"Mùa hè năm 1945, khi thời cơ giành độc lập đã đến rất gần, người đứng đầu phong trào lại lên cơn sốt cao trong một chiếc lán nứa giữa rừng. Bên Người khi ấy có một người chỉ huy quân sự trẻ tuổi, một cụ lang người Tày và cả một y tá người Mỹ. Từ trong cơn bệnh ấy vang lên một lời dặn đã đi vào lịch sử.","bia":{"src":"textures/bai/G13_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1999},{"i":2,"tieu_de_bang":"Hai ngày dưới mái đình Tân Trào","tieu_de":"Hai ngày dưới mái đình Tân Trào: nơi một nhà nước được chuẩn bị trên sàn gỗ làng","sapo":"Không có hội trường, không có nghi lễ cầu kỳ. Tháng 8/1945, hơn 60 đại biểu của ba miền đất nước và cả kiều bào ở nước ngoài ngồi lại dưới mái một ngôi đình gỗ ở Tuyên Quang. Hai ngày họp ấy đã trao cho cả dân tộc một cơ quan lãnh đạo, một lá cờ, một bài ca và một hiệu lệnh.","bia":{"src":"textures/bai/G13_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2036},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Pác Bó đến Ba Đình: năm 1945 qua từng mốc ngày","sapo":"Chưa đầy sáu tháng tách đêm đảo chính 9/3 khỏi ngày Tuyên ngôn Độc lập 2/9/1945. Trong khoảng thời gian ngắn ngủi ấy, chiếc đồng hồ của Chiến tranh thế giới và nhịp sống ở một thung lũng nhỏ Tuyên Quang đã khớp vào nhau đến từng ngày. Dòng thời gian dưới đây đặt Tân Trào vào giữa những biến động ấy.","bia":{"src":"textures/bai/G13_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1594},{"i":4,"tieu_de_bang":"Lán Nà Nưa (Nà Lừa), nơi Người ở và làm việc 5–8/1945","tieu_de":"Lán Nà Nưa: căn lán nứa giữa rừng, nơi đặt “bộ chỉ huy” của cách mạng mùa hè 1945","sapo":"Một căn lán nhỏ bằng tre nứa, mái lợp lá cọ, đứng lặng trên sườn đồi giữa rừng Tuyên Quang. Không tường gạch, không biển hiệu, chẳng khác chòi canh nương của một gia đình miền núi. Vậy mà suốt mùa hè năm 1945, mọi đầu mối của phong trào cách mạng cả nước đều quy về đây. Vì sao Người chọn nơi này, và căn lán đã sống qua những ngày tháng ấy ra sao?","bia":{"src":"textures/ht/ht_anh_lan_na_lua.jpg","credit":"Ảnh: Liftold (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1944},{"i":5,"tieu_de_bang":"Đình Tân Trào, nơi họp Quốc dân Đại hội 16 – 17/8/1945","tieu_de":"Dưới mái đình Tân Trào: nơi ra đời quốc kỳ, quốc ca và Chính phủ lâm thời","sapo":"Ngôi đình gỗ trong ảnh trông chẳng khác bao ngôi đình làng miền núi: sàn cao, cột gỗ, mái lợp lá cọ. Vậy mà tháng 8/1945, dưới mái đình này, một lá cờ, một bài ca và một cơ quan lãnh đạo của cả nước lần đầu được chính thức xác định. Mỗi biểu tượng ấy đã đi một chặng đường dài trước khi về tới thung lũng Tân Trào, và còn đi xa hơn nhiều sau khi rời đi.","bia":{"src":"textures/ht/ht_anh_dinh_tan_trao.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1743},{"i":6,"tieu_de_bang":"Cây đa Tân Trào, nơi Giải phóng quân xuất phát về xuôi","tieu_de":"Dưới gốc đa Tân Trào: từ đội quân 34 chiến sĩ đến lễ xuất quân tháng Tám","sapo":"Chiều 16/8/1945, dưới tán cây đa đầu làng Tân Trào, những người lính Giải phóng quân nhận lệnh lên đường về xuôi. Chưa đầy tám tháng trước đó, đội quân tiền thân của họ mới chỉ có 34 chiến sĩ trong một khu rừng ở Cao Bằng. Hơn sáu mươi năm sau, chính cây đa chứng nhân ấy lại suýt chết, và cả một tỉnh đã chung sức cứu nó.","bia":{"src":"textures/ht/ht_anh_cay_da_lich_su_tan_trao.jpg","credit":"Ảnh: Liftold (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1664},{"i":7,"tieu_de_bang":"Giải phóng quân duyệt binh ở Nhà hát Lớn, 28/8/1945","tieu_de":"Từ rừng núi Việt Bắc về Nhà hát Lớn: Giải phóng quân duyệt binh giữa Thủ đô","sapo":"Mười hai ngày sau lễ xuất quân dưới cây đa Tân Trào, những người lính từ chiến khu đã đứng thành hàng giữa quảng trường sang trọng bậc nhất Hà Nội. Quảng trường ấy vốn dành cho người Âu và giới nói tiếng Pháp, nay thuộc về một đội quân từ rừng núi về. Tấm ảnh tư liệu ghi ngày 28/8/1945 giữ lại khoảnh khắc hiếm hoi đó, và đằng sau nó là một tuần lễ mà cả đất nước đổi thay.","bia":{"src":"textures/ht/ht_anh_ngay_28_08_1945_doan_giai_phong_quan_o_viet_bac_.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"so_chu":1717},{"i":8,"tieu_de_bang":"Cây đa Tân Trào","tieu_de":"Cây đa Tân Trào: chứng nhân sống của buổi chiều xuất quân tháng Tám","sapo":"Chiều 16/8/1945, dưới tán một cây đa đầu làng, một đội quân nghe đọc lệnh Tổng khởi nghĩa rồi lên đường về xuôi. Hơn sáu mươi năm sau, chính cây đa ấy suýt chết khô, và người ta đã phải chạy chữa cho nó suốt hai năm. Câu chuyện về cây đa Tân Trào vì thế vừa là câu chuyện của một buổi chiều lịch sử, vừa là hành trình giữ lại một chứng nhân còn sống.","bia":{"src":"textures/ht/ht_anh_cay_da_lich_su_tan_trao.jpg","credit":"Ảnh: Liftold (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":2018},{"i":9,"tieu_de_bang":"Đình Tân Trào","tieu_de":"Đình Tân Trào: khi ngôi nhà chung của một làng trở thành nơi bàn việc nước","sapo":"Ngôi đình gỗ ba gian, sàn cao, mái lợp lá cọ vốn chỉ dành cho việc làng: thờ thành hoàng, hội hè, bàn chuyện chung. Tháng 8/1945, hơn 60 đại biểu từ khắp ba miền đã về họp dưới mái đình ấy. Những điều được quyết định và thề nguyện ở đây khiến ngôi đình nhỏ về sau được nhắc tới như nơi khởi đầu con đường đi tới Quốc hội Việt Nam.","bia":{"src":"textures/ht/ht_anh_dinh_tan_trao.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1894},{"i":10,"tieu_de_bang":"Lán Nà Nưa","tieu_de":"Lán Nà Nưa: căn nhà sàn chưa đầy mười hai mét vuông và nếp sống của “ông Ké” mùa hè 1945","sapo":"Dài 4,2 mét, rộng 2,7 mét, chia làm hai gian: gian trong để ngủ, gian ngoài để làm việc và tiếp khách. Đó là toàn bộ nơi ở của người đứng đầu phong trào cách mạng cả nước trong gần ba tháng quyết định của năm 1945. Người dân quanh Tân Trào khi ấy gọi Người bằng một cái tên giản dị, thân mật: ông Ké.","bia":{"src":"textures/ht/ht_anh_lan_na_lua.jpg","credit":"Ảnh: Liftold (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1564}],"do_vat":[{"id":"table@26.7,-50.1","x":26.7,"y":11.04,"z":-50.06,"loai":"table","ten":"Bàn làm việc trong lán Nà Nưa","tieu_de":"Bộ bàn tre của Bác ở Nà Nưa"},{"id":"vintage_oil_lamp@26.7,-50.1","x":26.7,"y":11.66,"z":-50.06,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"Ánh đèn những đêm tháng Tám"},{"id":"binder_notebook@26.4,-50.0","x":26.45,"y":11.66,"z":-50.02,"loai":"binder_notebook","ten":"Tập giấy tờ","tieu_de":"Những trang viết từ Tân Trào"},{"id":"wicker_basket_02@30.4,-49.8","x":30.43,"y":11.04,"z":-49.77,"loai":"wicker_basket_02","ten":"Giỏ đan","tieu_de":"Tấm lòng đồng bào Tày Tân Trào"},{"id":"table@-18.1,-7.4","x":-18.14,"y":1.15,"z":-7.39,"loai":"table","ten":"Bàn trong đình","tieu_de":"Từ việc làng đến việc nước"}]},"G14":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Hà Nội 1945 – Ba Đình","tieu_de":"Hà Nội 1945–1946: mười sáu tháng giữ một nền độc lập","sapo":"Cuối tháng Tám năm 1945, một vị khách gầy gò từ chiến khu Việt Bắc lặng lẽ bước lên căn gác của một hiệu lụa trên phố Hàng Ngang. Một tuần sau, hàng chục vạn người lần đầu được nghe giọng nói của Người ở Quảng trường Ba Đình. Rồi suốt mười sáu tháng tiếp theo, nhà nước vừa ra đời phải cùng lúc chống giặc đói, giặc dốt và giặc ngoại xâm. Gian trưng bày này mời bạn bước vào chính những tháng ngày ấy.","bia":{"src":"textures/bai/G14_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2379},{"i":1,"tieu_de_bang":"Tuần lễ Vàng: cả nước góp vàng giữ độc lập","tieu_de":"Tuần lễ Vàng: ngân khố quốc gia từ những chiếc nhẫn, đôi hoa tai","sapo":"Nhà nước mới ra đời với một ngân khố gần như trống rỗng. Vậy mà chỉ trong một tuần của tháng 9/1945, từ những gia đình buôn bán khá giả trên phố Hàng Ngang đến những người dân nghèo ở thôn quê, đồng bào cả nước đã góp nên hàng trăm kilôgam vàng. Điều gì khiến người ta trao chiếc nhẫn, đôi hoa tai của mình cho một chính phủ ra đời chưa đầy một tháng?","bia":{"src":"textures/bai/G14_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2173},{"i":2,"tieu_de_bang":"Diệt giặc dốt: những lớp Bình dân học vụ","tieu_de":"“Vợ chưa biết thì chồng bảo”: cuộc chiến chống giặc dốt mùa thu 1945","sapo":"Năm 1945, cứ một trăm người Việt Nam thì chừng chín mươi lăm người không biết đọc, biết viết. Chỉ khoảng một năm sau, hai triệu rưỡi người đã tự tay viết được tên mình. Cuộc chiến chống “giặc dốt” ấy diễn ra gần như không có trường sở, không có ngân sách, mà trên lá chuối, dưới ánh đèn dầu, theo lời kêu gọi của một vị Chủ tịch.","bia":{"src":"textures/bai/G14_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2160},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ căn gác Hàng Ngang đến đêm 19/12: 31 mốc của 481 ngày lập quốc","sapo":"Chưa đầy mười sáu tháng tách ngày Người về Hà Nội với đêm toàn quốc kháng chiến. Trong 481 ngày ấy, một nhà nước được khai sinh, có Chính phủ, có Quốc hội, có Hiến pháp, và đứng vững trước thù trong giặc ngoài. Đặt các mốc cạnh nhau, ta nghe thấy nhịp thở dồn dập của những ngày lập quốc.","bia":{"src":"textures/bai/G14_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1537},{"i":4,"tieu_de_bang":"Quảng trường Ba Đình ngày 2/9/1945","tieu_de":"Biển người ở Ba Đình: ai đã có mặt chiều 2/9/1945?","sapo":"Tấm ảnh đen trắng không ghi tên người chụp, cũng không ghi tên một ai trong đám đông. Vậy mà nó là một trong những chân dung đầy đủ nhất của dân tộc Việt Nam trong ngày Độc lập. Họ là ai, từ đâu đến, đã cùng nhau thề điều gì, và số phận họ ra sao sau buổi chiều ấy?","bia":{"src":"textures/ht/ht_anh_ba_dinh_square_september_2nd_1945.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1586},{"i":5,"tieu_de_bang":"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, 2/9/1945","tieu_de":"“Tôi nói, đồng bào nghe rõ không?”: khoảnh khắc trên lễ đài Ba Đình","sapo":"Trong tấm ảnh đen trắng, vị Chủ tịch nước đứng trên lễ đài giữa biển người, trong bộ áo ka-ki giản dị. Không ai dưới quảng trường hôm ấy biết rằng giữa bài đọc, Người sẽ dừng lại để hỏi một câu không hề có trong văn bản. Ai đã bấm máy ghi lại khoảnh khắc ấy, ai đã quay những thước phim còn lại đến hôm nay — và vì sao một câu hỏi giản dị lại trở thành ký ức chung của cả dân tộc?","bia":{"src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},"so_chu":1883},{"i":6,"tieu_de_bang":"Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp, 1945","tieu_de":"Người thầy và người học trò: Chủ tịch Hồ Chí Minh và Võ Nguyên Giáp năm 1945","sapo":"Trong tấm ảnh năm 1945, vị Chủ tịch nước năm mươi lăm tuổi đứng bên người Bộ trưởng Bộ Nội vụ vừa bước sang tuổi ba mươi tư. Năm năm trước, họ mới gặp nhau lần đầu ở Côn Minh, bên kia biên giới. Giữa hai khoảnh khắc ấy là những năm ở Cao Bằng, là khu rừng nơi ba mươi tư chiến sĩ làm lễ thành lập đội, và một lời dặn giữa cơn sốt ở Tân Trào mà người học trò nhớ suốt đời.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_and_vo_nguyen_giap_1945.jpg","credit":"Ảnh: An Ninh Võ · Public domain · Wikimedia Commons"},"so_chu":1942},{"i":7,"tieu_de_bang":"Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa","tieu_de":"Nội các của cả dân tộc: Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa","sapo":"Trong danh sách mười lăm thành viên Chính phủ lâm thời công bố ngày 28/8/1945 có một nhà thơ hai mươi sáu tuổi, một học giả đứng đầu hội truyền bá chữ quốc ngữ, một bác sĩ đang ở Sài Gòn và một trí thức Công giáo. Họ không đi cùng một con đường, nhưng cùng được mời ngồi chung một nội các. Chủ tịch Hồ Chí Minh đã chọn người như thế nào, và chính phủ ấy đã làm gì trong những ngày đầu tiên của nước Việt Nam độc lập?","bia":{"src":"textures/ht/ht_anh_chinh_phu_lam_thoi.jpg","credit":"Ảnh: Vietnam Government · Public domain · Wikimedia Commons"},"so_chu":1863},{"i":8,"tieu_de_bang":"Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa, 1946","tieu_de":"Lá phiếu đầu tiên: Tổng tuyển cử 6/1/1946 và Quốc hội khóa I","sapo":"Tấm ảnh được ghi ngày 2/3/1946, ngày những người đại biểu do dân bầu ra lần đầu tiên ngồi lại với nhau trong một nghị trường giữa Thủ đô. Để có được ngày ấy, khoảng tám mươi chín phần trăm cử tri cả nước đã đi bầu, có nơi phải bỏ phiếu dưới làn đạn. Và chỉ bốn ngày sau phiên họp, Chính phủ do chính Quốc hội ấy thông qua đặt bút ký một hiệp định định đoạt vận nước.","bia":{"src":"textures/ht/ht_anh_quoc_hoi_vndcch_khoa_i.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1959},{"i":9,"tieu_de_bang":"Ngày Tiễu trừ nạn đói, Hà Nội 1945","tieu_de":"“Lúc chúng ta nâng bát cơm mà ăn…”: mặt trận chống giặc đói mùa thu 1945","sapo":"Hơn một tháng sau ngày Độc lập, một tấm ảnh tư liệu ở Hà Nội mang cái tên nghe như lệnh ra quân: “Ngày Tiễu trừ nạn đói”. Mùa thu năm 1945, cái đói cũng là một thứ giặc, và nó vừa cướp đi hơn hai triệu sinh mạng. Nhà nước non trẻ đã đánh thứ giặc ấy bằng những bữa cơm nhịn, những hũ gạo nhỏ và những luống khoai trồng vội trên đất vừa rút lũ.","bia":{"src":"textures/ht/ht_anh_ngay_tieu_tru_nan_doi.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1948},{"i":10,"tieu_de_bang":"Chủ tịch Hồ Chí Minh với kiều bào tại Pháp, 1946","tieu_de":"Bốn tháng trên đất Pháp: Chủ tịch Hồ Chí Minh giữa kiều bào năm 1946","sapo":"Năm 1923, một thanh niên tên Nguyễn Ái Quốc lặng lẽ rời Paris. Hai mươi ba năm sau, người ấy trở lại, lần này là Chủ tịch nước Việt Nam Dân chủ Cộng hòa, thượng khách của nước Pháp. Giữa những cuộc đàm phán căng thẳng, có những buổi gặp mà Người dành trọn cho đồng bào mình: người lính thợ, người thủy thủ, cậu sinh viên, vị kỹ sư đang sống xa Tổ quốc.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_with_vietnamese_expats_in_france_194.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1782},{"i":11,"tieu_de_bang":"Ký Hiệp định Sơ bộ 6/3/1946","tieu_de":"Chiều 6/3/1946: một chữ ký để tránh chiến tranh","sapo":"Buổi sáng, súng nổ ở cảng Hải Phòng. Buổi chiều, trong một ngôi nhà trên phố Lý Thái Tổ, Chủ tịch Hồ Chí Minh đặt bút ký một văn bản mà nhiều người khi ấy chưa hiểu, thậm chí phản đối. Nhưng chính chữ ký ấy đã đẩy hai mươi vạn quân Tưởng về nước và mua cho nước Việt Nam non trẻ chín tháng quý giá để chuẩn bị cho cuộc chiến không thể tránh.","bia":{"src":"textures/ht/ht_anh_ho_sainteny_agreement_march_6_1946.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1875},{"i":12,"tieu_de_bang":"Toàn cảnh lễ đài Ba Đình ngày 2/9/1945","tieu_de":"Bảy ngày dựng một quảng trường: toàn cảnh lễ đài ngày Độc lập","sapo":"Bức ảnh toàn cảnh lễ đài chiều 2 tháng 9 năm 1945, nay lưu trong hệ thống Lưu trữ quốc gia, cho thấy một quảng trường rợp cờ và một biển người trải dài đến tận các góc phố. Nhưng đứng sau khung hình tĩnh lặng ấy là một guồng máy khẩn trương chỉ có đúng một tuần để chuẩn bị, một sĩ quan Mỹ xin đứng lẫn giữa đám đông thay vì ngồi ghế danh dự, và một phóng viên ảnh trẻ chạy vội lên vườn hoa với chiếc máy cũ trên tay. Toàn cảnh ấy, nhìn kỹ, kể một câu chuyện khác với những gì người ta vẫn thường nhớ về ngày hôm đó.","bia":{"src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"so_chu":1696},{"i":13,"tieu_de_bang":"Bản Tuyên ngôn Độc lập — Trung tâm Lưu trữ quốc gia III","tieu_de":"Đọc chậm bản Tuyên ngôn Độc lập: lý lẽ, cáo trạng và tờ giấy được gìn giữ","sapo":"Chỉ vài trang giấy, được viết trong hai ngày trên một căn gác phố cổ, nhưng bản Tuyên ngôn Độc lập chứa cả một phiên tòa lịch sử: có lý lẽ, có chứng cứ, có phán quyết. Hôm nay, văn bản ấy được gìn giữ tại Trung tâm Lưu trữ quốc gia III. Hãy thử đọc chậm từng phần, như một nhà lưu trữ lật giở tập hồ sơ quý nhất của mình.","bia":{"src":"textures/ht/ht_anh_ban_tuyen_ngon_doc_lap_cua_nuoc_viet_nam_dan_chu.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"so_chu":1904},{"i":14,"tieu_de_bang":"Phố Hàng Ngang (rue des Cantonnais) đầu thế kỷ XX","tieu_de":"Hàng Ngang — \"rue des Cantonnais\": con phố buôn bán rồi sẽ giữ một bí mật lớn của dân tộc","sapo":"Tấm ảnh đen trắng chụp đầu thế kỷ XX chỉ cho thấy một con phố buôn bán bình thường của Hà Nội: mái ngói san sát, biển hiệu, người đi bộ và xe tay ngược xuôi. Không có gì trong khung hình báo trước rằng vài chục năm sau, trên gác hai của một ngôi nhà giữa dãy phố ấy, một văn kiện làm thay đổi vận mệnh dân tộc sẽ ra đời. Người Pháp khi ấy gọi con phố này là \"rue des Cantonnais\" — phố của người Quảng Đông. Để hiểu vì sao Hàng Ngang trở thành một địa chỉ lịch sử, hãy quay lại với con phố buôn bán bình dị trong tấm ảnh này.","bia":{"src":"textures/ht/ht_anh_tonkin_hanoi_rue_des_cantonnais.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1950},{"i":15,"tieu_de_bang":"Di tích 48 Hàng Ngang trong phố cổ Hà Nội ngày nay","tieu_de":"Số 48 Hàng Ngang hôm nay: bước qua một ngưỡng cửa, lùi lại tám mươi năm","sapo":"Giữa dãy phố Hàng Ngang tấp nập người mua kẻ bán, có một cánh cửa mà bước qua, thời gian như quay ngược lại tám mươi năm. Tấm ảnh chụp năm 2016 ghi lại khoảnh khắc rất đời thường ấy: một di tích lịch sử nép mình giữa những cửa hàng, không cờ hoa rực rỡ, không hàng rào ngăn cách. Ngôi nhà số 48 hôm nay đón khách tham quan quanh năm, nhưng mỗi dịp Quốc khánh, con phố buôn bán này lại trở thành điểm hẹn của một ký ức chung.","bia":{"src":"textures/ht/ht_anh_memorial_in_honour_of_ho_chi_minh_in_the_hanoi_o.jpg","credit":"Ảnh: shankar s. from Dubai, united arab emira · CC BY 2.0 · Wikimedia Commons"},"so_chu":1599},{"i":16,"tieu_de_bang":"Lời Bác: “Quyết đem tất cả tinh thần và lực lượng…”","tieu_de":"“Quyết đem tất cả tinh thần và lực lượng…”: lời thề của một dân tộc, được giữ trọn bằng máu","sapo":"Câu văn khép lại bản Tuyên ngôn Độc lập không phải một lời tự hào suông. Đó là một lời thề, được cả một dân tộc chuẩn bị phải giữ bằng chính tính mạng của mình chỉ ít lâu sau đó. Từ Quảng trường Ba Đình chiều 2/9/1945, lời thề ấy đã đi qua ba mươi năm chiến tranh, để trở thành một trong những câu nói được nhắc tới nhiều nhất trong lịch sử Việt Nam hiện đại.","bia":{"src":"textures/ht/ht_anh_ban_tuyen_ngon_doc_lap_cua_nuoc_viet_nam_dan_chu.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"so_chu":1835},{"i":17,"tieu_de_bang":"Nhà số 48 Hàng Ngang","tieu_de":"Ngôi nhà hiệu lụa Phúc Lợi: vì sao 48 Hàng Ngang được chọn cho những ngày lập quốc","sapo":"Ngày 25 tháng 8 năm 1945, một vị khách đặc biệt lặng lẽ bước lên căn gác hai của một hiệu buôn tơ lụa giữa phố cổ Hà Nội. Chín ngày sau, từ chính căn gác ấy, người khách đó bước ra Quảng trường Ba Đình đọc bản Tuyên ngôn Độc lập trước hàng chục vạn đồng bào. Vì sao trong cả Hà Nội, một ngôi nhà buôn bán bình thường lại được chọn cho những ngày quyết định bậc nhất của một dân tộc?","bia":{"src":"textures/bai/G14_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1900},{"i":18,"tieu_de_bang":"Căn phòng soạn thảo Tuyên ngôn","tieu_de":"Căn phòng nhỏ trên gác hai: bản Tuyên ngôn Độc lập được viết ra như thế nào","sapo":"Chỉ một căn phòng nhỏ trên gác hai nhà 48 Hàng Ngang, bàn viết kê sát cửa sổ nhìn ra phố. Nhưng chính tại đây, trong những ngày cuối tháng Tám năm 1945, giữa bộn bề công việc của một chính quyền vừa ra đời, Chủ tịch Hồ Chí Minh đã đặt bút viết nên văn kiện lập quốc của nước Việt Nam Dân chủ Cộng hòa.","bia":{"src":"textures/bai/G14_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1603},{"i":19,"tieu_de_bang":"Lễ đài Ba Đình, 2/9/1945","tieu_de":"Lễ đài Độc lập: một công trình gỗ và vải dựng trong một ngày đêm","sapo":"Lễ đài nơi Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập không phải một công trình kiên cố được chuẩn bị từ trước, mà là một kết cấu gỗ và vải, dựng gấp trong chưa đầy một ngày đêm. Vậy mà hình ảnh giản dị ấy đã trở thành một trong những biểu tượng được nhớ đến nhiều nhất của lịch sử Việt Nam hiện đại.","bia":{"src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},"so_chu":1558},{"i":20,"tieu_de_bang":"Hai địa điểm","tieu_de":"Từ căn gác đến quảng trường: hai cây số của mùa thu 1945","sapo":"Phố Hàng Ngang và Quảng trường Ba Đình cách nhau chừng hai cây số. Quãng đường ấy nối khu phố buôn bán của người Việt với khu hành chính thời thuộc địa — và nối căn phòng nơi bản Tuyên ngôn Độc lập được viết ra với nơi nó được đọc lên trước toàn dân.","bia":{"src":"textures/bai/G14_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1557}],"do_vat":[{"id":"table@10.4,69.6","x":10.4,"y":0.22,"z":69.6,"loai":"table","ten":"Bàn viết (phục dựng)","tieu_de":"Chiếc bàn của những ngày viết Tuyên ngôn"},{"id":"table@9.6,69.6","x":9.6,"y":0.22,"z":69.6,"loai":"table","ten":"Bàn họp (phục dựng)","tieu_de":"Cuộc họp ngày 26 tháng 8 năm 1945"},{"id":"desk_lamp_arm_01@10.6,70.1","x":10.6,"y":1,"z":70.1,"loai":"desk_lamp_arm_01","ten":"Đèn bàn (phục dựng)","tieu_de":"Ngọn đèn của những ngày làm việc không nghỉ"},{"id":"vintage_grandfather_clock_01@12.2,68.5","x":12.22,"y":0.26,"z":68.45,"loai":"vintage_grandfather_clock_01","ten":"Đồng hồ đứng (phục dựng)","tieu_de":"Tám ngày lập quốc"},{"id":"bookshelf@12.2,67.2","x":12.2,"y":0.22,"z":67.2,"loai":"bookshelf","ten":"Tủ sách (phục dựng)","tieu_de":"Hai bản tuyên ngôn được trích dẫn"},{"id":"vintage_day_bed@7.9,67.0","x":7.9,"y":0.26,"z":66.95,"loai":"vintage_day_bed","ten":"Giường nghỉ (phục dựng)","tieu_de":"Căn gác vừa ở vừa làm việc"},{"id":"ArmChair_01@8.7,71.0","x":8.7,"y":0.26,"z":70.95,"loai":"ArmChair_01","ten":"Ghế tiếp khách (phục dựng)","tieu_de":"Mời người tài đức cùng gánh việc nước"},{"id":"vintage_suitcase@6.2,66.8","x":6.2,"y":0.26,"z":66.85,"loai":"vintage_suitcase","ten":"Va li (đồ vật minh họa)","tieu_de":"Từ chiến khu về Thủ đô"},{"id":"table@0.0,-92.2","x":0,"y":1.9,"z":-92.2,"loai":"table","ten":"Bàn trên lễ đài","tieu_de":"Trên lễ đài Độc lập"}]},"G15":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Việt Bắc – An toàn khu","tieu_de":"Chín năm “thủ đô” không tên giữa rừng cọ, đồi chè Việt Bắc","sapo":"Tháng 5 năm 1947, một đoàn người lặng lẽ băng rừng, lội suối, dừng chân giữa một thung lũng nhỏ ở Định Hóa, Thái Nguyên. Không cờ hoa, không dinh thự nghênh đón, chỉ có vài mái lán nứa vừa dựng vội bên sườn đồi. Thế nhưng chính từ những mái lán đơn sơ ấy, suốt chín năm ròng, một dân tộc đã điều hành cuộc kháng chiến giữ nước của mình, và chiến thắng Điện Biên Phủ lừng lẫy năm châu đã được thai nghén. Bước vào gian trưng bày này, bạn sẽ đi vào không gian sống và làm việc giản dị đến bất ngờ của Chủ tịch Hồ Chí Minh giữa núi rừng Việt Bắc.","bia":{"src":"textures/bai/G15_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2281},{"i":1,"tieu_de_bang":"Thu – đông 1947: đòn đánh vào chiến khu thất bại","tieu_de":"75 ngày đêm: khi quân dù Pháp nhảy xuống Bắc Kạn hòng bắt gọn cơ quan đầu não","sapo":"Một buổi sáng tháng 10 năm 1947, tiếng động cơ máy bay gầm rú trên bầu trời Bắc Kạn, những chiếc dù trắng bung ra giữa không trung. Thực dân Pháp tin rằng chỉ cần một đòn bất ngờ, chúng có thể bắt gọn cả cơ quan đầu não kháng chiến, kết thúc cuộc chiến trong vài tuần. Bảy mươi lăm ngày đêm sau, chính đội quân ấy phải rút chạy khỏi Việt Bắc.","bia":{"src":"textures/bai/G15_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1985},{"i":2,"tieu_de_bang":"Từ Tỉn Keo đến Điện Biên Phủ","tieu_de":"“Chắc thắng mới đánh”: lời dặn từ một căn lán nhỏ và con đường tới Điện Biên Phủ","sapo":"Từ cuộc họp trong một căn lán nhỏ ở Tỉn Keo đêm 6 tháng 12 năm 1953 đến buổi chiều 7 tháng 5 năm 1954 ở lòng chảo Điện Biên là chưa đầy năm tháng. Ở khởi đầu con đường ấy là một câu hỏi lớn: đánh hay không đánh, và một lời dặn ngắn gọn của Bác đã trở thành kim chỉ nam cho cả chiến dịch.","bia":{"src":"textures/bai/G15_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1896},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Lời kêu gọi kháng chiến đến ngày về Thủ đô: hai mươi ba mốc son ở Việt Bắc","sapo":"Chín năm, hàng nghìn ngày, nhưng chỉ cần hơn hai mươi mốc thời gian là có thể dựng lại toàn bộ hành trình từ một Chính phủ vừa rời Hà Nội trong đêm đến một dân tộc làm nên chiến thắng Điện Biên Phủ. Mỗi mốc dưới đây đều gắn với một quyết định, một trận đánh hay một con người cụ thể — không có mốc nào là ngẫu nhiên.","bia":{"src":"textures/bai/G15_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1489},{"i":4,"tieu_de_bang":"Với cụ Tôn Đức Thắng và Hoàng Quốc Việt, 1947","tieu_de":"Ba miền quê, một chiến khu: chuyện sau bức ảnh năm 1947 của Bác, Bác Tôn và Hoàng Quốc Việt","sapo":"Một bức ảnh không đề tên tác giả, chụp đâu đó giữa rừng núi Việt Bắc năm 1947, ghi lại ba người đàn ông đang cúi đầu bàn việc bên một chiếc bàn mộc. Không cờ hoa, không micro — chỉ có sự tập trung của những người vừa từ ba ngả đường khác nhau hội tụ về một chiến khu. Một người là Chủ tịch nước; người thứ hai vừa ra khỏi ngục tù Côn Đảo được hai năm; người thứ ba từng nếm đủ Hỏa Lò, Sơn La. Đằng sau khung hình giản dị ấy là cả một chặng đường dài của khối đại đoàn kết dân tộc.","bia":{"src":"textures/ht/ht_anh_chu_tich_ho_chi_minh_trao_doi_cong_viec_voi_dong.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1638},{"i":5,"tieu_de_bang":"Người với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949","tieu_de":"\"Bất kỳ đàn ông, đàn bà\": Người và những nữ cán bộ giữa chiến khu","sapo":"Tháng 2 năm 1949, ống kính vô tình ghi lại một buổi gặp gỡ giữa núi rừng: Chủ tịch Hồ Chí Minh ngồi cùng mấy cán bộ Hội Phụ nữ, không cờ hoa, không khẩu hiệu. Nhưng đằng sau khung hình bình dị ấy là một chặng đường dài, bắt đầu từ một bản Hiến pháp ghi rằng đàn bà ngang quyền đàn ông, tiếp nối bằng những đoàn thể phụ nữ ra đời ngay giữa khói lửa. Cuộc kháng chiến chín năm, hóa ra, cũng là câu chuyện của hàng vạn người mẹ, người chị chưa từng cầm súng.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_and_vietnam_women_union_s_cadres_at_.jpg","credit":"Ảnh: Musée Annam · Public domain · Wikimedia Commons"},"so_chu":1791},{"i":6,"tieu_de_bang":"Quan sát mặt trận Đông Khê, Chiến dịch Biên giới 1950","tieu_de":"\"Chống gậy lên non xem trận địa\": Người ở mặt trận Đông Khê","sapo":"Rạng sáng 16 tháng 9 năm 1950, một người đàn ông chống gậy trèo lên đỉnh núi Báo Đông, giữa biên giới Việt – Trung, để tận mắt theo dõi trận đánh mở màn một chiến dịch lớn. Người đó là Chủ tịch nước. Bức ảnh chụp khoảnh khắc ấy, cùng bài thơ chữ Hán Người viết ngay trong chiến dịch, đã trở thành một trong những hình ảnh khắc họa rõ nhất tinh thần của cuộc kháng chiến chống Pháp giữa lúc chuyển sang thế chủ động tiến công.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_in_dong_khe_1950.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1548},{"i":7,"tieu_de_bang":"Đại hội II của Đảng tại Chiêm Hóa, Tuyên Quang, 1951","tieu_de":"Đại hội giữa rừng Chiêm Hóa: khi Đảng trở lại hoạt động công khai","sapo":"Tháng 2 năm 1951, giữa rừng già Chiêm Hóa, hơn hai trăm đại biểu từ khắp mọi miền đất nước lặng lẽ tề tựu về một địa điểm bí mật. Sau hơn năm năm phải ẩn mình dưới cái tên \"tự giải tán\", Đảng Cộng sản Đông Dương chuẩn bị bước ra công khai với một tên gọi mới. Không lễ đài lộng lẫy, chỉ có nhà tranh giữa rừng — nhưng những quyết định đưa ra ở đó sẽ dẫn dắt cả một cuộc kháng chiến đi đến ngày toàn thắng.","bia":{"src":"textures/ht/ht_anh_dai_hoi_dai_bieu_toan_quoc_lan_thu_hai_dang_cong.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1561},{"i":8,"tieu_de_bang":"Họa sĩ Phan Kế An ký họa Bác tại Việt Bắc, 11/1948","tieu_de":"Ký họa giữa rừng: hơn hai mươi bức vẽ Bác Hồ từ người thật","sapo":"Một ngày cuối thu năm 1948, giữa rừng Khuôn Tát, một họa sĩ trẻ được gọi đến bên Chủ tịch Hồ Chí Minh, mang theo giấy bút. Không có người mẫu ngồi yên, không có buổi tạo dáng: Người vẫn làm việc, đi lại, trò chuyện, còn họa sĩ phải vẽ thật nhanh để bắt được dáng hình chân thực nhất. Hơn hai mươi bức tốc họa ra đời trong ít ngày ngắn ngủi ấy, và một trong số chúng đã trở thành bức ký họa Bác Hồ đầu tiên được đăng báo công khai.","bia":{"src":"textures/ht/ht_anh_painter_phan_ke_an_sketched_a_portrait_of_presid.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1644},{"i":9,"tieu_de_bang":"An toàn khu Định Hóa, Thái Nguyên ngày nay","tieu_de":"Định Hóa hôm nay: về “Thủ đô gió ngàn” nghe núi rừng kể chuyện","sapo":"Tấm ảnh chụp năm 2007 ghi lại một góc An toàn khu Định Hóa hôm nay: đồi núi trập trùng, rừng cọ và nương chè trải dài yên ả. Ít ai hình dung được rằng suốt chín năm, giữa khung cảnh bình lặng ấy, cơ quan đầu não của cả một cuộc kháng chiến đã từng ẩn mình. Hôm nay, những mái lán năm xưa đã trở thành di tích, còn vùng đất này mang một tên gọi thân thương: Thủ đô gió ngàn.","bia":{"src":"textures/ht/ht_anh_atk_dinh_hoa.jpg","credit":"Ảnh: Viethavvh at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},"so_chu":1568},{"i":10,"tieu_de_bang":"An toàn khu Việt Bắc","tieu_de":"An toàn khu vận hành thế nào? Bí mật, cơ động và lòng dân","sapo":"Làm sao một Chính phủ, một Bộ Tổng tư lệnh có thể hoạt động liên tục suốt nhiều năm, ngay trong tầm với của máy bay trinh sát và những cuộc hành quân càn quét của đối phương? Câu trả lời nằm ở cách An toàn khu Việt Bắc được tổ chức: không phải một cứ điểm cố định, mà là một mạng lưới bí mật, cơ động, dựa vào lòng dân.","bia":{"src":"textures/bai/G15_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1593},{"i":11,"tieu_de_bang":"Lán Bác ở và làm việc","tieu_de":"Căn lán, chiếc máy chữ và những trang viết của Người","sapo":"Một căn lán nứa nhỏ, một bàn tre, một chiếc máy chữ, một ngọn đèn dầu. Trong không gian giản dị ấy, giữa núi rừng Việt Bắc, đã ra đời những văn kiện, bài báo, bức thư, và cả những vần thơ đẹp trong đời cầm bút của Chủ tịch Hồ Chí Minh.","bia":{"src":"textures/bai/G15_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1581},{"i":12,"tieu_de_bang":"Lán họp Bộ Chính trị","tieu_de":"Căn lán nhỏ, quyết định lớn: đêm 6/12/1953 ở Tỉn Keo","sapo":"Không súng ống, không quân phục, chỉ vài chiếc bàn gỗ mộc kê sát nhau dưới mái lá cọ. Đêm 6 tháng 12 năm 1953, trong căn lán nhỏ ấy ở Tỉn Keo, một quyết định làm thay đổi cục diện cả cuộc chiến tranh Đông Dương đã được đưa ra. Vì sao Bộ Chính trị chọn đúng ngọn đồi khuất nẻo này để bàn về trận đánh lớn nhất trong lịch sử quân sự Việt Nam? Câu trả lời còn nằm trong từng vật dụng mộc mạc được gìn giữ nơi đây.","bia":{"src":"textures/bai/G15_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1753},{"i":13,"tieu_de_bang":"Hầm trú ẩn","tieu_de":"Dưới lòng đồi: hầm trú ẩn và cuộc chiến với bầu trời","sapo":"Đối phương làm chủ bầu trời; cơ quan kháng chiến chỉ có rừng, có đất và đôi bàn tay đào bới. Suốt chín năm ở Việt Bắc, mỗi lán ở, lán làm việc đều phải có một căn hầm bên cạnh — tấm khiên vô hình giữ an toàn cho cả bộ máy đầu não kháng chiến. Vì sao một hố đất đào vội giữa rừng lại có thể ngăn được bom đạn từ trên không?","bia":{"src":"textures/bai/G15_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1610},{"i":14,"tieu_de_bang":"Bếp Hoàng Cầm","tieu_de":"Bếp Hoàng Cầm: sáng kiến của một anh nuôi giữ bí mật cho cả đoàn quân","sapo":"Một cột khói mỏng bốc thẳng lên tán rừng cũng đủ để máy bay trinh sát lần ra cả một đơn vị đang trú quân. Giữa khó khăn tưởng chừng không lời giải ấy, một người lính cấp dưỡng bình dị đã nghĩ ra cách “giấu khói” xuống lòng đất. Chiếc bếp mang tên anh — bếp Hoàng Cầm — theo bước quân đi suốt hai cuộc kháng chiến.","bia":{"src":"textures/bai/G15_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1642},{"i":15,"tieu_de_bang":"Đồi chè Thái Nguyên","tieu_de":"Rừng cọ, đồi chè: núi rừng Việt Bắc che chở và nuôi dưỡng kháng chiến","sapo":"Không một khẩu súng nào canh gác cho cơ quan đầu não kháng chiến tốt hơn chính những cánh rừng cọ, những đồi chè xanh ngát của Định Hóa. Núi rừng Việt Bắc không chỉ là phông nền cho câu chuyện chín năm kháng chiến — mà là một phần sống còn của câu chuyện ấy: vừa che mắt kẻ thù, vừa nuôi sống cả một bộ máy lãnh đạo. Vì sao một vùng trung du bình dị lại trở thành “thủ đô kháng chiến” vững chắc đến vậy?","bia":{"src":"textures/bai/G15_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1596}],"do_vat":[{"id":"table@-7.1,-19.6","x":-7.13,"y":3.18,"z":-19.63,"loai":"table","ten":"Bàn tre làm việc","tieu_de":"Nơi ra đời “Sửa đổi lối làm việc”"},{"id":"typewriter@-7.2,-19.6","x":-7.23,"y":3.84,"z":-19.61,"loai":"typewriter","ten":"Chiếc máy chữ","tieu_de":"Người bạn đồng hành thầm lặng ở chiến khu"},{"id":"vintage_oil_lamp@-6.8,-19.8","x":-6.77,"y":3.84,"z":-19.75,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"“Cảnh khuya như vẽ người chưa ngủ”"},{"id":"table@11.1,-24.3","x":11.06,"y":3.38,"z":-24.29,"loai":"table","ten":"Bàn họp Bộ Chính trị","tieu_de":"Ngày 6/12/1953: quyết định mở Chiến dịch Điện Biên Phủ"},{"id":"table@9.2,-24.7","x":9.15,"y":3.38,"z":-24.68,"loai":"table","ten":"Bàn họp gỗ mộc","tieu_de":"Lời dặn “chắc thắng mới đánh”"},{"id":"vintage_oil_lamp@12.2,-24.1","x":12.19,"y":4.14,"z":-24.07,"loai":"vintage_oil_lamp","ten":"Đèn dầu lán họp","tieu_de":"Quyết định quân sự, thông điệp hòa bình"},{"id":"tea_set_01@10.0,-24.5","x":9.98,"y":4.14,"z":-24.51,"loai":"tea_set_01","ten":"Bộ ấm chén","tieu_de":"Chén trà trên đất chè Thái Nguyên"},{"id":"hearth@-17.5,-7.0","x":-17.5,"y":0.33,"z":-7,"loai":"hearth","ten":"Bếp Hoàng Cầm","tieu_de":"Bếp giấu khói của anh nuôi Hoàng Cầm"},{"id":"wicker_basket_01@-18.5,-6.2","x":-18.5,"y":0.33,"z":-6.2,"loai":"wicker_basket_01","ten":"Giỏ đan","tieu_de":"Gánh gạo nuôi quân"}]},"G16":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Phủ Chủ tịch – Nhà sàn","tieu_de":"Mười lăm năm bên vườn cây, ao cá — nơi Chủ tịch Hồ Chí Minh sống những năm cuối đời","sapo":"Giữa một khu vườn rộng từng là nơi ở của các quan toàn quyền Pháp, người đứng đầu một nhà nước độc lập lại chọn cho mình căn nhà nhỏ nhất có thể tìm được. Suốt mười lăm năm, từ căn nhà của người thợ điện đến ngôi nhà sàn gỗ bên ao cá, Chủ tịch Hồ Chí Minh vừa gánh vác việc nước vừa tự tay vun từng gốc cây, cho từng đàn cá ăn. Vì sao một vị nguyên thủ quốc gia lại sống như vậy, và điều gì đã diễn ra trong căn phòng nhỏ trên tầng hai ngôi nhà sàn ấy suốt bốn năm cuối cùng?","bia":{"src":"textures/bai/G16_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":2111},{"i":1,"tieu_de_bang":"Tết trồng cây – từ khu vườn của Bác","tieu_de":"“Mùa xuân là Tết trồng cây”: phong tục mới bắt đầu từ khu vườn Phủ Chủ tịch","sapo":"Cuối năm 1959, báo Nhân Dân đăng một bài viết ngắn, giản dị của Chủ tịch Hồ Chí Minh. Không ai ngờ vài trăm chữ mộc mạc ấy lại khai sinh ra một phong tục mà hơn sáu mươi năm sau, người Việt Nam vẫn giữ mỗi độ xuân về — bắt đầu từ chính khu vườn nhỏ nơi Người sống.","bia":{"src":"textures/bai/G16_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1875},{"i":2,"tieu_de_bang":"Bản Di chúc viết trong những mùa sinh nhật","tieu_de":"1965–1969: bản Di chúc lặng lẽ viết trong căn phòng nhỏ trên nhà sàn","sapo":"Sáng 10 tháng 5 năm 1965, đúng dịp sinh nhật lần thứ 75, Chủ tịch Hồ Chí Minh ngồi vào bàn làm việc trên tầng hai nhà sàn và bắt đầu viết những lời dặn lại cho muôn đời sau. Công việc ấy được giữ kín suốt bốn năm, chỉ được giở ra mỗi độ tháng Năm về, và chỉ được công bố đầy đủ hai mươi năm sau khi Người đã đi xa. Vì sao một văn kiện hệ trọng như vậy lại được viết lặng lẽ đến thế, trong một căn phòng nhỏ chỉ vài mét vuông?","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_office.jpg","credit":"Ảnh: Dennis G. Jarvis · CC BY-SA 2.0 · Wikimedia Commons"},"so_chu":1905},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Phủ Chủ tịch 1954–1969: mười lăm năm cuối đời qua những mốc lớn","sapo":"Từ ngày trở về Thủ đô đến lúc Người đi xa, mỗi mốc thời gian dưới đây đều gắn với khu nhà sàn, vườn cây và ao cá nơi Chủ tịch Hồ Chí Minh đã sống và làm việc suốt mười lăm năm cuối đời.","bia":{"src":"textures/bai/G16_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1122},{"i":4,"tieu_de_bang":"Chủ tịch Hồ Chí Minh năm 1967 — ảnh Anefo","tieu_de":"Chân dung năm 1967: vị Chủ tịch ngoài bảy mươi tuổi giữa những năm chiến tranh","sapo":"Bức ảnh do hãng ảnh Anefo của Hà Lan phát hành, nay lưu tại Lưu trữ Quốc gia Hà Lan, được ghi ngày 23 tháng 1 năm 1967. Khi ấy, Chủ tịch Hồ Chí Minh đã ngoài bảy mươi lăm tuổi, còn Hà Nội đang sống trong những năm tháng bom đạn. Vì sao một hãng tin phương Tây lại lưu hành chân dung của một vị lãnh tụ ở phía bên kia cuộc chiến tranh lạnh?","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_anefo.jpg","credit":"Ảnh: Không rõ tác giả · CC BY-SA 3.0 nl · Wikimedia Commons"},"so_chu":1480},{"i":5,"tieu_de_bang":"Người xem bóng đá, 1958","tieu_de":"Trên khán đài năm 1958: niềm vui bóng đá của một Chủ tịch nước yêu thể thao","sapo":"Một chiều cuối tháng 8 năm 1958, giữa hàng nghìn khán giả trên một sân vận động không ghi rõ tên, ống kính vô danh bắt được một khoảnh khắc hiếm hoi: Chủ tịch Hồ Chí Minh ngồi xem bóng đá, vỗ tay reo hò như bất cứ người dân nào khác. Bức ảnh tưởng chỉ là một lát cắt đời thường ấy lại hé mở một phần tư tưởng lớn của Người, bắt đầu từ mười hai năm trước, khi đất nước vừa giành độc lập. Vì sao giữa muôn vàn việc nước, một vị Chủ tịch vẫn dành thời gian ra sân cỏ?","bia":{"src":"textures/ht/ht_anh_president_ho_chi_minh_watching_soccer_1958.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"so_chu":1820},{"i":6,"tieu_de_bang":"Với Thủ tướng Ấn Độ Jawaharlal Nehru, 1958","tieu_de":"Hồ Chí Minh và Nehru: tình bạn của hai dân tộc vừa giành độc lập","sapo":"Một tấm ảnh đen trắng lưu tại New Delhi chỉ ghi vỏn vẹn một dòng: năm 1958. Trong ảnh, Chủ tịch Hồ Chí Minh đứng bên Thủ tướng Ấn Độ Jawaharlal Nehru, không nghi lễ cầu kỳ, như hai người bạn lâu năm. Đằng sau khoảnh khắc giản dị ấy là cả một hành trình gắn bó giữa hai dân tộc châu Á cùng vừa thoát khỏi ách thực dân, và một chuyến công du tám ngày để lại dấu ấn sâu đậm trong lịch sử ngoại giao Việt Nam.","bia":{"src":"textures/ht/ht_anh_jawaharlal_nehru_with_dr_ho_chi_minh.jpg","credit":"Ảnh: Nehru Memorial Museum & Library · Public domain · Wikimedia Commons"},"so_chu":1745},{"i":7,"tieu_de_bang":"Bác Hồ với các cháu thiếu nhi","tieu_de":"Bác Hồ với các cháu thiếu nhi: tình thương dành cho những người chủ tương lai","sapo":"Trong hàng nghìn bức ảnh còn lưu lại về Chủ tịch Hồ Chí Minh, những tấm ảnh Người bên các cháu thiếu nhi luôn có một sức hút riêng: gương mặt Người như trẻ lại, rạng rỡ hẳn lên. Tấm ảnh này thuộc bộ sưu tập Musée Annam, không ghi rõ ngày tháng, địa điểm – nhưng câu chuyện đằng sau nó thì bắt đầu từ chính những ngày đầu tiên của nước Việt Nam độc lập.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_with_children_6.jpg","credit":"Ảnh: Musée Annam · Public domain · Wikimedia Commons"},"so_chu":1733},{"i":8,"tieu_de_bang":"Nhà sàn Bác Hồ trong Khu Di tích Phủ Chủ tịch","tieu_de":"Nhà sàn giữa lòng Thủ đô: ngôi nhà mang theo ký ức Việt Bắc","sapo":"Một bức ảnh chụp từ bên kia mặt ao, năm 2017, ghi lại dáng vẻ ngôi nhà sàn gỗ nhỏ giữa cây xanh và bóng nước. Không phải biệt thự, cũng không phải dinh thự, đây lại là nơi Chủ tịch Hồ Chí Minh ở lâu nhất tại Hà Nội. Vì sao một vị nguyên thủ quốc gia lại chọn sống trong một ngôi nhà nhỏ đến vậy, và điều gì khiến hình ảnh ấy còn lan tỏa đến tận hôm nay?","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_s_stilt_house_hanoi_1_38439116266.jpg","credit":"Ảnh: Richard Mortel from Riyadh, Saudi Arabia · CC BY 2.0 · Wikimedia Commons"},"so_chu":1597},{"i":9,"tieu_de_bang":"Phòng làm việc của Người trong nhà sàn","tieu_de":"Căn phòng làm việc trên nhà sàn: nơi ngọn bút không nghỉ","sapo":"Trên giá sách ở góc phòng còn đó chiếc máy chữ Người từng dùng, bên cạnh những chồng báo đọc dở. Suốt hơn một thập niên, chưa đầy chục mét vuông ấy chứng kiến hàng nghìn bài báo ký bút danh C.B. ra đời, và trong bốn năm cuối cùng, cả những dòng đầu tiên của bản Di chúc. Vì sao một vị Chủ tịch nước lại chọn làm việc trong một căn phòng nhỏ đến vậy?","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_office.jpg","credit":"Ảnh: Dennis G. Jarvis · CC BY-SA 2.0 · Wikimedia Commons"},"so_chu":1663},{"i":10,"tieu_de_bang":"Phòng ngủ giản dị trong Nhà 54","tieu_de":"Căn phòng ngủ ở Nhà 54 và nếp sống cần, kiệm của vị Chủ tịch","sapo":"Một chiếc giường gỗ, một bàn nhỏ, một tủ sách vài chục cuốn — đó là toàn bộ những gì có trong phòng ngủ của một vị Chủ tịch nước suốt gần bốn năm. Tấm ảnh chụp năm 2010 khiến không ít du khách phải dừng lại thật lâu, rồi tự hỏi: điều gì khiến một người đứng đầu nhà nước chọn sống như vậy, giữa lúc hoàn toàn có thể chọn khác đi?","bia":{"src":"textures/ht/ht_anh_bedroom_of_ho_chi_minh_s_house_attached_to_the_p.jpg","credit":"Ảnh: Esemono · CC0 · Wikimedia Commons"},"so_chu":1656},{"i":11,"tieu_de_bang":"Phủ Chủ tịch — nơi Người tiếp khách nhưng không ở","tieu_de":"Từ Phủ Toàn quyền đến Phủ Chủ tịch: tòa nhà Người dùng để tiếp khách nhưng không ở","sapo":"Tòa nhà sơn vàng uy nghi bậc nhất Ba Đình từng là nơi ở của những viên Toàn quyền cai trị cả cõi Đông Dương. Năm 1954, khi trở thành người đứng đầu một nước Việt Nam độc lập, Chủ tịch Hồ Chí Minh hoàn toàn có thể chuyển vào ở đó. Nhưng suốt mười lăm năm cuối cùng của cuộc đời, Người chưa từng qua đêm một lần nào trong tòa nhà ấy.","bia":{"src":"textures/ht/ht_anh_presidential_palace_hanoi_vietnam.jpg","credit":"Ảnh: RB Photo · CC BY 4.0 · Wikimedia Commons"},"so_chu":1623},{"i":12,"tieu_de_bang":"Lời Bác: “Tôi để lại muôn vàn tình thân yêu…”","tieu_de":"“Muôn vàn tình thân yêu”: những dòng cuối trong bản Di chúc của Người","sapo":"Sau những dặn dò về Đảng, về cuộc kháng chiến và về công việc sau chiến tranh, bản Di chúc khép lại bằng một câu văn ngắn, giản dị đến bất ngờ. Không một lời kể công, không một điều mong cầu cho riêng mình — chỉ có tình thương để lại cho những người ở lại. Vì sao trong những dòng cuối cùng của một văn kiện trọng đại bậc nhất lịch sử dân tộc, Người lại chọn nói về điều giản dị ấy trước tiên?","bia":{"src":"textures/bai/G16_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1562},{"i":13,"tieu_de_bang":"Nhà sàn Bác Hồ","tieu_de":"Nhà sàn Bác Hồ: ngôi nhà nhỏ mang hồn núi rừng Việt Bắc giữa lòng Thủ đô","sapo":"Mùa hè năm 1958, một đội thợ mộc quân đội âm thầm dựng lên giữa vườn cây Phủ Chủ tịch một ngôi nhà sàn bằng thứ gỗ mà chẳng mấy ai chọn để làm nhà cho một vị nguyên thủ quốc gia. Người đặt hàng ngôi nhà ấy chính là Chủ tịch Hồ Chí Minh, và Người đã đưa ra một yêu cầu khiến vị kiến trúc sư phải nghĩ lại toàn bộ bản vẽ ban đầu. Ngôi nhà nhỏ ấy — cao vỏn vẹn hai tầng, không rộng hơn một căn nhà cấp bốn ở làng quê — trở thành nơi ở và làm việc suốt mười một năm cuối đời của Người. Hôm nay, bước qua chiếc cầu thang gỗ lên tầng trên, du khách vẫn có thể nhìn thấy chiếc giá sách mỏng manh ngăn đôi ranh giới giữa việc nước và đời riêng.","bia":{"src":"textures/bai/G16_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1651},{"i":14,"tieu_de_bang":"Ao cá","tieu_de":"Ao cá trước nhà sàn: nơi Bác Hồ nghỉ ngơi và suy nghĩ việc nước mỗi buổi chiều","sapo":"Không cần đến vườn thượng uyển hay hồ cảnh cầu kỳ, khoảng lặng riêng của một vị Chủ tịch nước chỉ vỏn vẹn là chiếc ao rộng hơn ba nghìn mét vuông trước nhà sàn. Ngày này qua ngày khác, sau giờ làm việc, Người ra bến ao vỗ tay gọi cá — một thói quen giản dị mà những ai từng phục vụ Bác vẫn nhắc lại đến tận hôm nay. Vì sao một nguyên thủ quốc gia giữa bộn bề việc nước lại dành thời gian đều đặn cho một việc nhỏ như vậy? Câu trả lời nằm ngay trong cách Người sống suốt mười lăm năm ở Phủ Chủ tịch.","bia":{"src":"textures/bai/G16_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1628},{"i":15,"tieu_de_bang":"Nhà để xe","tieu_de":"Ba chiếc ô tô của Bác Hồ: từ quà tặng ngoại giao đến bảo vật quốc gia","sapo":"Không một chiếc xe sang trọng theo nghi thức nguyên thủ, ba chiếc ô tô nằm trong nhà để xe cạnh nhà sàn đều là quà tặng — của một chính phủ bạn, và của chính những người Việt xa xứ. Suốt hơn một thập niên, chúng lặng lẽ đưa Bác đi khắp các công trường, hợp tác xã, đơn vị bộ đội miền Bắc, không phải để phô trương mà để Người đến gần hơn với đời sống nhân dân. Gần sáu mươi năm sau, cả ba chiếc xe ấy được công nhận là bảo vật quốc gia — không phải vì giá trị vật chất, mà vì mỗi vòng bánh xe đều gắn với một chặng đường Người đã đi.","bia":{"src":"textures/bai/G16_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1588},{"i":16,"tieu_de_bang":"Nhà 54","tieu_de":"Nhà 54: ngôi nhà người thợ điện trở thành nơi ở đầu tiên của Chủ tịch nước tại Thủ đô","sapo":"Trong cả một khu Phủ Chủ tịch rộng lớn, nơi ở đầu tiên Chủ tịch Hồ Chí Minh chọn khi trở về Hà Nội năm 1954 không phải một căn phòng nào trong tòa dinh thự, mà là ngôi nhà nhỏ ba gian của một người thợ điện vô danh thời Pháp thuộc. Gần bốn năm sau, khi đã chuyển sang ở nhà sàn mới dựng bên ao cá, Người vẫn mỗi ngày quay trở lại ngôi nhà cũ ấy — không phải vì hoài niệm, mà vì một lý do rất thiết thực trong nếp sống thường nhật của Người.","bia":{"src":"textures/ht/ht_anh_bedroom_of_ho_chi_minh_s_house_attached_to_the_p.jpg","credit":"Ảnh: Esemono · CC0 · Wikimedia Commons"},"so_chu":1560}],"do_vat":[{"id":"bookshelf@-31.8,-11.3","x":-31.81,"y":2.76,"z":-11.27,"loai":"bookshelf","ten":"Giá sách ngăn phòng","tieu_de":"Giá sách làm vách ngăn"},{"id":"table@-32.8,-9.6","x":-32.78,"y":2.76,"z":-9.59,"loai":"table","ten":"Bàn làm việc","tieu_de":"Chiếc bàn nơi Di chúc ra đời"},{"id":"typewriter@-32.8,-9.7","x":-32.75,"y":3.52,"z":-9.68,"loai":"typewriter","ten":"Máy chữ","tieu_de":"Thói quen tự đánh máy"},{"id":"alarm_clock_01@-33.0,-9.3","x":-33.05,"y":3.52,"z":-9.26,"loai":"alarm_clock_01","ten":"Đồng hồ báo thức","tieu_de":"Người luôn đúng giờ"},{"id":"binder_notebook@-32.6,-9.9","x":-32.57,"y":3.52,"z":-9.92,"loai":"binder_notebook","ten":"Tập hồ sơ trên bàn","tieu_de":"Những trang bản thảo được giữ kín"},{"id":"phan@-31.3,-13.1","x":-31.26,"y":2.76,"z":-13.09,"loai":"phan","ten":"Giường ngủ","tieu_de":"Chiếc giường gỗ đơn sơ"},{"id":"cabinet@-28.9,-13.4","x":-28.95,"y":2.76,"z":-13.38,"loai":"cabinet","ten":"Tủ quần áo","tieu_de":"Vài bộ quần áo và đôi dép cao su"},{"id":"vintage_radio_transceiver@-29.6,-11.4","x":-29.56,"y":3.46,"z":-11.37,"loai":"vintage_radio_transceiver","ten":"Chiếc radio","tieu_de":"Nghe tin từ khắp nơi"},{"id":"table@-31.7,-11.0","x":-31.7,"y":0.21,"z":-10.97,"loai":"table","ten":"Bàn họp tầng dưới","tieu_de":"Nơi họp Bộ Chính trị"},{"id":"bookshelf@-32.1,-15.9","x":-32.12,"y":0.21,"z":-15.9,"loai":"bookshelf","ten":"Tủ sách","tieu_de":"Những cuốn sách nhiều thứ tiếng"}]},"G17":{"_nhe":1,"bang":[{"i":0,"tieu_de_bang":"Di sản – Học và làm theo Bác","tieu_de":"Sau mùa thu năm 1969: di sản Hồ Chí Minh trong lòng dân tộc và thế giới","sapo":"Mùa thu năm 1969, cả nước để tang một người vừa đi xa. Hơn nửa thế kỷ sau, người ấy vẫn có mặt: trong dòng người xếp hàng trước một công trình đá hoa cương ở Ba Đình, trong hơn 170.000 trang tài liệu của một bảo tàng mang tên Người, trong chính tên gọi của thành phố lớn nhất phương Nam. Điều gì đã biến một con người thành một di sản sống, được cả dân tộc và thế giới cùng gìn giữ? Câu chuyện bắt đầu từ chính buổi sáng mùa thu năm ấy.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_ba_dinh_square_and_ho_chi_minh_mau.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"so_chu":2127},{"i":1,"tieu_de_bang":"Sáu năm gìn giữ thi hài Bác giữa chiến tranh","tieu_de":"1969–1975: hành trình thầm lặng gìn giữ thi hài Chủ tịch Hồ Chí Minh","sapo":"Tháng 9 năm 1969, khi bom Mỹ vẫn trút xuống miền Bắc và đất nước còn chia cắt đôi bờ, một đơn vị đặc biệt nhận nhiệm vụ chưa từng có tiền lệ: giữ gìn thi hài Chủ tịch Hồ Chí Minh cho muôn đời sau. Suốt sáu năm, giữa những đợt sơ tán, những đêm báo động và cả nỗi lo bom rơi ngay trên đầu, họ đã hoàn thành nhiệm vụ ấy trong im lặng tuyệt đối. Đây là câu chuyện về căn cứ mang mật danh K9, về những người lính mang tên Đoàn 69, và về ngày họ đưa Người trở về giữa lòng Hà Nội.","bia":{"src":"textures/bai/G17_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1937},{"i":2,"tieu_de_bang":"Di chúc: hai lần công bố, một nguyện vọng","tieu_de":"Sau ngày 2/9/1969: bản Di chúc đến với nhân dân qua hai lần công bố, cách nhau hai mươi năm","sapo":"Ở gian Phủ Chủ tịch, bạn đã thấy Bác lặng lẽ ngồi viết Di chúc trên nhà sàn giữa vườn cây. Gian Di sản kể tiếp phần sau của câu chuyện ấy: bản Di chúc thiêng liêng đó đến với nhân dân như thế nào, vì sao phải hai mươi năm sau toàn văn mới được công bố đầy đủ, và có một lời dặn giản dị của Người mà cho đến nay vẫn chưa thể thực hiện đúng như ý nguyện.","bia":{"src":"textures/bai/G17_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1914},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ năm 1969 đến nay: những mốc gìn giữ và lan tỏa di sản Hồ Chí Minh","sapo":"Hơn nửa thế kỷ sau ngày Chủ tịch Hồ Chí Minh đi xa, di sản của Người được gìn giữ bằng những công trình, những văn kiện và những cuộc vận động. Có mốc ai cũng biết, như ngày khánh thành Lăng hay ngày mở cửa Bảo tàng; cũng có mốc ít được nhắc đến, như ngày một đơn vị quân đội bí mật được kiện toàn thành một bộ tư lệnh. Dưới đây là những mốc chính, xếp theo trình tự thời gian.","bia":{"src":"textures/bai/G17_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1296},{"i":4,"tieu_de_bang":"Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh","tieu_de":"Từ vườn hoa mang tên một giám mục Pháp đến trái tim của một dân tộc","sapo":"Tấm ảnh chụp năm 2008 ghi lại một khoảng sân rộng, cỏ xanh mướt, và phía xa là khối kiến trúc uy nghiêm của Lăng Chủ tịch Hồ Chí Minh. Ít ai còn nhớ, hơn một thế kỷ trước, chính mảnh đất này từng mang tên một vị giám mục người Pháp. Vì sao một vườn hoa nhỏ giữa khu phố Tây lại trở thành nơi khai sinh một quốc gia, rồi sau đó là nơi Người tìm về yên nghỉ giữa lòng nhân dân? Câu chuyện bắt đầu từ một cuộc đổi tên, giữa những ngày tháng Tám sục sôi năm 1945.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_ba_dinh_square_and_ho_chi_minh_mau.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"so_chu":1548},{"i":5,"tieu_de_bang":"Tiêu binh trước Lăng","tieu_de":"Đoàn 275: những người lính đứng gác bên giấc ngủ của Người","sapo":"Họ đứng bất động hàng giờ trước cửa Lăng, dưới nắng hè gay gắt hay trong gió mùa đông buốt giá. Tấm ảnh chụp năm 2018 ghi lại hình ảnh quen thuộc với hàng triệu người từng đến viếng Chủ tịch Hồ Chí Minh: những người lính tiêu binh của Đoàn 275. Ít ai biết, đằng sau vẻ nghiêm trang bất động ấy là hàng chục nghìn giờ luyện tập và trực gác, được ghi lại bằng những con số cụ thể mỗi năm.","bia":{"src":"textures/ht/ht_anh_guards_of_the_ho_chi_minh_mausoleum.jpg","credit":"Ảnh: Christophe95 · CC BY-SA 4.0 · Wikimedia Commons"},"so_chu":1525},{"i":6,"tieu_de_bang":"Quảng trường Ba Đình về đêm","tieu_de":"Khi Ba Đình lên đèn: nghi lễ cờ và những công trình quanh quảng trường","sapo":"Ban ngày, Ba Đình là nơi dòng người nối dài chờ vào viếng Lăng. Khi đêm buông, quảng trường lên đèn, khoác một vẻ tĩnh lặng khác hẳn. Tấm ảnh chụp năm 2010 ghi lại khoảnh khắc ấy — và phía sau ánh đèn là một nghi lễ đã diễn ra đều đặn mỗi ngày, suốt nửa thế kỷ.","bia":{"src":"textures/ht/ht_anh_quang_truong_ba_dinh_ve_dem.jpg","credit":"Ảnh: Nguyễn Thanh Quang · CC BY-SA 3.0 · Wikimedia Commons"},"so_chu":1471},{"i":7,"tieu_de_bang":"Bảo tàng Hồ Chí Minh, Hà Nội","tieu_de":"Bảo tàng Hồ Chí Minh: bông sen trắng dâng Người tròn trăm tuổi","sapo":"Ngày 19 tháng 5 năm 1990, đúng 100 năm ngày sinh Chủ tịch Hồ Chí Minh, một công trình mang dáng bông sen trắng khổng lồ mở cửa ngay cạnh Lăng của Người. Từ đó, Bảo tàng Hồ Chí Minh trở thành nơi lưu giữ, nghiên cứu và giới thiệu toàn diện nhất về cuộc đời, sự nghiệp của Người — không chỉ bằng hiện vật, mà bằng chính ngôn ngữ của kiến trúc.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_ho_chi_minh_museum_the_pyramid.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"so_chu":1478},{"i":8,"tieu_de_bang":"Bên trong Bảo tàng Hồ Chí Minh","tieu_de":"Bên trong Bảo tàng: đi hết một cuộc đời qua tài liệu, hiện vật và nghệ thuật","sapo":"Bước vào Bảo tàng Hồ Chí Minh, khách tham quan lần lượt đi qua những chặng đường của một cuộc đời: từ làng Sen đến những bến cảng xa, từ hang Pác Bó đến Quảng trường Ba Đình. Tấm ảnh chụp năm 2008 ghi lại một góc không gian trưng bày bên trong — nơi hàng triệu người đã dừng chân, có người đứng thật lâu trước một bức thư viết tay, có người lặng đi trước một đôi dép cao su đã mòn.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_interiors_of_ho_chi_minh_museum.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"so_chu":1619},{"i":9,"tieu_de_bang":"“Học tập và làm theo” – Chỉ thị 05-CT/TW","tieu_de":"“Học tập và làm theo”: vì sao là tư tưởng, đạo đức và phong cách Hồ Chí Minh","sapo":"Câu chữ trên tấm bảng là tên gọi của một cuộc vận động lớn, được Bộ Chính trị xác định trong Chỉ thị 05-CT/TW năm 2016. Nhưng để đi tới đúng ba chữ “tư tưởng, đạo đức, phong cách”, cuộc vận động đã đi qua một chặng đường gần mười năm, qua ba văn bản khác nhau của Đảng. Điều khó nhất, như chính những người soạn thảo từng nhắc lại, không phải là học, mà là làm theo.","bia":{"src":"textures/bai/G17_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1524},{"i":10,"tieu_de_bang":"Lăng Chủ tịch Hồ Chí Minh","tieu_de":"Kiến trúc Lăng: ba lớp đá hoa cương và những vật liệu từ mọi miền đất nước","sapo":"Cao 21,6 mét, không cầu kỳ, không phô trương, Lăng Chủ tịch Hồ Chí Minh là một trong những công trình kiến trúc trang nghiêm bậc nhất của đất nước. Đá, gỗ quý, cát và cây xanh được đưa về từ khắp các miền để dựng nên công trình này, như một cách thể hiện tấm lòng của cả dân tộc hướng về Người. Phía sau vẻ tĩnh lặng ấy còn là một công việc thầm lặng, được duy trì đều đặn suốt nửa thế kỷ, để giữ cho Người luôn như đang yên giấc.","bia":{"src":"textures/bai/G17_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1630},{"i":11,"tieu_de_bang":"Quảng trường Ba Đình","tieu_de":"Quảng trường Ba Đình: nơi đất nước làm lễ trong những ngày trọng đại","sapo":"Không chỉ là nơi khai sinh nước Việt Nam Dân chủ Cộng hòa, Quảng trường Ba Đình còn chứng kiến những cuộc mít tinh, diễu binh và những buổi lễ trọng thể nhất của đất nước suốt tám mươi năm qua. Một lễ đài dựng tạm trong vài ngày của năm 1945, về sau lại trở thành nơi đặt một trong những công trình vĩnh cửu nhất của dân tộc.","bia":{"src":"textures/bai/G17_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"so_chu":1597}],"do_vat":[]}};
